-- Cancer question bank: exactly 500 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Cancer/Cancer-Overview.html
--   Notes/Cancer/All-Cancer-Overview.html
--   Notes/Cancer/Tumor-Grading.html
--   Notes/Cancer/Hematological-Cancers.html
--   Notes/Cancer/GI-Cancers.html
--   Notes/Cancer/Large-Organ-Cancers.html
--   Notes/Cancer/SCLC.html
--   Notes/Cancer/Female-Reproductive-Cancers.html
--   Notes/Cancer/Male-Reproductive-Cancers.html
--   Notes/Cancer/Skin-Cancer.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (500) exist after insert.
BEGIN;

CREATE TEMP TABLE _cancer_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _cancer_sources (source_key, source_path, category) VALUES
  ('overview', 'Notes/Cancer/Cancer-Overview.html', 'Cancer NCLEX seed v1 - cancer overview'),
  ('all_overview', 'Notes/Cancer/All-Cancer-Overview.html', 'Cancer NCLEX seed v1 - all cancer overview'),
  ('grading', 'Notes/Cancer/Tumor-Grading.html', 'Cancer NCLEX seed v1 - tumor grading'),
  ('heme', 'Notes/Cancer/Hematological-Cancers.html', 'Cancer NCLEX seed v1 - hematological cancers'),
  ('gi_cancers', 'Notes/Cancer/GI-Cancers.html', 'Cancer NCLEX seed v1 - gi cancers'),
  ('large_organ', 'Notes/Cancer/Large-Organ-Cancers.html', 'Cancer NCLEX seed v1 - large organ cancers'),
  ('sclc', 'Notes/Cancer/SCLC.html', 'Cancer NCLEX seed v1 - sclc'),
  ('female', 'Notes/Cancer/Female-Reproductive-Cancers.html', 'Cancer NCLEX seed v1 - female reproductive cancers'),
  ('male', 'Notes/Cancer/Male-Reproductive-Cancers.html', 'Cancer NCLEX seed v1 - male reproductive cancers'),
  ('skin', 'Notes/Cancer/Skin-Cancer.html', 'Cancer NCLEX seed v1 - skin cancer');

CREATE TEMP TABLE _cancer_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _cancer_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'cancer'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Cancer"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'cancer'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _cancer_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Cancer subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Cancer points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _cancer_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Cancer seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _cancer_seed_map) <> 10 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 10 note mappings, found %.',
      (SELECT count(*) FROM _cancer_seed_map);
  END IF;

  INSERT INTO _cancer_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _cancer_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('overview', 1, 'A client newly diagnosed with cancer asks the nurse, "What exactly is cancer?" Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"It is abnormal cell growth that does not respond to normal cell-cycle controls.\""}, {"id": "b", "text": "\"It is normal cell growth that happens faster than usual but stays in one organ.\""}, {"id": "c", "text": "\"It is a bacterial infection that causes cells to swell and multiply.\""}, {"id": "d", "text": "\"It is a process in which damaged cells stop dividing and slowly die off.\""}]'::jsonb, '["a"]', 'Cancer is uncontrolled, abnormal cell growth caused by DNA mutations; the cells do not respond to normal cell-cycle regulation. Cancer cells are not confined to one organ, because they can invade nearby tissue and spread to distant organs.'),
  ('overview', 2, 'A client with a long history of chronic hepatitis B infection asks about cancer risk. The nurse recognizes that this client has an increased risk for which cancer?', '[{"id": "a", "text": "Cervical cancer"}, {"id": "b", "text": "Bone sarcoma"}, {"id": "c", "text": "Liver cancer"}, {"id": "d", "text": "Skin melanoma"}]'::jsonb, '["c"]', 'Hepatitis B and C viruses are linked to liver cancer. HPV, not hepatitis B, is the virus linked to cervical cancer.'),
  ('overview', 3, 'A client with a chronic inflammatory condition asks why inflammation would raise the risk of cancer. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"Inflammation directly spreads cancer cells to distant organs.\""}, {"id": "b", "text": "\"Inflammation lowers platelet counts, which causes tumors to grow.\""}, {"id": "c", "text": "\"Inflammation makes cells grow more slowly and look more normal.\""}, {"id": "d", "text": "\"Repeated tissue damage and repair can promote DNA mutations.\""}]'::jsonb, '["d"]', 'Chronic inflammation causes a repeated tissue damage/repair cycle that promotes mutations. Slow-growing, normal-looking cells describe low-grade tumors, not the effect of inflammation.'),
  ('overview', 4, 'A client who takes immunosuppressive medication after an organ transplant asks why cancer screening is emphasized. The nurse explains that a weakened immune system increases cancer risk because it:', '[{"id": "a", "text": "allows mutated cells to escape immune surveillance."}, {"id": "b", "text": "causes cells to become well differentiated."}, {"id": "c", "text": "triggers radiation damage to healthy skin cells."}, {"id": "d", "text": "prevents tumors from invading nearby tissue."}]'::jsonb, '["a"]', 'Immunosuppression allows mutated cells to escape surveillance, so they can grow unchecked. Well-differentiated cells describe low-grade tumors and are unrelated to immune function.'),
  ('overview', 5, 'A biopsy report states that a client''s tumor arose from the epithelial cells lining the colon. The nurse recognizes this tumor type as which of the following?', '[{"id": "a", "text": "Sarcoma"}, {"id": "b", "text": "Lymphoma"}, {"id": "c", "text": "Carcinoma"}, {"id": "d", "text": "Melanoma"}]'::jsonb, '["c"]', 'Carcinomas originate from epithelial cells such as skin and organ linings, and colon cancer is an example. Sarcomas arise from connective tissue such as bone, muscle, and fat.'),
  ('overview', 6, 'An adolescent is diagnosed with osteosarcoma. The parent asks what type of tissue this cancer comes from. The nurse''s best response is that it originates in:', '[{"id": "a", "text": "epithelial cells that line organs."}, {"id": "b", "text": "connective tissue such as bone."}, {"id": "c", "text": "pigment-producing skin cells."}, {"id": "d", "text": "lymphocytes in the lymph nodes."}]'::jsonb, '["b"]', 'Osteosarcoma is a sarcoma, which originates in connective tissue such as bone, muscle, and fat. Epithelial cells give rise to carcinomas, not sarcomas.'),
  ('overview', 7, 'A client diagnosed with Hodgkin''s disease asks which body system the cancer started in. The nurse explains that this cancer type begins in the:', '[{"id": "a", "text": "blood-forming cells of the bone marrow."}, {"id": "b", "text": "melanocytes of the skin."}, {"id": "c", "text": "connective tissue of the muscles."}, {"id": "d", "text": "lymphocytes of the lymphatic system."}]'::jsonb, '["d"]', 'Hodgkin''s is a lymphoma, which originates in the lymphatic system (lymphocytes). Leukemias, not lymphomas, originate in blood and bone marrow.'),
  ('overview', 8, 'During a health screening, which client statement should the nurse recognize as a possible warning sign of cancer?', '[{"id": "a", "text": "\"I get sneezy every spring when the trees bloom.\""}, {"id": "b", "text": "\"I have a sore on my lip that has not healed in two months.\""}, {"id": "c", "text": "\"My muscles were sore for two days after a new workout.\""}, {"id": "d", "text": "\"I had a cold last month that cleared up within a week.\""}]'::jsonb, '["b"]', 'A sore that does not heal is one of the CAUTION warning signs of cancer. A cold that resolved within a week is self-limiting and is not one of the warning signs.'),
  ('overview', 9, 'The nurse reviews the CAUTION warning signs of cancer with a community group. Which participant statement indicates a need for further teaching?', '[{"id": "a", "text": "\"The C stands for a change in bowel or bladder habits.\""}, {"id": "b", "text": "\"The T stands for thickening or a lump in the breast or elsewhere.\""}, {"id": "c", "text": "\"The U stands for unusual bleeding or discharge.\""}, {"id": "d", "text": "\"The N stands for numbness or tingling in the hands or feet.\""}]'::jsonb, '["d"]', 'In the CAUTION mnemonic, N stands for nagging cough or hoarseness, so this statement needs correction. The other statements correctly describe C, T, and U.'),
  ('overview', 10, 'A client reports a mole on the forearm that has recently changed in appearance. Which CAUTION warning sign does this finding represent?', '[{"id": "a", "text": "Obvious change in wart or mole"}, {"id": "b", "text": "A sore that does not heal"}, {"id": "c", "text": "Thickening or lump in breast or elsewhere"}, {"id": "d", "text": "Unusual bleeding or discharge"}]'::jsonb, '["a"]', 'The O in CAUTION stands for an obvious change in a wart or mole. A sore that does not heal is the A of CAUTION and describes a non-healing wound, not a changing mole.'),
  ('overview', 11, 'A client tells the nurse that food has been "getting stuck" when swallowing for the past several weeks. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Reassure the client that this is a normal part of aging"}, {"id": "b", "text": "Advise the client to eat faster to keep food moving"}, {"id": "c", "text": "Report it as a possible cancer warning sign"}, {"id": "d", "text": "Tell the client to return only if weight gain occurs"}]'::jsonb, '["c"]', 'Indigestion or difficulty swallowing (dysphagia) is the I of the CAUTION warning signs and should be reported for evaluation. Dismissing it as normal aging delays evaluation of a recognized warning sign.'),
  ('overview', 12, 'A client''s pathology report lists the tumor as T2 N1 M0. The client asks what the "N" means. The nurse explains that N refers to:', '[{"id": "a", "text": "the number of tumors present."}, {"id": "b", "text": "involvement of the lymph nodes."}, {"id": "c", "text": "necrosis within the tumor."}, {"id": "d", "text": "the neutrophil count at diagnosis."}]'::jsonb, '["b"]', 'In the TNM system, T is tumor size, N is node involvement, and M is metastasis. N does not refer to the number of tumors.'),
  ('overview', 13, 'A client whose staging report includes "M0" asks whether this is good news. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, M0 means no distant metastasis was found.\""}, {"id": "b", "text": "\"No, M0 means the cancer has spread to distant organs.\""}, {"id": "c", "text": "\"Yes, M0 means the tumor has been fully removed.\""}, {"id": "d", "text": "\"No, M0 means the cells are the most aggressive grade.\""}]'::jsonb, '["a"]', 'M0 means no distant metastasis, which is a positive indicator. M1, not M0, indicates metastatic disease.'),
  ('overview', 14, 'A client is told the cancer is stage IV. The nurse understands that this stage indicates which of the following?', '[{"id": "a", "text": "Cancer in situ with no invasion"}, {"id": "b", "text": "A small tumor that remains localized"}, {"id": "c", "text": "Distant metastasis, the most advanced stage"}, {"id": "d", "text": "Local spread without lymph node involvement"}]'::jsonb, '["c"]', 'Stage IV indicates distant metastasis and is the most advanced stage. Stage 0 is in situ with no invasion.'),
  ('overview', 15, 'A client''s report describes the cancer as stage 0. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The cancer has spread to distant organs.\""}, {"id": "b", "text": "\"The cancer involves many lymph nodes.\""}, {"id": "c", "text": "\"The cancer has spread locally to nearby tissue.\""}, {"id": "d", "text": "\"The cancer is in situ and has not invaded tissue.\""}]'::jsonb, '["d"]', 'Stage 0 is in situ, meaning there is no invasion. Extensive lymph node involvement describes stage III.'),
  ('overview', 16, 'A pathology report describes a client''s tumor as high-grade and poorly differentiated. The nurse anticipates that these cancer cells are:', '[{"id": "a", "text": "slow-growing and similar to normal cells."}, {"id": "b", "text": "fast-growing and abnormal in appearance."}, {"id": "c", "text": "confined to the original site without invasion."}, {"id": "d", "text": "unable to spread to the lymph nodes."}]'::jsonb, '["b"]', 'High-grade (poorly differentiated) cells are fast-growing and look abnormal. Slow-growing cells that look like normal cells describe a low-grade, well-differentiated tumor.'),
  ('overview', 17, 'A client asks the nurse, "What is the difference between my cancer''s stage and its grade?" Which response is correct?', '[{"id": "a", "text": "\"Stage shows how aggressive the cells are; grade shows how far it spread.\""}, {"id": "b", "text": "\"Stage and grade both describe the size of the original tumor only.\""}, {"id": "c", "text": "\"Stage shows how far it has spread; grade shows how aggressive the cells are.\""}, {"id": "d", "text": "\"Stage is based on blood tests; grade is based on a mammogram.\""}]'::jsonb, '["c"]', 'Staging describes how far the cancer has spread, while grading describes how aggressive the cells are. Option a reverses the two concepts.'),
  ('overview', 18, 'A client was diagnosed with stage II cancer two years ago, and the disease has now progressed. The client asks, "Does that mean my stage changes now?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Your stage is automatically changed to stage IV.\""}, {"id": "b", "text": "\"Your stage drops to stage 0 once treatment starts.\""}, {"id": "c", "text": "\"Your stage stays as it was assigned at diagnosis.\""}, {"id": "d", "text": "\"Your stage is reassigned each time a blood test is done.\""}]'::jsonb, '["c"]', 'Staging does not change after the initial diagnosis, even if the disease progresses. Automatically reassigning the stage to IV contradicts this principle.'),
  ('overview', 19, 'A CT scan shows a suspicious mass in a client''s abdomen. The client asks which test will confirm whether it is cancer. The nurse identifies which test as the gold standard?', '[{"id": "a", "text": "Biopsy of the tissue"}, {"id": "b", "text": "Tumor marker blood test"}, {"id": "c", "text": "Repeat CT scan"}, {"id": "d", "text": "PET scan"}]'::jsonb, '["a"]', 'A biopsy is the gold standard because the tissue sample confirms the cancer type and grade. CT, MRI, and PET scans are used for staging and identifying spread rather than confirming the diagnosis.'),
  ('overview', 20, 'A client being treated for ovarian cancer has serial blood work ordered to follow a tumor marker. The nurse expects which tumor marker to be monitored?', '[{"id": "a", "text": "PSA"}, {"id": "b", "text": "CA-125"}, {"id": "c", "text": "AFP"}, {"id": "d", "text": "CA 19-9"}]'::jsonb, '["b"]', 'CA-125 is the tumor marker for ovarian cancer. CA 19-9 is the marker for pancreatic cancer.'),
  ('overview', 21, 'A client whose cancer was confirmed by biopsy is scheduled for a PET scan. The client asks why another test is needed. The nurse explains that the scan is used to:', '[{"id": "a", "text": "confirm the cancer type and grade."}, {"id": "b", "text": "determine the stage and identify spread."}, {"id": "c", "text": "screen for cervical cancer."}, {"id": "d", "text": "measure the platelet count."}]'::jsonb, '["b"]', 'CT, MRI, and PET scans are used for staging and identifying spread. Confirming cancer type and grade is the purpose of a biopsy.'),
  ('overview', 22, 'A 46-year-old client at average risk asks about colorectal cancer screening. Which recommendation by the nurse is correct?', '[{"id": "a", "text": "Colonoscopy every 10 years, beginning at age 45"}, {"id": "b", "text": "Colonoscopy every year, beginning at age 60"}, {"id": "c", "text": "Colonoscopy every 3 years, beginning at age 21"}, {"id": "d", "text": "Colonoscopy only after rectal bleeding occurs"}]'::jsonb, '["a"]', 'Colonoscopy is the gold standard for colorectal screening and is done every 10 years starting at age 45. Waiting for bleeding defeats the purpose of screening.'),
  ('overview', 23, 'A client with an incurable abdominal tumor is scheduled for surgery to relieve a bowel obstruction. The client''s spouse asks if the surgery will cure the cancer. The nurse explains that the goal of this surgery is to:', '[{"id": "a", "text": "remove the entire tumor to cure the cancer."}, {"id": "b", "text": "obtain tissue to determine the cancer stage."}, {"id": "c", "text": "relieve symptoms such as the obstruction."}, {"id": "d", "text": "place radioactive seeds inside the tumor."}]'::jsonb, '["c"]', 'Palliative surgery relieves symptoms such as pain or obstruction when the cancer is not curable. Removing the tumor entirely with the goal of cure describes curative surgery.'),
  ('overview', 24, 'A client is receiving chemotherapy. When reviewing the complete blood count, which findings does the nurse expect as a result of myelosuppression?', '[{"id": "a", "text": "Increased WBCs, decreased RBCs, and increased platelets"}, {"id": "b", "text": "Decreased WBCs, decreased RBCs, and decreased platelets"}, {"id": "c", "text": "Increased WBCs, increased RBCs, and decreased platelets"}, {"id": "d", "text": "Decreased WBCs, increased RBCs, and increased platelets"}]'::jsonb, '["b"]', 'Myelosuppression from chemotherapy decreases WBCs (neutropenia), RBCs (anemia), and platelets (thrombocytopenia). Any option with an increased count does not reflect myelosuppression.'),
  ('overview', 25, 'A client is scheduled to receive chemotherapy at 1000. Ondansetron is prescribed. Which action by the nurse requires correction by the charge nurse?', '[{"id": "a", "text": "Giving the ondansetron before the chemotherapy begins"}, {"id": "b", "text": "Monitoring the CBC for the expected nadir"}, {"id": "c", "text": "Encouraging small, frequent meals for nausea"}, {"id": "d", "text": "Holding ondansetron until the client starts vomiting"}]'::jsonb, '["d"]', 'Antiemetics such as ondansetron should be given before chemotherapy, so waiting until vomiting starts requires correction. Giving ondansetron before chemotherapy is the correct practice.'),
  ('overview', 26, 'A client receiving chemotherapy is tearful about losing hair and asks if it will ever grow back. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"Hair loss from chemotherapy is temporary.\""}, {"id": "b", "text": "\"Hair loss from chemotherapy is permanent.\""}, {"id": "c", "text": "\"Hair loss means the treatment is not working.\""}, {"id": "d", "text": "\"Hair loss means the cancer has metastasized.\""}]'::jsonb, '["a"]', 'Alopecia is a chemotherapy side effect, and the nurse should reassure the client that it is temporary. Telling the client it is permanent is inaccurate and adds to body-image distress.'),
  ('overview', 27, 'The nurse teaches a client with chemotherapy-induced mucositis about oral care. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will brush my teeth gently with a soft toothbrush.\""}, {"id": "b", "text": "\"I will keep up with oral care to help the mouth sores.\""}, {"id": "c", "text": "\"I will rinse with an alcohol-based mouthwash after meals.\""}, {"id": "d", "text": "\"I understand mucositis means painful sores in my mouth.\""}]'::jsonb, '["c"]', 'Clients with mucositis should avoid alcohol-based mouthwash, so this statement needs correction. Using a soft toothbrush is the correct oral care.'),
  ('overview', 28, 'A client receiving chemotherapy reports severe fatigue. Which instruction by the nurse is most appropriate?', '[{"id": "a", "text": "\"Finish all of your chores early in the day so you can get them done.\""}, {"id": "b", "text": "\"Pace your activities and plan rest periods to conserve energy.\""}, {"id": "c", "text": "\"Increase strenuous exercise each day to build up your energy.\""}, {"id": "d", "text": "\"Avoid resting during the day so you will sleep better at night.\""}]'::jsonb, '["b"]', 'Fatigue management includes pacing activities, prioritizing rest, and conserving energy. Doing all chores at once or adding strenuous activity works against energy conservation.'),
  ('overview', 29, 'The nurse teaches a client about skin care during external beam radiation therapy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep the treated area out of direct sunlight.\""}, {"id": "b", "text": "\"I will protect the skin in the radiation field.\""}, {"id": "c", "text": "\"I will avoid harsh soaps on the treated area.\""}, {"id": "d", "text": "\"I will sunbathe to help the treated skin heal.\""}]'::jsonb, '["d"]', 'Skin in the external beam field must be protected with no harsh soaps and no sun exposure, so sunbathing requires correction. Keeping the area out of the sun is correct teaching.'),
  ('overview', 30, 'A client has a radioactive implant placed near a tumor (brachytherapy). Which action by the nurse is appropriate?', '[{"id": "a", "text": "Encourage family members to stay at the bedside for long visits"}, {"id": "b", "text": "Limit visitor time and use distance and shielding precautions"}, {"id": "c", "text": "Remove shielding during care so tasks can be completed faster"}, {"id": "d", "text": "Assign the client a shared room to reduce feelings of isolation"}]'::jsonb, '["b"]', 'Brachytherapy requires radiation precautions: limit visitor time, distance, and shielding. Long bedside visits increase exposure time and violate these precautions.'),
  ('overview', 31, 'A client asks how brachytherapy differs from external beam radiation. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"Brachytherapy places radioactive seeds inside or near the tumor.\""}, {"id": "b", "text": "\"Brachytherapy aims a focused beam from outside the body.\""}, {"id": "c", "text": "\"Brachytherapy uses donor stem cells to rebuild bone marrow.\""}, {"id": "d", "text": "\"Brachytherapy blocks hormones that feed the tumor.\""}]'::jsonb, '["a"]', 'Brachytherapy uses radioactive seeds or implants placed inside or near the tumor. Focused radiation from outside the body describes external beam radiation.'),
  ('overview', 32, 'A client receiving pembrolizumab for melanoma develops new, frequent diarrhea. The nurse recognizes this finding as a possible:', '[{"id": "a", "text": "sign of graft-versus-host disease from donor cells."}, {"id": "b", "text": "result of hormone deprivation from the drug."}, {"id": "c", "text": "skin reaction from external beam radiation."}, {"id": "d", "text": "immune-related reaction such as colitis."}]'::jsonb, '["d"]', 'Immunotherapy such as pembrolizumab can cause immune-related reactions including colitis, pneumonitis, and endocrinopathies. GVHD is a risk of allogeneic stem cell transplant, not of pembrolizumab.'),
  ('overview', 33, 'A client with estrogen receptor-positive (ER+) breast cancer is prescribed tamoxifen. The client asks why. The nurse explains that this medication works by:', '[{"id": "a", "text": "killing all rapidly dividing cells in the bone marrow."}, {"id": "b", "text": "placing radioactive material next to the tumor."}, {"id": "c", "text": "blocking hormones that feed hormone-sensitive tumors."}, {"id": "d", "text": "replacing damaged marrow with the client''s own cells."}]'::jsonb, '["c"]', 'Tamoxifen is a hormone therapy for ER+ breast cancer that blocks or lowers hormones feeding hormone-sensitive tumors. Placing radioactive material near the tumor describes brachytherapy.'),
  ('overview', 34, 'A client with prostate cancer begins leuprolide therapy. Which statement by the client indicates understanding of the medication''s purpose?', '[{"id": "a", "text": "\"It deprives the tumor of the androgens that feed it.\""}, {"id": "b", "text": "\"It boosts my immune system to attack the tumor.\""}, {"id": "c", "text": "\"It prevents nausea before my chemotherapy.\""}, {"id": "d", "text": "\"It is used to screen my blood for prostate cancer.\""}]'::jsonb, '["a"]', 'Leuprolide is a hormone therapy for prostate cancer that works by androgen deprivation. Preventing nausea before chemotherapy is the role of ondansetron.'),
  ('overview', 35, 'Two weeks after an allogeneic stem cell transplant, a client develops a skin rash, diarrhea, and abnormal liver studies. The nurse should suspect which complication?', '[{"id": "a", "text": "Immune-related colitis from PD-1 therapy"}, {"id": "b", "text": "Radiation skin damage from brachytherapy"}, {"id": "c", "text": "Expected alopecia from chemotherapy"}, {"id": "d", "text": "Graft-versus-host disease"}]'::jsonb, '["d"]', 'Allogeneic (donor) transplants carry a risk of graft-versus-host disease, which presents with rash, liver damage, and GI involvement. PD-1 related colitis is linked to immunotherapy such as pembrolizumab, not to a donor transplant.'),
  ('overview', 36, 'A client is preparing for an autologous stem cell transplant. Which client statement indicates correct understanding?', '[{"id": "a", "text": "\"Because these are donor cells, I am at high risk for graft-versus-host disease.\""}, {"id": "b", "text": "\"Because these are my own cells, the risk of rejection is lower.\""}, {"id": "c", "text": "\"Because these are my own cells, I will not need any blood counts.\""}, {"id": "d", "text": "\"Because these are donor cells, I will need radiation seeds placed.\""}]'::jsonb, '["b"]', 'Autologous transplant uses the client''s own cells and carries less rejection risk. Donor cells and GVHD risk describe an allogeneic transplant.'),
  ('overview', 37, 'A client receiving chemotherapy has an absolute neutrophil count (ANC) of 400. Which nursing concern is the priority?', '[{"id": "a", "text": "Risk for infection"}, {"id": "b", "text": "Disturbed body image"}, {"id": "c", "text": "Knowledge deficit about screening"}, {"id": "d", "text": "Risk for skin damage from radiation"}]'::jsonb, '["a"]', 'An ANC below 500 is severe neutropenia, and infection risk is the number-one nursing priority. Body image concerns are important but do not take priority over infection risk.'),
  ('overview', 38, 'A visitor arrives with several items for a client who has severe neutropenia. Which item should the nurse ask the visitor to take home?', '[{"id": "a", "text": "A greeting card"}, {"id": "b", "text": "A paperback book"}, {"id": "c", "text": "A vase of fresh flowers"}, {"id": "d", "text": "A framed family photo"}]'::jsonb, '["c"]', 'Neutropenic precautions include no fresh flowers. Cards, books, and photos are not restricted by these precautions.'),
  ('overview', 39, 'The nurse reviews meal choices with a client who has severe neutropenia. Which menu item should the nurse advise the client to avoid?', '[{"id": "a", "text": "Baked chicken breast"}, {"id": "b", "text": "Steamed rice"}, {"id": "c", "text": "Cooked green beans"}, {"id": "d", "text": "Fresh raw garden salad"}]'::jsonb, '["d"]', 'Clients with neutropenia should avoid raw produce, so a raw salad is not appropriate. The other items are cooked foods, which are not restricted.'),
  ('overview', 40, 'A client with severe neutropenia has an oral temperature of 38.2°C (100.8°F). Which action should the nurse take first?', '[{"id": "a", "text": "Recheck the temperature in 4 hours"}, {"id": "b", "text": "Report the temperature to the provider immediately"}, {"id": "c", "text": "Encourage fluids and reassess the next morning"}, {"id": "d", "text": "Document the finding as an expected chemo effect"}]'::jsonb, '["b"]', 'In neutropenia, a temperature of 38°C (100.4°F) or higher must be reported immediately. Waiting hours to recheck delays care for possible infection.'),
  ('overview', 41, 'The charge nurse is assigning rooms. Which room assignment is most appropriate for a client with severe neutropenia?', '[{"id": "a", "text": "A semi-private room with a client who has pneumonia"}, {"id": "b", "text": "A semi-private room near the nurses'' station"}, {"id": "c", "text": "A private room"}, {"id": "d", "text": "A shared room with a client recovering from surgery"}]'::jsonb, '["c"]', 'Neutropenic precautions call for a private room to reduce infection risk. Sharing a room, especially with a client who has an infection, increases exposure.'),
  ('overview', 42, 'A client receiving chemotherapy has a platelet count of 18,000/mm³. How should the nurse interpret this result?', '[{"id": "a", "text": "It is an emergency-level bleeding risk to report"}, {"id": "b", "text": "It is a mild bleeding risk needing weekly checks"}, {"id": "c", "text": "It indicates severe neutropenia and infection risk"}, {"id": "d", "text": "It is within the expected range after chemotherapy"}]'::jsonb, '["a"]', 'Platelets below 50,000 indicate bleeding risk, and below 20,000 is an emergency. Severe neutropenia is defined by an ANC below 500, not by the platelet count.'),
  ('overview', 43, 'A client with thrombocytopenia has a platelet count of 40,000/mm³. Which prescription should the nurse question?', '[{"id": "a", "text": "Use of an electric razor for shaving"}, {"id": "b", "text": "Ondansetron before chemotherapy"}, {"id": "c", "text": "A soft toothbrush for oral care"}, {"id": "d", "text": "An intramuscular injection of medication"}]'::jsonb, '["d"]', 'Bleeding precautions for thrombocytopenia include avoiding IM injections. An electric razor and a soft toothbrush are recommended bleeding precautions.'),
  ('overview', 44, 'The nurse teaches a client with a low platelet count about bleeding precautions at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will report any new bruising to my provider.\""}, {"id": "b", "text": "\"I will keep using my razor blade to shave.\""}, {"id": "c", "text": "\"I will use a soft toothbrush to clean my teeth.\""}, {"id": "d", "text": "\"I will report any bleeding from my gums.\""}]'::jsonb, '["b"]', 'Clients with thrombocytopenia should use an electric razor, so continuing to use a razor blade requires further teaching. Reporting bruising and bleeding is correct.'),
  ('overview', 45, 'A client received chemotherapy on day 1 of the cycle. The nurse anticipates the client''s blood counts will reach their lowest point (nadir) during which time frame?', '[{"id": "a", "text": "Within 24 hours after the infusion"}, {"id": "b", "text": "Days 2 to 4 after chemotherapy"}, {"id": "c", "text": "Days 7 to 14 after chemotherapy"}, {"id": "d", "text": "Days 30 to 45 after chemotherapy"}]'::jsonb, '["c"]', 'The nadir, the lowest blood count, usually occurs 7 to 14 days after chemotherapy. Counts are not expected to bottom out within 24 hours.'),
  ('overview', 46, 'A client receiving chemotherapy reports nausea and a poor appetite. Which dietary instruction by the nurse is most appropriate?', '[{"id": "a", "text": "\"Eat one large meal each evening when nausea is less.\""}, {"id": "b", "text": "\"Eat small, frequent meals that are high in protein.\""}, {"id": "c", "text": "\"Skip meals on treatment days to prevent vomiting.\""}, {"id": "d", "text": "\"Eat three large meals that are low in protein.\""}]'::jsonb, '["b"]', 'Nutrition interventions include small frequent meals and a high-protein diet, along with antiemetics. Large or skipped meals and low protein contradict these interventions.'),
  ('overview', 47, 'A parent asks the nurse which cancers the HPV vaccine (Gardasil) helps prevent. Which response is correct?', '[{"id": "a", "text": "\"Liver cancer and colorectal cancer\""}, {"id": "b", "text": "\"Breast cancer and endometrial cancer\""}, {"id": "c", "text": "\"Skin cancers such as melanoma\""}, {"id": "d", "text": "\"Cervical, penile, and oropharyngeal cancers\""}]'::jsonb, '["d"]', 'The HPV vaccine targets cervical, penile, and oropharyngeal cancers. Liver cancer is targeted by the hepatitis B vaccine, not the HPV vaccine.'),
  ('overview', 48, 'The nurse teaches a client about reducing skin cancer risk. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will use a tanning bed instead of lying in the sun.\""}, {"id": "b", "text": "\"I will use a sunscreen that is SPF 30 or higher.\""}, {"id": "c", "text": "\"I will have regular skin exams as recommended.\""}, {"id": "d", "text": "\"Sunscreen helps lower my risk of melanoma.\""}]'::jsonb, '["a"]', 'Skin cancer prevention includes sunscreen SPF 30+ and avoiding tanning beds, so using a tanning bed needs correction. Using SPF 30 or higher sunscreen is correct.'),
  ('overview', 49, 'A client who smokes asks which cancers quitting smoking would help prevent. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Only lung cancer is linked to smoking.\""}, {"id": "b", "text": "\"Lung, oral, and bladder cancers, among others.\""}, {"id": "c", "text": "\"Mainly skin cancers such as melanoma.\""}, {"id": "d", "text": "\"Mainly bone and muscle sarcomas.\""}]'::jsonb, '["b"]', 'Not smoking targets lung, oral, bladder, cervical, esophageal, and pancreatic cancers. Saying only lung cancer is linked to smoking is too narrow.'),
  ('overview', 50, 'A client with a strong family history of colorectal cancer asks about diet changes to lower the risk. Which diet should the nurse recommend?', '[{"id": "a", "text": "Low-fiber, high-fat diet"}, {"id": "b", "text": "High-fiber, high-fat diet"}, {"id": "c", "text": "High-fiber, low-fat diet"}, {"id": "d", "text": "Low-fiber, low-fat diet"}]'::jsonb, '["c"]', 'A high-fiber, low-fat diet is the prevention intervention that targets colorectal cancer. A low-fiber, high-fat diet is the reverse of this recommendation.'),
  ('all_overview', 1, 'A client reports frequent infections, fatigue, easy bruising, bone pain, and night sweats over the past month. The nurse recognizes that these findings are most consistent with which cancer?', '[{"id": "a", "text": "Leukemia"}, {"id": "b", "text": "Gastric cancer"}, {"id": "c", "text": "Testicular cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["a"]', 'Leukemia arises from WBCs in the bone marrow and presents with frequent infections, fatigue/anemia, easy bruising/bleeding, bone pain, and fever/night sweats. Gastric cancer presents with early satiety, epigastric pain, and weight loss instead.'),
  ('all_overview', 2, 'An occupational health nurse reviews the history of a factory worker with many years of benzene exposure. The worker is at increased risk for which cancer?', '[{"id": "a", "text": "Penile cancer"}, {"id": "b", "text": "Gastric cancer"}, {"id": "c", "text": "Leukemia"}, {"id": "d", "text": "Endometrial cancer"}]'::jsonb, '["c"]', 'Benzene exposure is a listed risk factor for leukemia, along with radiation, chemotherapy history, and Down syndrome. The top risk factor for gastric cancer is H. pylori, not benzene.'),
  ('all_overview', 3, 'A client newly diagnosed with leukemia asks about the order of the chemotherapy phases. Which sequence should the nurse describe?', '[{"id": "a", "text": "Maintenance, then induction, then consolidation"}, {"id": "b", "text": "Induction, then consolidation, then maintenance"}, {"id": "c", "text": "Consolidation, then induction, then maintenance"}, {"id": "d", "text": "Induction, then maintenance, then consolidation"}]'::jsonb, '["b"]', 'Leukemia chemotherapy proceeds from induction to consolidation to maintenance. Starting with maintenance reverses the order.'),
  ('all_overview', 4, 'A client with chronic myeloid leukemia (CML) is starting targeted therapy. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Rituximab"}, {"id": "b", "text": "Bortezomib"}, {"id": "c", "text": "Sorafenib"}, {"id": "d", "text": "Imatinib"}]'::jsonb, '["d"]', 'Imatinib is the targeted therapy for CML. Rituximab targets non-Hodgkin''s lymphoma, and bortezomib is used for multiple myeloma.'),
  ('all_overview', 5, 'A client reports painless swollen lymph nodes, night sweats, unexplained weight loss, fatigue, and itching without a rash. The nurse suspects which cancer?', '[{"id": "a", "text": "Lymphoma"}, {"id": "b", "text": "Multiple myeloma"}, {"id": "c", "text": "Endometrial cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["a"]', 'Lymphoma presents with painless swollen lymph nodes, night sweats, unexplained weight loss, fatigue, and pruritus without rash. Multiple myeloma presents with CRAB findings rather than painless lymph node swelling.'),
  ('all_overview', 6, 'A client tells the nurse, "I found a lump in my neck, but it doesn''t hurt, so it''s probably nothing." Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"Painless lumps are rarely a concern, so you can just watch it.\""}, {"id": "b", "text": "\"If it is still there in a year, mention it at your next checkup.\""}, {"id": "c", "text": "\"A painless lump needs to be evaluated, which may include a biopsy.\""}, {"id": "d", "text": "\"Warm compresses should make the lump go away within a week.\""}]'::jsonb, '["c"]', 'A painless lump anywhere is considered cancer until proven otherwise; the nurse should not reassure the client, and a biopsy is indicated. Telling the client it is rarely a concern is false reassurance.'),
  ('all_overview', 7, 'A client living with HIV asks which cancer the condition places them at higher risk for. The nurse identifies which cancer?', '[{"id": "a", "text": "Endometrial cancer"}, {"id": "b", "text": "Lymphoma"}, {"id": "c", "text": "Testicular cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["b"]', 'HIV, EBV, and immunosuppression are risk factors for lymphoma. Endometrial cancer risk is linked to unopposed estrogen and obesity, not HIV.'),
  ('all_overview', 8, 'A client with lymphoma is starting the CHOP regimen. Which medication should the nurse expect to be included in this regimen?', '[{"id": "a", "text": "Imatinib"}, {"id": "b", "text": "Bortezomib"}, {"id": "c", "text": "Gemcitabine"}, {"id": "d", "text": "Prednisone"}]'::jsonb, '["d"]', 'CHOP consists of cyclophosphamide, doxorubicin, vincristine, and prednisone. Gemcitabine is the chemotherapy listed for pancreatic cancer, not part of CHOP.'),
  ('all_overview', 9, 'A lymph node biopsy report shows Reed-Sternberg cells with an "owl-eye" appearance. The nurse recognizes that this finding indicates which diagnosis?', '[{"id": "a", "text": "Hodgkin''s lymphoma"}, {"id": "b", "text": "Non-Hodgkin''s lymphoma"}, {"id": "c", "text": "Multiple myeloma"}, {"id": "d", "text": "Chronic myeloid leukemia"}]'::jsonb, '["a"]', 'Reed-Sternberg cells with an owl-eye appearance identify Hodgkin''s lymphoma. Non-Hodgkin''s lymphoma has no Reed-Sternberg cells.'),
  ('all_overview', 10, 'The nurse teaches a client about the differences between Hodgkin''s and non-Hodgkin''s lymphoma (NHL). Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Hodgkin''s lymphoma has Reed-Sternberg cells.\""}, {"id": "b", "text": "\"Non-Hodgkin''s lymphoma is the more common type.\""}, {"id": "c", "text": "\"Non-Hodgkin''s has a better prognosis than Hodgkin''s.\""}, {"id": "d", "text": "\"Both types can cause fever, night sweats, and weight loss.\""}]'::jsonb, '["c"]', 'NHL is more common and has a worse prognosis overall, while Hodgkin''s has the better prognosis, so this statement is incorrect. The statement that Hodgkin''s has Reed-Sternberg cells is accurate.'),
  ('all_overview', 11, 'A client with lymphoma is being assessed for "B symptoms." Which group of findings should the nurse document as B symptoms?', '[{"id": "a", "text": "Itchy rash, joint pain, and hair loss"}, {"id": "b", "text": "Fever, night sweats, and >10% weight loss"}, {"id": "c", "text": "Dysphagia, hoarseness, and chronic cough"}, {"id": "d", "text": "Bloating, pelvic pressure, and urinary frequency"}]'::jsonb, '["b"]', 'B symptoms in both Hodgkin''s and non-Hodgkin''s lymphoma are fever, night sweats, and weight loss greater than 10% of body weight. Bloating, pelvic pressure, and frequent urination are ovarian cancer symptoms.'),
  ('all_overview', 12, 'A client with multiple myeloma is prescribed bortezomib and asks what type of drug it is. The nurse explains that bortezomib is a:', '[{"id": "a", "text": "PD-1 inhibitor."}, {"id": "b", "text": "androgen deprivation agent."}, {"id": "c", "text": "HER2-targeted antibody."}, {"id": "d", "text": "proteasome inhibitor."}]'::jsonb, '["d"]', 'Bortezomib is a proteasome inhibitor used for multiple myeloma. Pembrolizumab, not bortezomib, is the PD-1 agent.'),
  ('all_overview', 13, 'A 70-year-old client presents with bone pain, anemia, hypercalcemia, and renal failure. The nurse recognizes that this cluster of findings is classic for which cancer?', '[{"id": "a", "text": "Multiple myeloma"}, {"id": "b", "text": "Hodgkin''s lymphoma"}, {"id": "c", "text": "Pancreatic cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["a"]', 'Hypercalcemia, renal failure, anemia, and bone pain form the CRAB findings of multiple myeloma. Pancreatic cancer classically presents with jaundice, new-onset diabetes, and back/abdominal pain.'),
  ('all_overview', 14, 'A client with esophageal cancer describes how swallowing has changed over several months. Which pattern does the nurse expect the client to report?', '[{"id": "a", "text": "Trouble with liquids first, then with solids"}, {"id": "b", "text": "Trouble with solids first, then with liquids"}, {"id": "c", "text": "Sudden trouble with solids and liquids at once"}, {"id": "d", "text": "Trouble with liquids only, never with solids"}]'::jsonb, '["b"]', 'Esophageal cancer causes progressive dysphagia that starts with solids and progresses to liquids. Difficulty with liquids first reverses this pattern.'),
  ('all_overview', 15, 'A client has a long history of GERD and has been diagnosed with Barrett''s esophagus. The nurse recognizes that this client is at increased risk for which cancer?', '[{"id": "a", "text": "Esophageal cancer"}, {"id": "b", "text": "Pancreatic cancer"}, {"id": "c", "text": "Colorectal cancer"}, {"id": "d", "text": "Liver cancer"}]'::jsonb, '["a"]', 'GERD/Barrett''s esophagus is a top risk factor for esophageal cancer. Pancreatic cancer risk factors include smoking, BRCA mutations, chronic pancreatitis, and obesity, not Barrett''s esophagus.'),
  ('all_overview', 16, 'A client is being evaluated for early satiety, epigastric pain, and weight loss. Which finding in the client''s history is the number-one risk factor for the suspected cancer?', '[{"id": "a", "text": "BRCA1 mutation"}, {"id": "b", "text": "HPV infection"}, {"id": "c", "text": "Cryptorchidism"}, {"id": "d", "text": "H. pylori infection"}]'::jsonb, '["d"]', 'Early satiety, epigastric pain, and weight loss suggest gastric cancer, for which H. pylori is the number-one risk factor. HPV is the top risk factor for cervical cancer, not gastric cancer.'),
  ('all_overview', 17, 'A 60-year-old client reports a recent change in bowel habits and has iron-deficiency anemia. Which additional finding would the nurse expect if colorectal cancer is present?', '[{"id": "a", "text": "Clay-colored stools"}, {"id": "b", "text": "Early satiety"}, {"id": "c", "text": "Pencil-thin stools"}, {"id": "d", "text": "Postcoital bleeding"}]'::jsonb, '["c"]', 'Colorectal cancer presents with a change in bowel habits, hematochezia/melena, pencil-thin stools, and iron-deficiency anemia. Clay-colored stools are a finding of pancreatic cancer.'),
  ('all_overview', 18, 'A client had a colectomy for colorectal cancer. Which tumor marker does the nurse expect to be used to monitor this client?', '[{"id": "a", "text": "AFP"}, {"id": "b", "text": "CEA"}, {"id": "c", "text": "CA 19-9"}, {"id": "d", "text": "CA-125"}]'::jsonb, '["b"]', 'CEA is the tumor marker for colorectal cancer. AFP is the marker for liver cancer and CA 19-9 is the marker for pancreatic cancer.'),
  ('all_overview', 19, 'The nurse teaches a community group about colorectal cancer risk factors. Which participant statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Eating a high-fiber, low-fat diet raises my risk.\""}, {"id": "b", "text": "\"Having inflammatory bowel disease raises my risk.\""}, {"id": "c", "text": "\"Being obese raises my risk of colorectal cancer.\""}, {"id": "d", "text": "\"A family history of colorectal cancer raises my risk.\""}]'::jsonb, '["a"]', 'A low-fiber, high-fat diet, not a high-fiber, low-fat diet, is a colorectal cancer risk factor, so this statement needs correction. IBD, obesity, and family history are all listed risk factors.'),
  ('all_overview', 20, 'A client is beginning chemotherapy for colorectal cancer. Which chemotherapy agent does the nurse anticipate?', '[{"id": "a", "text": "Gemcitabine"}, {"id": "b", "text": "Cisplatin with etoposide"}, {"id": "c", "text": "5-FU"}, {"id": "d", "text": "Paclitaxel"}]'::jsonb, '["c"]', '5-FU chemotherapy is a key treatment for colorectal cancer. Gemcitabine is the chemotherapy for pancreatic cancer.'),
  ('all_overview', 21, 'A client with cirrhosis develops jaundice, right upper quadrant pain, ascites, and weight loss. Which tumor marker should the nurse expect to be elevated if liver cancer is present?', '[{"id": "a", "text": "CEA"}, {"id": "b", "text": "PSA"}, {"id": "c", "text": "CA-125"}, {"id": "d", "text": "AFP"}]'::jsonb, '["d"]', 'Hepatocellular carcinoma presents with jaundice, RUQ pain, ascites, fatigue, and weight loss, and its tumor marker is AFP. CEA is the marker for colorectal cancer.'),
  ('all_overview', 22, 'A client asks whether any food-related exposure increases the risk of liver cancer. Which exposure should the nurse identify?', '[{"id": "a", "text": "Smoked and cured foods"}, {"id": "b", "text": "Aflatoxin from food mold"}, {"id": "c", "text": "A low-fiber, high-fat diet"}, {"id": "d", "text": "Unopposed estrogen intake"}]'::jsonb, '["b"]', 'Aflatoxin from food mold is a risk factor for hepatocellular carcinoma. Smoked and cured foods are listed as a risk factor for gastric cancer, not liver cancer.'),
  ('all_overview', 23, 'A client presents with jaundice, new-onset diabetes mellitus, and back pain. The nurse recognizes that this combination of findings most strongly suggests which cancer?', '[{"id": "a", "text": "Gastric cancer"}, {"id": "b", "text": "Colorectal cancer"}, {"id": "c", "text": "Pancreatic cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["c"]', 'Jaundice plus new-onset diabetes plus back/abdominal pain is the classic clue for pancreatic cancer. Gastric cancer presents with early satiety, epigastric pain, weight loss, and occult GI bleeding.'),
  ('all_overview', 24, 'A client with suspected pancreatic cancer has painless jaundice. Which additional urine and stool findings does the nurse expect?', '[{"id": "a", "text": "Pale urine and black, tarry stools"}, {"id": "b", "text": "Dark urine and clay-colored stools"}, {"id": "c", "text": "Clear urine and pencil-thin stools"}, {"id": "d", "text": "Bloody urine and frequent loose stools"}]'::jsonb, '["b"]', 'Pancreatic cancer presents with painless jaundice, dark urine, and clay-colored stools. Pencil-thin stools are a finding of colorectal cancer.'),
  ('all_overview', 25, 'The nurse is caring for a client recovering from a Whipple procedure (pancreaticoduodenectomy). The nurse recognizes that this surgery is most often performed for which cancer?', '[{"id": "a", "text": "Esophageal cancer"}, {"id": "b", "text": "Gastric cancer"}, {"id": "c", "text": "Liver cancer"}, {"id": "d", "text": "Pancreatic cancer"}]'::jsonb, '["d"]', 'The Whipple procedure (pancreaticoduodenectomy) is a key treatment for pancreatic cancer, along with gemcitabine chemotherapy. Esophageal cancer is treated with esophagectomy.'),
  ('all_overview', 26, 'A 65-year-old client with a 40-year smoking history reports a chronic cough and coughing up blood. The nurse recognizes these findings as a classic clue for which cancer?', '[{"id": "a", "text": "Gastric cancer"}, {"id": "b", "text": "Lung cancer"}, {"id": "c", "text": "Esophageal cancer"}, {"id": "d", "text": "Lymphoma"}]'::jsonb, '["b"]', 'A chronic cough with hemoptysis suggests lung cancer, especially in smokers. Esophageal cancer presents with progressive dysphagia, weight loss, and hoarseness rather than hemoptysis.'),
  ('all_overview', 27, 'A client who has never smoked is diagnosed with non-small cell lung cancer (NSCLC). Which exposure in the client''s history is a known risk factor for this cancer?', '[{"id": "a", "text": "Benzene"}, {"id": "b", "text": "Aflatoxin"}, {"id": "c", "text": "Radon"}, {"id": "d", "text": "H. pylori"}]'::jsonb, '["c"]', 'Besides smoking, risk factors for NSCLC include asbestos, radon, and air pollution. Benzene is a risk factor for leukemia, not lung cancer.'),
  ('all_overview', 28, 'A client with localized non-small cell lung cancer (NSCLC) is scheduled for surgery. Which procedure does the nurse anticipate?', '[{"id": "a", "text": "Whipple procedure"}, {"id": "b", "text": "Esophagectomy"}, {"id": "c", "text": "Orchiectomy"}, {"id": "d", "text": "Lobectomy"}]'::jsonb, '["d"]', 'Surgical treatment for NSCLC is lobectomy, along with radiation and pembrolizumab. An esophagectomy is the surgery for esophageal cancer.'),
  ('all_overview', 29, 'A client with small cell lung cancer (SCLC) has a low serum sodium level. The nurse recognizes this finding as a sign of which paraneoplastic syndrome?', '[{"id": "a", "text": "SIADH"}, {"id": "b", "text": "Cushing''s syndrome"}, {"id": "c", "text": "Lambert-Eaton syndrome"}, {"id": "d", "text": "Graft-versus-host disease"}]'::jsonb, '["a"]', 'SCLC can cause SIADH, which lowers sodium. Cushing''s syndrome in SCLC is associated with increased ACTH, not low sodium.'),
  ('all_overview', 30, 'A client with small cell lung cancer (SCLC) reports progressive muscle weakness. The nurse suspects which paraneoplastic syndrome?', '[{"id": "a", "text": "SIADH"}, {"id": "b", "text": "Lambert-Eaton syndrome"}, {"id": "c", "text": "Cushing''s syndrome"}, {"id": "d", "text": "Hypercalcemia from bone lesions"}]'::jsonb, '["b"]', 'Lambert-Eaton syndrome is the SCLC paraneoplastic syndrome that causes muscle weakness. SIADH in SCLC causes low sodium rather than muscle weakness.'),
  ('all_overview', 31, 'A client with small cell lung cancer (SCLC) is beginning chemotherapy. Which regimen does the nurse anticipate?', '[{"id": "a", "text": "CHOP regimen"}, {"id": "b", "text": "Gemcitabine alone"}, {"id": "c", "text": "Cisplatin plus etoposide"}, {"id": "d", "text": "5-FU alone"}]'::jsonb, '["c"]', 'SCLC is treated with cisplatin plus etoposide chemotherapy and prophylactic cranial irradiation. CHOP is the regimen for lymphoma.'),
  ('all_overview', 32, 'The nurse reviews types of lung cancer with a client. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Non-small cell lung cancer is the most common type.\""}, {"id": "b", "text": "\"Small cell lung cancer is a very aggressive type.\""}, {"id": "c", "text": "\"Smoking is the top risk factor for both types.\""}, {"id": "d", "text": "\"Small cell lung cancer is the most common type.\""}]'::jsonb, '["d"]', 'Non-small cell lung cancer is the most common type, while small cell is very aggressive, so this statement needs correction. Smoking is the top risk factor for both types.'),
  ('all_overview', 33, 'A sexually active client reports bleeding after intercourse and a watery, foul-smelling vaginal discharge. The nurse recognizes these as classic symptoms of which cancer?', '[{"id": "a", "text": "Cervical cancer"}, {"id": "b", "text": "Endometrial cancer"}, {"id": "c", "text": "Ovarian cancer"}, {"id": "d", "text": "Breast cancer"}]'::jsonb, '["a"]', 'Postcoital bleeding and watery, foul discharge are classic symptoms of cervical cancer. The most common sign of endometrial cancer is postmenopausal bleeding.'),
  ('all_overview', 34, 'A 35-year-old client with no risk factors asks how often she should be screened for cervical cancer. Which recommendation by the nurse is correct?', '[{"id": "a", "text": "Pap smear every year"}, {"id": "b", "text": "Pap smear with HPV testing every 5 years"}, {"id": "c", "text": "No routine screening is recommended"}, {"id": "d", "text": "CA-125 blood test every year"}]'::jsonb, '["b"]', 'For ages 30–65, cervical screening is a Pap smear plus HPV test every 5 years. CA-125 is used for high-risk ovarian cancer evaluation, not cervical screening.'),
  ('all_overview', 35, 'A client asks the nurse what the most significant risk factor for cervical cancer is. Which response is correct?', '[{"id": "a", "text": "BRCA gene mutation"}, {"id": "b", "text": "Unopposed estrogen"}, {"id": "c", "text": "Nulliparity"}, {"id": "d", "text": "HPV infection"}]'::jsonb, '["d"]', 'HPV is the number-one risk factor for cervical cancer. Unopposed estrogen is the top risk factor for endometrial cancer.'),
  ('all_overview', 36, 'A 62-year-old postmenopausal client reports new vaginal bleeding. Which action by the nurse is most appropriate?', '[{"id": "a", "text": "Arrange prompt referral for an endometrial biopsy"}, {"id": "b", "text": "Reassure the client that this is expected after menopause"}, {"id": "c", "text": "Schedule a routine mammogram for the client"}, {"id": "d", "text": "Advise the client to recheck in one year"}]'::jsonb, '["a"]', 'Postmenopausal bleeding suggests endometrial cancer and requires immediate referral for biopsy. Reassuring the client delays evaluation of the most common sign of endometrial cancer.'),
  ('all_overview', 37, 'The nurse reviews the histories of four female clients. Which client has the strongest risk factors for endometrial cancer?', '[{"id": "a", "text": "A 28-year-old with a history of HPV infection"}, {"id": "b", "text": "An obese 58-year-old taking unopposed estrogen"}, {"id": "c", "text": "A 40-year-old with H. pylori infection"}, {"id": "d", "text": "A 45-year-old with chronic hepatitis B"}]'::jsonb, '["b"]', 'Unopposed estrogen and obesity are the top risk factors for endometrial cancer. HPV infection is the top risk factor for cervical cancer.'),
  ('all_overview', 38, 'A client with endometrial cancer asks what surgery is usually performed. Which procedure should the nurse describe?', '[{"id": "a", "text": "Loop electrosurgical excision procedure only"}, {"id": "b", "text": "Lumpectomy followed by tamoxifen therapy"}, {"id": "c", "text": "Total hysterectomy with bilateral salpingo-oophorectomy"}, {"id": "d", "text": "Pancreaticoduodenectomy (Whipple procedure)"}]'::jsonb, '["c"]', 'Endometrial cancer is treated with total hysterectomy plus bilateral salpingo-oophorectomy (BSO). LEEP is a treatment listed for cervical cancer.'),
  ('all_overview', 39, 'A client with a known BRCA1 mutation asks about screening for ovarian cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"An annual Pap smear will detect ovarian cancer early.\""}, {"id": "b", "text": "\"A colonoscopy every 10 years screens for ovarian cancer.\""}, {"id": "c", "text": "\"All women receive routine yearly ovarian cancer screening.\""}, {"id": "d", "text": "\"A CA-125 test may be used because you are at high risk.\""}]'::jsonb, '["d"]', 'There is no routine screening for ovarian cancer, but CA-125 is used for high-risk clients such as those with BRCA1/BRCA2 mutations. A Pap smear screens for cervical cancer, not ovarian cancer.'),
  ('all_overview', 40, 'A nulliparous client with a BRCA2 mutation reports persistent bloating, pelvic pressure, and frequent urination. The nurse suspects which cancer?', '[{"id": "a", "text": "Cervical cancer"}, {"id": "b", "text": "Ovarian cancer"}, {"id": "c", "text": "Endometrial cancer"}, {"id": "d", "text": "Colorectal cancer"}]'::jsonb, '["b"]', 'Bloating, pelvic pressure, and frequent urination are ovarian cancer symptoms, and BRCA1/BRCA2 and nulliparity are its top risk factors. Cervical cancer presents with postcoital bleeding and watery, foul discharge.'),
  ('all_overview', 41, 'A client is being examined for possible breast cancer. Which finding is the classic presentation the nurse should be alert for?', '[{"id": "a", "text": "A tender lump that changes with the menstrual cycle"}, {"id": "b", "text": "Bloating with pelvic pressure and urinary frequency"}, {"id": "c", "text": "A painless lump in the upper outer quadrant"}, {"id": "d", "text": "Bleeding after intercourse with foul discharge"}]'::jsonb, '["c"]', 'Breast cancer classically presents as a painless lump in the upper outer quadrant, along with peau d''orange and nipple discharge. Bloating and pelvic pressure are ovarian cancer symptoms.'),
  ('all_overview', 42, 'A 42-year-old client at average risk asks how she should be screened for breast cancer. Which recommendation by the nurse is correct?', '[{"id": "a", "text": "A mammogram every 10 years"}, {"id": "b", "text": "A yearly CA-125 blood test"}, {"id": "c", "text": "No routine screening is needed"}, {"id": "d", "text": "An annual mammogram"}]'::jsonb, '["d"]', 'Breast cancer screening is an annual mammogram starting at age 40. A CA-125 test is used for high-risk ovarian cancer, not breast screening.'),
  ('all_overview', 43, 'A client with prostate cancer reports new, persistent back pain. The nurse recognizes that this finding may indicate:', '[{"id": "a", "text": "bone metastasis."}, {"id": "b", "text": "Lambert-Eaton syndrome."}, {"id": "c", "text": "testicular cancer spread."}, {"id": "d", "text": "SIADH from the tumor."}]'::jsonb, '["a"]', 'In prostate cancer, back pain is a sign of bone metastasis. Lambert-Eaton syndrome is a paraneoplastic syndrome of small cell lung cancer that causes muscle weakness, not a complication of prostate cancer.'),
  ('all_overview', 44, 'A 45-year-old African American man asks when he should begin prostate cancer screening. Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"You should wait until age 50 like everyone else.\""}, {"id": "b", "text": "\"Because you are high risk, PSA and DRE can begin at 45.\""}, {"id": "c", "text": "\"Prostate screening is done only with a monthly self-exam.\""}, {"id": "d", "text": "\"Screening is not needed unless you have back pain.\""}]'::jsonb, '["b"]', 'African American men have a higher risk of prostate cancer, and PSA plus DRE screening starts at age 50, or 45 if high risk. Waiting until 50 ignores this client''s high-risk status.'),
  ('all_overview', 45, 'A client''s laboratory results show an elevated PSA, and the provider notes a hard, irregular prostate on digital rectal exam. The nurse recognizes these findings as most suggestive of which condition?', '[{"id": "a", "text": "Testicular cancer"}, {"id": "b", "text": "Penile cancer"}, {"id": "c", "text": "Prostate cancer"}, {"id": "d", "text": "Colorectal cancer"}]'::jsonb, '["c"]', 'An elevated PSA with a hard, irregular prostate on DRE is the classic clue for prostate cancer. Testicular cancer classically presents as a painless testicular mass in a young male.'),
  ('all_overview', 46, 'A 22-year-old client reports finding a painless lump on one testicle. The nurse recognizes this as the most common presentation of which cancer?', '[{"id": "a", "text": "Penile cancer"}, {"id": "b", "text": "Prostate cancer"}, {"id": "c", "text": "Lymphoma"}, {"id": "d", "text": "Testicular cancer"}]'::jsonb, '["d"]', 'A painless testicular lump in a young man is the most common presentation of testicular cancer, which affects men 15–35. Prostate cancer occurs mainly in men over 50 and presents with urinary symptoms.'),
  ('all_overview', 47, 'The nurse is teaching a 16-year-old male client about testicular cancer screening. Which instruction is correct?', '[{"id": "a", "text": "\"Perform a testicular self-exam once every month.\""}, {"id": "b", "text": "\"Perform a testicular self-exam once every year.\""}, {"id": "c", "text": "\"Begin testicular self-exams at age 50.\""}, {"id": "d", "text": "\"Have a PSA blood test every month instead.\""}]'::jsonb, '["a"]', 'Testicular cancer screening is a monthly testicular self-exam starting in the teenage years. PSA testing is used for prostate cancer screening, not testicular cancer.'),
  ('all_overview', 48, 'An uncircumcised client with a history of HPV has a red, ulcerated lesion on the penis that has not healed, foul-smelling discharge, and swollen inguinal lymph nodes. The nurse suspects which cancer?', '[{"id": "a", "text": "Testicular cancer"}, {"id": "b", "text": "Prostate cancer"}, {"id": "c", "text": "Penile cancer"}, {"id": "d", "text": "Lymphoma"}]'::jsonb, '["c"]', 'Penile cancer presents as a red/ulcerated non-healing lesion with foul-smelling discharge and swollen inguinal lymph nodes; HPV, poor hygiene, and being uncircumcised are risk factors. Testicular cancer presents as a painless testicular lump instead.'),
  ('all_overview', 49, 'A client returns to the unit after surgical removal of a tumor. Which group of concerns should the nurse focus on in the postoperative plan of care?', '[{"id": "a", "text": "Respiratory status, bleeding, infection, and DVT prevention"}, {"id": "b", "text": "Time, distance, and shielding to limit radiation exposure"}, {"id": "c", "text": "Monthly self-exams and annual screening schedules"}, {"id": "d", "text": "Ondansetron timing and the expected blood count nadir"}]'::jsonb, '["a"]', 'Post-operative nursing points after cancer surgery are respiratory status, bleeding, infection, and DVT prevention. Time, distance, and shielding are brachytherapy precautions, not post-op priorities.'),
  ('all_overview', 50, 'A client with kidney cancer is prescribed a targeted therapy. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Imatinib"}, {"id": "b", "text": "Sunitinib"}, {"id": "c", "text": "Rituximab"}, {"id": "d", "text": "Bortezomib"}]'::jsonb, '["b"]', 'Sunitinib is the targeted therapy listed for kidney cancer. Imatinib targets CML, rituximab targets NHL, and bortezomib targets myeloma.'),
  ('grading', 1, 'A client''s biopsy report describes the tumor as well-differentiated. The client asks what this means. Which response by the nurse is accurate?', '[{"id": "a", "text": "The cancer cells look close to normal cells and tend to grow slowly."}, {"id": "b", "text": "The cancer has spread only to the lymph nodes near the tumor."}, {"id": "c", "text": "The cancer cells bear no resemblance at all to normal cells."}, {"id": "d", "text": "The cancer has not invaded beyond its original layer of tissue."}]'::jsonb, '["a"]', 'A well-differentiated (Grade I) tumor has cells that look close to normal and is slow-growing with the best prognosis. Lymph node spread and invasion describe staging, not grading, and cells with no resemblance to normal describe Grade IV.'),
  ('grading', 2, 'The nurse reviews the pathology reports of four clients with newly diagnosed cancer. Which client''s tumor grade indicates the most aggressive cancer?', '[{"id": "a", "text": "Grade I, well-differentiated"}, {"id": "b", "text": "Grade II, moderately differentiated"}, {"id": "c", "text": "Grade III, poorly differentiated"}, {"id": "d", "text": "Grade IV, undifferentiated"}]'::jsonb, '["d"]', 'Grade IV (undifferentiated/anaplastic) cells bear no resemblance to normal cells and are the most aggressive with the worst prognosis. Grade III is fast-growing and aggressive but is not the most aggressive grade.'),
  ('grading', 3, 'A client is told that the tumor is Grade III and asks what this grade says about the cancer. The nurse explains that the cells are:', '[{"id": "a", "text": "somewhat abnormal and growing at an intermediate rate."}, {"id": "b", "text": "very abnormal and likely to grow quickly."}, {"id": "c", "text": "close to normal and likely to grow slowly."}, {"id": "d", "text": "confined to the organ where they started."}]'::jsonb, '["b"]', 'Grade III (poorly differentiated) cells are very abnormal and fast-growing and aggressive. Somewhat abnormal cells with an intermediate growth rate describe Grade II, and confinement to the organ describes stage, not grade.'),
  ('grading', 4, 'A pathology report describes a client''s tumor as moderately differentiated. Which growth pattern does the nurse expect?', '[{"id": "a", "text": "Slow growth with the best prognosis"}, {"id": "b", "text": "Rapid growth with the worst prognosis"}, {"id": "c", "text": "An intermediate rate of growth"}, {"id": "d", "text": "Fast and aggressive growth"}]'::jsonb, '["c"]', 'Grade II, moderately differentiated, cells are somewhat abnormal with an intermediate growth rate. Slow growth with the best prognosis describes Grade I, and fast, aggressive growth describes Grades III and IV.'),
  ('grading', 5, 'The nurse teaches a client about the difference between tumor grade and tumor stage. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "The grade tells how abnormal my cancer cells look under a microscope."}, {"id": "b", "text": "The stage tells how far my cancer has spread in my body."}, {"id": "c", "text": "A biopsy is needed before my tumor can be graded."}, {"id": "d", "text": "The grade tells which distant organs my cancer has reached."}]'::jsonb, '["d"]', 'Grading describes the cell, while staging describes the spread, so spread to distant organs is reflected in the stage (M component), not the grade. The other statements are accurate, including that a biopsy is required for grading.'),
  ('grading', 6, 'A client newly diagnosed with a solid tumor asks how the health care team will describe how far the cancer has spread. The nurse explains that spread is described using which system?', '[{"id": "a", "text": "TNM system"}, {"id": "b", "text": "Nottingham grading system"}, {"id": "c", "text": "WHO grading system (I–IV)"}, {"id": "d", "text": "FAB classification"}]'::jsonb, '["a"]', 'Staging describes the extent of cancer spread and uses the TNM system. The Nottingham system grades breast cancer cells, WHO grading is used for CNS tumors, and FAB classifies AML.'),
  ('grading', 7, 'A client with breast cancer is told that her tumor was graded with the Nottingham system. The nurse understands that this score combines which findings?', '[{"id": "a", "text": "Tumor size, lymph node involvement, and distant metastasis"}, {"id": "b", "text": "Tubule formation, nuclear pleomorphism, and mitotic count"}, {"id": "c", "text": "Physical examination, imaging, and surgical findings"}, {"id": "d", "text": "Treatment response, recurrence, and relapse history"}]'::jsonb, '["b"]', 'The Nottingham grading system for breast cancer combines tubule formation, nuclear pleomorphism, and mitotic count into a score. Tumor size, nodes, and metastasis are the TNM staging components, which describe spread rather than cell appearance.'),
  ('grading', 8, 'The nurse is reviewing documentation for a client with breast cancer graded by the Nottingham system. Which recorded score should the nurse question as outside the possible range?', '[{"id": "a", "text": "A score of 3"}, {"id": "b", "text": "A score of 6"}, {"id": "c", "text": "A score of 9"}, {"id": "d", "text": "A score of 12"}]'::jsonb, '["d"]', 'The Nottingham system produces a score of 3 to 9, so a score of 12 is outside the possible range and should be clarified. Scores of 3, 6, and 9 all fall within the range.'),
  ('grading', 9, 'A client''s pathology report lists the primary tumor as Tis. The nurse interprets this finding as:', '[{"id": "a", "text": "a primary tumor that cannot be assessed."}, {"id": "b", "text": "no evidence of a primary tumor."}, {"id": "c", "text": "a primary tumor that is in situ."}, {"id": "d", "text": "a tumor with the greatest size and invasion."}]'::jsonb, '["c"]', 'Tis indicates a tumor in situ. TX means the tumor cannot be assessed, and T0 means there is no evidence of a primary tumor.'),
  ('grading', 10, 'A client''s staging documentation includes TX. A nursing student asks what this means. The nurse explains that the primary tumor:', '[{"id": "a", "text": "cannot be assessed."}, {"id": "b", "text": "shows no evidence of being present."}, {"id": "c", "text": "is in situ."}, {"id": "d", "text": "has the greatest size and local invasion."}]'::jsonb, '["a"]', 'TX means the primary tumor cannot be assessed. No evidence of tumor is T0, in situ is Tis, and increasing size and invasion are shown by T1 through T4.'),
  ('grading', 11, 'Two clients have the same type of cancer. One is documented as T1 and the other as T4. The nurse understands that, compared with T1, the T4 tumor has:', '[{"id": "a", "text": "less local invasion."}, {"id": "b", "text": "more distant metastasis."}, {"id": "c", "text": "more regional lymph node involvement."}, {"id": "d", "text": "greater size and local invasion."}]'::jsonb, '["d"]', 'T1 through T4 reflect increasing size and invasion of the primary tumor. Lymph node involvement is described by N, and distant metastasis is described by M.'),
  ('grading', 12, 'A client''s staging report includes N0. The client asks whether the cancer is in the lymph nodes. The nurse''s response is based on the understanding that N0 indicates:', '[{"id": "a", "text": "the lymph nodes cannot be assessed."}, {"id": "b", "text": "no regional lymph node involvement."}, {"id": "c", "text": "limited regional lymph node involvement."}, {"id": "d", "text": "distant metastasis to other organs."}]'::jsonb, '["b"]', 'N0 means there is no regional lymph node involvement. NX means the nodes cannot be assessed, and N1 indicates limited involvement.'),
  ('grading', 13, 'The nurse compares the staging of two clients: one is documented as N1 and the other as N3. Which interpretation is correct?', '[{"id": "a", "text": "N3 indicates a larger primary tumor than N1."}, {"id": "b", "text": "N3 indicates the nodes could not be assessed."}, {"id": "c", "text": "N3 indicates more lymph node involvement than N1."}, {"id": "d", "text": "N3 indicates distant metastasis, while N1 does not."}]'::jsonb, '["c"]', 'N1 through N3 indicate increasing regional lymph node involvement. Tumor size is reflected in T, unassessable nodes are NX, and distant metastasis is reflected in M.'),
  ('grading', 14, 'A client''s staging report shows M1. Which statement by the nurse accurately explains this finding?', '[{"id": "a", "text": "The cancer has spread to distant organs."}, {"id": "b", "text": "The cancer has not spread to distant organs."}, {"id": "c", "text": "The cancer is limited to one regional node."}, {"id": "d", "text": "The cancer cells look close to normal cells."}]'::jsonb, '["a"]', 'M1 means distant metastasis is present. M0 means no distant metastasis, and cell appearance is described by grade rather than stage.'),
  ('grading', 15, 'The nurse is reviewing TNM findings for several clients. Which finding should the nurse recognize as a positive prognostic sign?', '[{"id": "a", "text": "T4"}, {"id": "b", "text": "N3"}, {"id": "c", "text": "M0"}, {"id": "d", "text": "M1"}]'::jsonb, '["c"]', 'M0 means no distant metastasis and is a positive prognostic sign. M1 indicates distant metastasis, while T4 and N3 indicate the greatest tumor invasion and node involvement.'),
  ('grading', 16, 'A client staged as cT2N1M0 asks why additional treatment is being discussed after surgery. Based on the N1 finding, the nurse anticipates which plan?', '[{"id": "a", "text": "No further treatment, because the nodes are clear"}, {"id": "b", "text": "Close monitoring and likely adjuvant therapy"}, {"id": "c", "text": "Hospice referral for distant metastatic disease"}, {"id": "d", "text": "Restaging to Stage IV for the medical record"}]'::jsonb, '["b"]', 'N1 means limited lymph node involvement, so the client needs monitoring and adjuvant therapy is likely. M0 shows no distant metastasis, and the stage is not changed to Stage IV in the record.'),
  ('grading', 17, 'A client is told that the cancer is Stage 0. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It is carcinoma in situ, with no invasion into surrounding tissue."}, {"id": "b", "text": "It has spread to nearby lymph nodes but not to distant organs."}, {"id": "c", "text": "It has spread extensively within the surrounding region."}, {"id": "d", "text": "It has spread from the original site to other organs."}]'::jsonb, '["a"]', 'Stage 0 is carcinoma in situ with no invasion into surrounding tissue. Nearby node spread suggests Stage II, extensive regional spread is Stage III, and spread to other organs is Stage IV.'),
  ('grading', 18, 'A client has a small invasive tumor that remains confined to the organ of origin, with no lymph node involvement. Which overall stage does the nurse recognize this description as?', '[{"id": "a", "text": "Stage 0"}, {"id": "b", "text": "Stage I"}, {"id": "c", "text": "Stage III"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["b"]', 'Stage I is a localized, small cancer confined to the organ of origin. Stage 0 has no invasion into surrounding tissue, and Stages III and IV involve extensive regional or distant spread.'),
  ('grading', 19, 'A client is told that the cancer is Stage II. Which description best matches this stage?', '[{"id": "a", "text": "Carcinoma in situ with no invasion"}, {"id": "b", "text": "Distant spread to other organs"}, {"id": "c", "text": "Local spread with possible nearby node involvement"}, {"id": "d", "text": "Extensive regional spread with significant node involvement"}]'::jsonb, '["c"]', 'Stage II is local spread with a larger tumor and possible nearby lymph node involvement. Extensive regional spread with significant node involvement describes Stage III.'),
  ('grading', 20, 'Imaging and biopsy show that a client''s cancer has extensive regional spread with significant lymph node involvement but no distant metastasis. Which overall stage does the nurse expect?', '[{"id": "a", "text": "Stage I"}, {"id": "b", "text": "Stage II"}, {"id": "c", "text": "Stage III"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["c"]', 'Stage III is extensive regional spread with significant lymph node involvement. Stage II has only possible nearby node involvement, and Stage IV requires distant metastasis.'),
  ('grading', 21, 'At the time of diagnosis, a client''s primary lung tumor is found to have spread to the liver. Which overall stage should the nurse expect to see documented?', '[{"id": "a", "text": "Stage I"}, {"id": "b", "text": "Stage II"}, {"id": "c", "text": "Stage III"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["d"]', 'Stage IV means distant metastasis, with cancer spread to other organs, and here the spread was present at diagnosis. Stage III is extensive regional spread without distant metastasis.'),
  ('grading', 22, 'A client was diagnosed with Stage II cancer 2 years ago. Imaging now shows that the cancer has spread to the bones. How should the nurse expect the original stage to be documented in the medical record?', '[{"id": "a", "text": "Changed to Stage IV"}, {"id": "b", "text": "Kept as Stage II"}, {"id": "c", "text": "Changed to Stage III"}, {"id": "d", "text": "Removed until restaged"}]'::jsonb, '["b"]', 'Once a cancer is staged at diagnosis, the stage does not change even if the disease progresses, so it remains Stage II. It is not restaged to Stage IV for the medical record.'),
  ('grading', 23, 'A client''s cancer, staged as Stage I at diagnosis, has since progressed. Which action by a newly hired nurse requires correction by the charge nurse?', '[{"id": "a", "text": "Changing the client''s original documented stage to Stage IV"}, {"id": "b", "text": "Recording the original stage exactly as it was assigned"}, {"id": "c", "text": "Reviewing the pathology report for the tumor grade"}, {"id": "d", "text": "Explaining that grading describes the cells'' appearance"}]'::jsonb, '["a"]', 'The stage assigned at diagnosis does not change even if the disease progresses, so changing the original stage to Stage IV is incorrect. Keeping the original stage and explaining that grading describes the cell are appropriate.'),
  ('grading', 24, 'The nurse teaches a client whose cancer has progressed since diagnosis. Which client statement indicates understanding of how the stage is recorded?', '[{"id": "a", "text": "My stage will be raised in my record now that it has spread."}, {"id": "b", "text": "My stage will be lowered in my record once treatment works."}, {"id": "c", "text": "My original stage stays in my record even though it progressed."}, {"id": "d", "text": "My stage will be erased from my record since it has progressed."}]'::jsonb, '["c"]', 'Staging does not change after initial diagnosis; the original stage is the permanent record. The stage is not raised, lowered, or removed because of progression or treatment.'),
  ('grading', 25, 'Before any treatment begins, a provider assigns a stage based on the client''s physical examination and CT scan results. Which prefix does the nurse expect to see on this stage?', '[{"id": "a", "text": "p"}, {"id": "b", "text": "c"}, {"id": "c", "text": "y"}, {"id": "d", "text": "r"}]'::jsonb, '["b"]', 'Clinical staging is based on physical exam and imaging before treatment and uses the prefix c. The prefix p is pathological staging, based on the surgical specimen after surgery.'),
  ('grading', 26, 'Following a lobectomy, a client''s stage is documented with the prefix p. The nurse understands that this stage is based on:', '[{"id": "a", "text": "physical examination and imaging before treatment."}, {"id": "b", "text": "re-evaluation after chemotherapy or radiation."}, {"id": "c", "text": "restaging after the disease has relapsed."}, {"id": "d", "text": "analysis of the surgical specimen after surgery."}]'::jsonb, '["d"]', 'Pathological staging (p) is based on analysis of the surgical specimen after surgery. Exam and imaging before treatment is clinical staging (c), post-therapy is y, and recurrence is r.'),
  ('grading', 27, 'A client asks which is more accurate: the stage assigned from scans before surgery or the stage assigned after the tumor was removed and examined. Which response by the nurse is correct?', '[{"id": "a", "text": "The stage from the surgical specimen is more accurate."}, {"id": "b", "text": "The stage from the scans before surgery is more accurate."}, {"id": "c", "text": "Both stages are always equally accurate for every client."}, {"id": "d", "text": "Neither stage is used once the tumor has been removed."}]'::jsonb, '["a"]', 'Pathological staging, based on the surgical specimen after surgery, is more accurate than clinical staging. Clinical staging is based on exam and imaging before treatment.'),
  ('grading', 28, 'A client completes a course of chemotherapy and radiation, and the tumor is re-evaluated to see how it responded. Which staging prefix does the nurse expect?', '[{"id": "a", "text": "c"}, {"id": "b", "text": "p"}, {"id": "c", "text": "y"}, {"id": "d", "text": "r"}]'::jsonb, '["c"]', 'Post-therapy staging (y) is a re-evaluation after chemo or radiation to see treatment response. The prefix r is used for restaging after recurrence or relapse.'),
  ('grading', 29, 'A client treated for cancer 3 years ago now has a relapse, and the provider restages the disease. Which staging prefix does the nurse expect on the new stage?', '[{"id": "a", "text": "c"}, {"id": "b", "text": "p"}, {"id": "c", "text": "y"}, {"id": "d", "text": "r"}]'::jsonb, '["d"]', 'Recurrence staging (r) is restaging after disease recurrence or relapse. The prefix y is used for re-evaluation after chemotherapy or radiation, not after relapse.'),
  ('grading', 30, 'A client has an examination and imaging before treatment, then surgery, then chemotherapy followed by re-evaluation, and later a relapse. Which sequence of staging prefixes reflects this course?', '[{"id": "a", "text": "p, c, y, r"}, {"id": "b", "text": "c, p, y, r"}, {"id": "c", "text": "c, y, r, p"}, {"id": "d", "text": "r, c, p, y"}]'::jsonb, '["b"]', 'Clinical staging (c) comes from exam and imaging before treatment, pathological (p) after surgery, post-therapy (y) after chemo or radiation, and recurrence (r) after relapse. Pathological staging cannot precede clinical staging because it requires the surgical specimen.'),
  ('grading', 31, 'A client''s tumor is staged as cT2N1M0. Which overall interpretation is accurate?', '[{"id": "a", "text": "Locally advanced disease that is not yet metastatic"}, {"id": "b", "text": "Carcinoma in situ with no invasion into the tissue"}, {"id": "c", "text": "Distant metastatic disease involving other organs"}, {"id": "d", "text": "A tumor confined to the organ with no node spread"}]'::jsonb, '["a"]', 'cT2N1M0 indicates locally advanced disease, likely Stage II to III, that is not yet metastatic. N1 shows lymph node involvement, so the disease is not confined to the organ, and M0 rules out distant metastasis.'),
  ('grading', 32, 'A client staged as cT2N1M0 asks the nurse whether the cancer has spread to other organs. The nurse''s response is based on which component?', '[{"id": "a", "text": "T2, which shows spread to distant organs"}, {"id": "b", "text": "N1, which shows spread to distant organs"}, {"id": "c", "text": "M0, which shows no distant metastasis"}, {"id": "d", "text": "c, which shows spread confirmed at surgery"}]'::jsonb, '["c"]', 'M0 indicates no distant metastasis, which is a favorable indicator. T2 describes the primary tumor, N1 describes limited regional node involvement, and c indicates clinical staging before surgery.'),
  ('grading', 33, 'In the stage cT2N1M0, how should the nurse interpret T2?', '[{"id": "a", "text": "No evidence of a primary tumor"}, {"id": "b", "text": "A moderately sized tumor with local invasion"}, {"id": "c", "text": "Limited regional lymph node involvement"}, {"id": "d", "text": "A primary tumor that cannot be assessed"}]'::jsonb, '["b"]', 'T2 indicates a moderately sized primary tumor with local invasion. Limited regional lymph node involvement is N1, and no evidence of tumor is T0.'),
  ('grading', 34, 'The nurse explains to a client that the c in the stage cT2N1M0 means the stage was determined:', '[{"id": "a", "text": "from the surgical specimen after surgery."}, {"id": "b", "text": "after chemotherapy to assess response."}, {"id": "c", "text": "after the disease relapsed."}, {"id": "d", "text": "before surgery, based on imaging."}]'::jsonb, '["d"]', 'The prefix c indicates clinical staging, done before surgery and based on imaging. Staging from the surgical specimen uses p, and post-therapy and recurrence staging use y and r.'),
  ('grading', 35, 'A client newly diagnosed with acute myelogenous leukemia asks why the cancer has no TNM stage. Which response by the nurse is accurate?', '[{"id": "a", "text": "Leukemia is blood-borne, so there is no solid tumor to stage."}, {"id": "b", "text": "Leukemia is always documented as Stage IV at diagnosis."}, {"id": "c", "text": "Leukemia is given a TNM stage only after it relapses."}, {"id": "d", "text": "Leukemia is staged using only the Nottingham system."}]'::jsonb, '["a"]', 'Leukemia is a blood-borne cancer with no solid tumor to stage, so it uses its own classification instead of TNM. The Nottingham system grades breast cancer.'),
  ('grading', 36, 'The nurse caring for a client with acute myelogenous leukemia (AML) anticipates that the disease will be classified using which system?', '[{"id": "a", "text": "TNM staging"}, {"id": "b", "text": "Nottingham grading"}, {"id": "c", "text": "FAB classification"}, {"id": "d", "text": "Recurrence staging"}]'::jsonb, '["c"]', 'Leukemia uses its own classification, such as FAB for AML, because there is no solid tumor for TNM staging. Nottingham grading is used for breast cancer.'),
  ('grading', 37, 'A client is diagnosed with a primary brain tumor. The nurse anticipates that the tumor will be described using which system?', '[{"id": "a", "text": "TNM staging"}, {"id": "b", "text": "WHO grading (I–IV)"}, {"id": "c", "text": "FAB classification"}, {"id": "d", "text": "Nottingham grading"}]'::jsonb, '["b"]', 'CNS tumors, including brain and spinal cord cancers, use WHO grading (I–IV) instead of TNM staging. FAB is used for AML, and Nottingham grading is used for breast cancer.'),
  ('grading', 38, 'The nurse is caring for four clients with cancer. For which client should the nurse expect a TNM stage to be documented?', '[{"id": "a", "text": "A client with acute myelogenous leukemia"}, {"id": "b", "text": "A client with a spinal cord tumor"}, {"id": "c", "text": "A client with a primary brain tumor"}, {"id": "d", "text": "A client with breast cancer"}]'::jsonb, '["d"]', 'TNM staging is not used for leukemia or CNS cancers, which include brain and spinal cord tumors. Breast cancer is a solid tumor staged with TNM, although its grade uses the Nottingham system.'),
  ('grading', 39, 'A client asks why a biopsy is needed when a CT scan has already shown the tumor. Which response by the nurse is accurate?', '[{"id": "a", "text": "A biopsy is required to grade the tumor and stage it pathologically."}, {"id": "b", "text": "A biopsy is required only for clinical staging before treatment."}, {"id": "c", "text": "A biopsy is needed only if the CT scan cannot locate the tumor."}, {"id": "d", "text": "A biopsy replaces the need for any imaging during staging."}]'::jsonb, '["a"]', 'A biopsy is required for both grading and pathological staging. Clinical staging is based on physical exam and imaging, not a biopsy.'),
  ('grading', 40, 'A client has a mass seen on imaging. Before a tumor grade can be assigned, which item must the nurse ensure has been obtained?', '[{"id": "a", "text": "A PET scan of the whole body"}, {"id": "b", "text": "A tissue sample from a biopsy"}, {"id": "c", "text": "A complete physical examination"}, {"id": "d", "text": "A documented clinical TNM stage"}]'::jsonb, '["b"]', 'Grading describes how abnormal the cancer cells look under a microscope, so a biopsy is required. Imaging and physical examination support clinical staging but cannot show cell appearance.'),
  ('grading', 41, 'After teaching about tumor differentiation, which client statement indicates correct understanding?', '[{"id": "a", "text": "Undifferentiated cells usually mean a slower-growing cancer."}, {"id": "b", "text": "Well-differentiated cells usually mean a slower-growing cancer."}, {"id": "c", "text": "Poorly differentiated cells look nearly the same as normal cells."}, {"id": "d", "text": "Moderately differentiated cells are the most aggressive type."}]'::jsonb, '["b"]', 'Well-differentiated means well-behaved and slow, while undifferentiated means unruly, fast, and aggressive. Poorly differentiated cells are very abnormal, and Grade IV, not moderately differentiated, is most aggressive.'),
  ('grading', 42, 'A client asks what the tumor grade is meant to predict. The nurse explains that the grade mainly reflects:', '[{"id": "a", "text": "how far the cancer has spread in the body."}, {"id": "b", "text": "how many lymph nodes contain cancer cells."}, {"id": "c", "text": "how fast the cancer is likely to grow."}, {"id": "d", "text": "whether the cancer has reached distant organs."}]'::jsonb, '["c"]', 'Grading describes how abnormal the cells look and reflects how fast the cancer is likely to grow. Spread, lymph node involvement, and distant metastasis are described by staging.'),
  ('grading', 43, 'Client A has a Grade I, Stage III cancer. Client B has a Grade IV, Stage I cancer. Which statement by the nurse is accurate?', '[{"id": "a", "text": "Client A''s cancer has spread further; Client B''s cells are more aggressive."}, {"id": "b", "text": "Client A''s cells are more aggressive; Client B''s cancer has spread further."}, {"id": "c", "text": "Client A''s cancer has distant metastasis; Client B''s is in situ."}, {"id": "d", "text": "Both clients'' cancers have the same degree of aggressiveness."}]'::jsonb, '["a"]', 'Grading describes the cell and staging describes the spread, so Stage III shows more spread than Stage I, and Grade IV cells are more aggressive than Grade I. Stage III is regional, not distant, spread, and Stage I is not in situ.'),
  ('grading', 44, 'A pathology report describes a client''s tumor cells as anaplastic. Which grade does the nurse associate with this term?', '[{"id": "a", "text": "Grade I"}, {"id": "b", "text": "Grade II"}, {"id": "c", "text": "Grade III"}, {"id": "d", "text": "Grade IV"}]'::jsonb, '["d"]', 'Grade IV is undifferentiated, or anaplastic, with cells that bear no resemblance to normal cells. Grade III is poorly differentiated.'),
  ('grading', 45, 'A client''s tumor is described on the pathology report as poorly differentiated. Which grade is the nurse most likely to see documented?', '[{"id": "a", "text": "Grade I"}, {"id": "b", "text": "Grade II"}, {"id": "c", "text": "Grade III"}, {"id": "d", "text": "Grade IV"}]'::jsonb, '["c"]', 'Grade III corresponds to poorly differentiated cells that are very abnormal and fast-growing. Grade II is moderately differentiated, and Grade IV is undifferentiated or anaplastic.'),
  ('grading', 46, 'Four clients have the same type of cancer at the same stage. Based on tumor grade alone, which client has the best expected prognosis?', '[{"id": "a", "text": "The client with a Grade III tumor"}, {"id": "b", "text": "The client with a Grade I tumor"}, {"id": "c", "text": "The client with a Grade II tumor"}, {"id": "d", "text": "The client with a Grade IV tumor"}]'::jsonb, '["b"]', 'Grade I (well-differentiated) cancer is slow-growing with the best prognosis. Grade IV has the worst prognosis, and Grades II and III grow at intermediate and fast rates.'),
  ('grading', 47, 'A family member asks what the stage of a client''s cancer tells the health care team. The nurse''s best response is that the stage describes:', '[{"id": "a", "text": "how far the cancer has spread in the body."}, {"id": "b", "text": "how abnormal the cells look under a microscope."}, {"id": "c", "text": "how fast the cancer cells are likely to grow."}, {"id": "d", "text": "how closely the cells resemble normal cells."}]'::jsonb, '["a"]', 'Staging describes the extent of cancer spread in the body. Cell appearance, growth rate, and resemblance to normal cells are all described by grading.'),
  ('grading', 48, 'A client''s staging report lists NX. How should the nurse interpret this finding?', '[{"id": "a", "text": "No regional lymph node involvement"}, {"id": "b", "text": "Limited regional lymph node involvement"}, {"id": "c", "text": "Extensive regional lymph node involvement"}, {"id": "d", "text": "Regional lymph nodes cannot be assessed"}]'::jsonb, '["d"]', 'NX means the regional lymph nodes cannot be assessed. N0 means no involvement, and N1 through N3 indicate increasing involvement.'),
  ('grading', 49, 'After evaluation, a client''s report lists T0. The nurse understands that this means:', '[{"id": "a", "text": "the primary tumor cannot be assessed."}, {"id": "b", "text": "the primary tumor is in situ."}, {"id": "c", "text": "there is no evidence of a primary tumor."}, {"id": "d", "text": "the tumor has spread to distant organs."}]'::jsonb, '["c"]', 'T0 means there is no evidence of a primary tumor. TX means the tumor cannot be assessed, Tis means in situ, and distant spread is described by M1.'),
  ('grading', 50, 'A client''s tumor is staged as cT2N1M0. Which overall stage range is most likely?', '[{"id": "a", "text": "Stage 0"}, {"id": "b", "text": "Stage I"}, {"id": "c", "text": "Stage II–III"}, {"id": "d", "text": "Stage IV"}]'::jsonb, '["c"]', 'cT2N1M0 represents locally advanced disease, likely Stage II to III, that is not yet metastatic. Stage IV would require distant metastasis, but M0 shows none.'),
  ('heme', 1, 'A client receiving chemotherapy for leukemia has an absolute neutrophil count (ANC) of 450. Which intervention should the nurse implement?', '[{"id": "a", "text": "Place the client in a private room and enforce strict hand hygiene."}, {"id": "b", "text": "Encourage fresh salads and raw fruit to improve nutrition."}, {"id": "c", "text": "Obtain the client''s temperature rectally every 4 hours."}, {"id": "d", "text": "Allow the family to bring fresh flowers into the room."}]'::jsonb, '["a"]', 'An ANC below 500 is severe neutropenia, which calls for strict hand hygiene and a private room. Raw produce, fresh flowers, and rectal temperatures are all to be avoided.'),
  ('heme', 2, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a client whose ANC is below 500. Which action by the UAP requires correction?', '[{"id": "a", "text": "Performing hand hygiene before entering the room"}, {"id": "b", "text": "Taking the client''s temperature rectally"}, {"id": "c", "text": "Removing a fresh flower arrangement from the room"}, {"id": "d", "text": "Reporting a temperature of 38.3°C to the nurse"}]'::jsonb, '["b"]', 'Rectal temperatures are avoided in a client with severe neutropenia. Hand hygiene, removing fresh flowers, and reporting a fever of 38°C or higher are all correct actions.'),
  ('heme', 3, 'A client with acute leukemia and severe neutropenia has a temperature of 38.2°C (100.8°F). Which action should the nurse take first?', '[{"id": "a", "text": "Recheck the temperature again in 4 hours"}, {"id": "b", "text": "Offer cool fluids and document the finding"}, {"id": "c", "text": "Apply a cooling blanket and reassess later"}, {"id": "d", "text": "Report the fever immediately as possible sepsis"}]'::jsonb, '["d"]', 'In a neutropenic client, any fever of 38°C (100.4°F) or higher is reported immediately as potential sepsis. Delaying with a recheck or comfort measures postpones needed treatment.'),
  ('heme', 4, 'The nurse teaches a client with severe neutropenia about infection precautions at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will snack on raw vegetables picked from my garden."}, {"id": "b", "text": "I will avoid raw produce while my counts are this low."}, {"id": "c", "text": "I will keep fresh flowers out of my room for now."}, {"id": "d", "text": "I will call right away if my temperature reaches 38°C."}]'::jsonb, '["a"]', 'Clients with severe neutropenia should avoid raw produce, so eating raw garden vegetables needs correction. Avoiding fresh flowers and reporting a fever of 38°C or higher are correct.'),
  ('heme', 5, 'The nurse reviews the absolute neutrophil counts (ANC) of four clients receiving chemotherapy. Which client meets the criterion for severe neutropenia?', '[{"id": "a", "text": "ANC of 1,200"}, {"id": "b", "text": "ANC of 400"}, {"id": "c", "text": "ANC of 900"}, {"id": "d", "text": "ANC of 650"}]'::jsonb, '["b"]', 'An ANC below 500 is severe neutropenia, so an ANC of 400 meets the criterion. The other values are all 500 or higher.'),
  ('heme', 6, 'A client with leukemia has a platelet count of 18,000. Which intervention should the nurse anticipate?', '[{"id": "a", "text": "Discharge teaching, as the count is in a safe range"}, {"id": "b", "text": "Intramuscular injections to control nausea"}, {"id": "c", "text": "Possible platelet transfusion for this emergency"}, {"id": "d", "text": "Routine monitoring with no change in the care plan"}]'::jsonb, '["c"]', 'A platelet count below 20,000 is an emergency, and the client may need a transfusion. Intramuscular injections are avoided in thrombocytopenia.'),
  ('heme', 7, 'A client with thrombocytopenia asks how to shave safely at home. Which instruction should the nurse give?', '[{"id": "a", "text": "Use a straight razor with a new blade."}, {"id": "b", "text": "Use a disposable razor with shaving gel."}, {"id": "c", "text": "Shave every other day with a blade razor."}, {"id": "d", "text": "Use an electric razor instead of a blade."}]'::jsonb, '["d"]', 'Bleeding precautions for thrombocytopenia include using an electric razor. Any blade razor increases the risk of bleeding, regardless of how often it is used.'),
  ('heme', 8, 'A client with a platelet count of 30,000 has several new prescriptions. Which prescription should the nurse question?', '[{"id": "a", "text": "Medication given by intramuscular injection"}, {"id": "b", "text": "Soft-bristled toothbrush for oral care"}, {"id": "c", "text": "Electric razor for shaving"}, {"id": "d", "text": "Neurologic checks for headache or confusion"}]'::jsonb, '["a"]', 'Platelets below 50,000 carry significant bleeding risk, and IM injections are avoided. A soft toothbrush, an electric razor, and monitoring for intracranial bleeding are appropriate precautions.'),
  ('heme', 9, 'A client with leukemia and a platelet count of 15,000 reports a new headache and is confused. Which complication should the nurse suspect?', '[{"id": "a", "text": "Fatigue related to anemia"}, {"id": "b", "text": "Possible intracranial bleeding"}, {"id": "c", "text": "Hypercalcemia from bone lesions"}, {"id": "d", "text": "Graft-versus-host disease"}]'::jsonb, '["b"]', 'Clients with thrombocytopenia are monitored for intracranial bleeding, which presents with headache and confusion. Hypercalcemia from bone lesions is a feature of multiple myeloma, not leukemia.'),
  ('heme', 10, 'The nurse teaches bleeding precautions to a client with thrombocytopenia. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will brush my teeth with a soft toothbrush."}, {"id": "b", "text": "I will use an electric razor when I shave."}, {"id": "c", "text": "I will bear down hard when I have a bowel movement."}, {"id": "d", "text": "I will report any headache or new confusion."}]'::jsonb, '["c"]', 'Bearing down is a Valsalva maneuver, which should be avoided with thrombocytopenia. A soft toothbrush, an electric razor, and reporting signs of intracranial bleeding are correct.'),
  ('heme', 11, 'A client receiving chemotherapy has a platelet count of 45,000. How should the nurse interpret this value?', '[{"id": "a", "text": "A sign of severe neutropenia"}, {"id": "b", "text": "A significant risk of bleeding"}, {"id": "c", "text": "An emergency requiring a transfusion"}, {"id": "d", "text": "A normal value needing no precautions"}]'::jsonb, '["b"]', 'Platelets below 50,000 indicate a significant bleeding risk. The emergency threshold that may require transfusion is below 20,000, and neutropenia is measured by the ANC.'),
  ('heme', 12, 'A client newly diagnosed with leukemia asks why the disease causes infections, bleeding, and fatigue. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The leukemia cells destroy the lymph nodes first."}, {"id": "b", "text": "Abnormal proteins in the blood damage the kidneys."}, {"id": "c", "text": "The bones release too much calcium into the blood."}, {"id": "d", "text": "Abnormal white cells crowd out normal blood cells."}]'::jsonb, '["d"]', 'In leukemia, abnormal WBCs crowd out normal blood cells, leading to infections, bleeding, and anemia. Kidney damage from abnormal proteins and high calcium are features of multiple myeloma.'),
  ('heme', 13, 'The nurse assesses a client with leukemia. Which finding should the nurse attribute to a decreased red blood cell count?', '[{"id": "a", "text": "Dyspnea on exertion"}, {"id": "b", "text": "Bleeding gums"}, {"id": "c", "text": "Petechiae"}, {"id": "d", "text": "Frequent infections"}]'::jsonb, '["a"]', 'Decreased RBCs cause anemia, with fatigue, pallor, dyspnea on exertion, and weakness. Gum bleeding and petechiae result from low platelets, and infections from low WBCs.'),
  ('heme', 14, 'Which assessment finding in a client with leukemia indicates that the platelet count is likely low?', '[{"id": "a", "text": "Pallor and weakness"}, {"id": "b", "text": "Poor wound healing"}, {"id": "c", "text": "Petechiae and easy bruising"}, {"id": "d", "text": "Dyspnea on exertion"}]'::jsonb, '["c"]', 'Low platelets cause easy bruising, petechiae, prolonged bleeding, and gum bleeding. Pallor, weakness, and dyspnea reflect anemia, and poor wound healing reflects low WBCs.'),
  ('heme', 15, 'A client with leukemia has a wound that is slow to heal and has had three infections this month. The nurse recognizes these findings as related to:', '[{"id": "a", "text": "a lack of normal platelets."}, {"id": "b", "text": "a lack of normal white blood cells."}, {"id": "c", "text": "a lack of normal red blood cells."}, {"id": "d", "text": "an elevated serum calcium level."}]'::jsonb, '["b"]', 'Decreased WBCs in leukemia cause fever, frequent infections, and poor wound healing. Low platelets cause bleeding, and low RBCs cause anemia symptoms.'),
  ('heme', 16, 'A client with leukemia reports aching bone pain. The nurse understands that this symptom is most likely caused by:', '[{"id": "a", "text": "osteolytic punched-out lesions."}, {"id": "b", "text": "hypercalcemia from plasma cells."}, {"id": "c", "text": "graft-versus-host disease."}, {"id": "d", "text": "expansion of the bone marrow."}]'::jsonb, '["d"]', 'Bone pain in leukemia is caused by marrow expansion. Osteolytic punched-out lesions and hypercalcemia are features of multiple myeloma.'),
  ('heme', 17, 'The nurse reviews the history of a client newly diagnosed with leukemia. Which history finding is a recognized risk factor for leukemia?', '[{"id": "a", "text": "Long-term occupational benzene exposure"}, {"id": "b", "text": "Prior kidney transplant with immunosuppression"}, {"id": "c", "text": "African American ancestry"}, {"id": "d", "text": "Infection with HIV"}]'::jsonb, '["a"]', 'Benzene is a chemical carcinogen and a risk factor for leukemia. Organ transplant with immunosuppression and HIV are lymphoma risk factors, and African American ancestry is the highest-risk group for multiple myeloma.'),
  ('heme', 18, 'A client was treated years ago with alkylating chemotherapy for a different cancer. The nurse recognizes that this treatment history increases the client''s risk for which cancer?', '[{"id": "a", "text": "Multiple myeloma"}, {"id": "b", "text": "Leukemia"}, {"id": "c", "text": "Hodgkin''s lymphoma"}, {"id": "d", "text": "Non-Hodgkin''s lymphoma"}]'::jsonb, '["b"]', 'Prior chemotherapy, especially with alkylating agents, is a risk factor for leukemia. It is not listed among the risk factors for lymphoma or multiple myeloma.'),
  ('heme', 19, 'The parent of a 5-year-old newly diagnosed with acute lymphocytic leukemia (ALL) asks about the outlook. Which information from the nurse is accurate?', '[{"id": "a", "text": "ALL in children has an excellent prognosis."}, {"id": "b", "text": "ALL in children is slow and found by chance."}, {"id": "c", "text": "ALL in children shows the Philadelphia chromosome."}, {"id": "d", "text": "ALL in children is identified by Auer rods."}]'::jsonb, '["a"]', 'ALL is the most common leukemia in children and has an excellent prognosis in children. Slow, incidental discovery describes CLL, the Philadelphia chromosome describes CML, and Auer rods describe AML.'),
  ('heme', 20, 'An adult''s peripheral blood smear shows Auer rods. Which plan of care does the nurse anticipate?', '[{"id": "a", "text": "Watchful waiting, as the disease is slow-growing"}, {"id": "b", "text": "Oral imatinib as the first-line therapy"}, {"id": "c", "text": "Immediate treatment of an aggressive leukemia"}, {"id": "d", "text": "ABVD chemotherapy combined with radiation"}]'::jsonb, '["c"]', 'Auer rods on the smear indicate AML, which is aggressive and needs immediate treatment. Imatinib is used for CML, and ABVD is used for Hodgkin''s lymphoma.'),
  ('heme', 21, 'A 72-year-old client is found to have a slow-growing leukemia that was discovered incidentally during routine blood work. Which type of leukemia does the nurse suspect?', '[{"id": "a", "text": "Acute myelogenous leukemia (AML)"}, {"id": "b", "text": "Acute lymphocytic leukemia (ALL)"}, {"id": "c", "text": "Chronic myelogenous leukemia (CML)"}, {"id": "d", "text": "Chronic lymphocytic leukemia (CLL)"}]'::jsonb, '["d"]', 'CLL occurs in elderly clients over 60, is slow, and is often discovered incidentally. CML is also slow but affects middle-aged adults, while AML and ALL progress rapidly.'),
  ('heme', 22, 'A 50-year-old client with leukemia tests positive for the Philadelphia chromosome (BCR-ABL). Which medication does the nurse anticipate?', '[{"id": "a", "text": "Rituximab"}, {"id": "b", "text": "Imatinib"}, {"id": "c", "text": "Bortezomib"}, {"id": "d", "text": "Zoledronic acid"}]'::jsonb, '["b"]', 'The Philadelphia chromosome is specific for CML, which is treated with imatinib, a BCR-ABL inhibitor. Rituximab is used for non-Hodgkin''s lymphoma, and bortezomib and zoledronic acid are used for multiple myeloma.'),
  ('heme', 23, 'A client with chronic myelogenous leukemia (CML) asks whether the disease will always stay slow. The nurse knows that CML can progress to:', '[{"id": "a", "text": "graft-versus-host disease."}, {"id": "b", "text": "Reed-Sternberg cell growth."}, {"id": "c", "text": "a blast crisis."}, {"id": "d", "text": "Bence-Jones proteinuria."}]'::jsonb, '["c"]', 'CML is slow but can progress to blast crisis. Reed-Sternberg cells are found in Hodgkin''s lymphoma, and Bence-Jones proteins are found in myeloma.'),
  ('heme', 24, 'A nursing student is reviewing the types of leukemia. Which statement by the student is accurate?', '[{"id": "a", "text": "AML is the most common acute leukemia in adults."}, {"id": "b", "text": "ALL is the most common leukemia in older adults."}, {"id": "c", "text": "CLL progresses rapidly and is an emergency."}, {"id": "d", "text": "CML occurs most often in young children."}]'::jsonb, '["a"]', 'AML is the most common acute leukemia in adults. ALL is most common in children, CLL is slow, and CML occurs in middle-aged adults.'),
  ('heme', 25, 'A client reports a lump in the neck. Which finding should the nurse recognize as most characteristic of lymphoma?', '[{"id": "a", "text": "Painful lymph node enlargement"}, {"id": "b", "text": "Petechiae over the neck and chest"}, {"id": "c", "text": "Bone pain over the collarbone"}, {"id": "d", "text": "Painless lymph node enlargement"}]'::jsonb, '["d"]', 'Lymphoma, a cancer of the lymphatic system, presents as painless lymph node enlargement. Painful node enlargement does not match this classic presentation, and petechiae reflect low platelets.'),
  ('heme', 26, 'A lymph node biopsy reveals Reed-Sternberg cells. The nurse recognizes this finding as the hallmark of which condition?', '[{"id": "a", "text": "Non-Hodgkin''s lymphoma"}, {"id": "b", "text": "Hodgkin''s lymphoma"}, {"id": "c", "text": "Multiple myeloma"}, {"id": "d", "text": "Chronic myelogenous leukemia"}]'::jsonb, '["b"]', 'Reed-Sternberg (owl-eye) giant cells are the hallmark of Hodgkin''s lymphoma. Non-Hodgkin''s lymphoma has no Reed-Sternberg cells.'),
  ('heme', 27, 'Imaging of a client with lymphoma shows involved lymph nodes in noncontiguous areas, with uninvolved node groups in between. Which diagnosis does this spread pattern suggest?', '[{"id": "a", "text": "Hodgkin''s lymphoma"}, {"id": "b", "text": "Multiple myeloma"}, {"id": "c", "text": "Non-Hodgkin''s lymphoma"}, {"id": "d", "text": "Acute myelogenous leukemia"}]'::jsonb, '["c"]', 'Non-Hodgkin''s lymphoma spreads in a non-contiguous skip pattern. Hodgkin''s lymphoma, which has Reed-Sternberg cells, spreads in an orderly, contiguous way, usually starting in the cervical nodes.'),
  ('heme', 28, 'Four clients present with painless lymph node enlargement. Which client is in a peak age group for Hodgkin''s lymphoma?', '[{"id": "a", "text": "A 24-year-old client"}, {"id": "b", "text": "A 45-year-old client"}, {"id": "c", "text": "A 52-year-old client"}, {"id": "d", "text": "An 8-year-old client"}]'::jsonb, '["a"]', 'Hodgkin''s lymphoma has a bimodal age peak in young adults (15–35) and the elderly (over 60). Ages 8, 45, and 52 fall outside both peaks.'),
  ('heme', 29, 'A client is diagnosed with Hodgkin''s lymphoma. Which treatment regimen does the nurse anticipate?', '[{"id": "a", "text": "CHOP chemotherapy plus rituximab"}, {"id": "b", "text": "ABVD chemotherapy plus radiation"}, {"id": "c", "text": "Imatinib as targeted therapy"}, {"id": "d", "text": "Bortezomib plus lenalidomide"}]'::jsonb, '["b"]', 'Hodgkin''s lymphoma is treated with the ABVD regimen plus radiation. CHOP plus rituximab is used for non-Hodgkin''s lymphoma, and imatinib is used for CML.'),
  ('heme', 30, 'A client with non-Hodgkin''s lymphoma who is receiving CHOP plus rituximab asks what rituximab is. The nurse explains that rituximab is:', '[{"id": "a", "text": "a proteasome inhibitor."}, {"id": "b", "text": "a BCR-ABL inhibitor."}, {"id": "c", "text": "an anti-CD20 monoclonal antibody."}, {"id": "d", "text": "a bisphosphonate."}]'::jsonb, '["c"]', 'Rituximab is an anti-CD20 monoclonal antibody given with CHOP for non-Hodgkin''s lymphoma. Bortezomib is a proteasome inhibitor, and imatinib is a BCR-ABL inhibitor.'),
  ('heme', 31, 'The nurse compares Hodgkin''s and non-Hodgkin''s lymphoma for a client. Which statement is accurate?', '[{"id": "a", "text": "Hodgkin''s lymphoma is more common than non-Hodgkin''s."}, {"id": "b", "text": "Non-Hodgkin''s lymphoma contains Reed-Sternberg cells."}, {"id": "c", "text": "Non-Hodgkin''s lymphoma has the better prognosis overall."}, {"id": "d", "text": "Hodgkin''s lymphoma is highly curable with ABVD chemo."}]'::jsonb, '["d"]', 'Hodgkin''s lymphoma has a better overall prognosis and is highly curable with ABVD chemotherapy. Non-Hodgkin''s lymphoma is more common, lacks Reed-Sternberg cells, and generally has a worse prognosis.'),
  ('heme', 32, 'A client with lymphoma reports drenching, recurrent night sweats. How should the nurse interpret this finding?', '[{"id": "a", "text": "A B symptom suggesting systemic involvement"}, {"id": "b", "text": "An expected effect needing no follow-up"}, {"id": "c", "text": "A sign of graft-versus-host disease"}, {"id": "d", "text": "A symptom of hypercalcemia from bone lesions"}]'::jsonb, '["a"]', 'Drenching, recurrent night sweats are a B symptom, which indicates systemic disease involvement and a worse prognosis. Hypercalcemia is a feature of multiple myeloma.'),
  ('heme', 33, 'Four clients with lymphoma report weight changes. Which client''s weight loss meets the criterion for a B symptom?', '[{"id": "a", "text": "Lost 3 kg from 80 kg over 6 months"}, {"id": "b", "text": "Lost 9 kg from 80 kg over 5 months"}, {"id": "c", "text": "Lost 5 kg from 100 kg over 6 months"}, {"id": "d", "text": "Lost 4 kg from 60 kg over 6 months"}]'::jsonb, '["b"]', 'A B symptom weight loss is more than 10% of body weight in 6 months, and 9 kg of 80 kg is about 11%. The other losses are about 4%, 5%, and 7%.'),
  ('heme', 34, 'After teaching a client with lymphoma about B symptoms, which client statement indicates understanding?', '[{"id": "a", "text": "The painless swollen node itself is my main B symptom."}, {"id": "b", "text": "B symptoms mean my disease is limited to one node."}, {"id": "c", "text": "Fever, night sweats, and weight loss can mean systemic disease."}, {"id": "d", "text": "B symptoms are expected and mean a better prognosis."}]'::jsonb, '["c"]', 'B symptoms are fever, night sweats, and weight loss over 10%, and they indicate systemic lymphoma involvement with a worse prognosis. They do not suggest limited disease or a better prognosis.'),
  ('heme', 35, 'A client who had a kidney transplant 6 years ago takes immunosuppressive drugs. Because of this history, the nurse should be alert for signs of which cancer?', '[{"id": "a", "text": "Lymphoma"}, {"id": "b", "text": "Multiple myeloma"}, {"id": "c", "text": "Chronic myelogenous leukemia"}, {"id": "d", "text": "Acute lymphocytic leukemia"}]'::jsonb, '["a"]', 'A prior organ transplant with immunosuppressive drugs is a risk factor for lymphoma. It is not a listed risk factor for multiple myeloma or leukemia.'),
  ('heme', 36, 'A client with enlarged lymph nodes is being evaluated for lymphoma. Which test does the nurse anticipate will confirm the diagnosis?', '[{"id": "a", "text": "Bone marrow biopsy"}, {"id": "b", "text": "Lymph node biopsy"}, {"id": "c", "text": "Skeletal survey"}, {"id": "d", "text": "Serum LDH level"}]'::jsonb, '["b"]', 'A lymph node biopsy is definitive for lymphoma and identifies Reed-Sternberg cells or the NHL subtype. A bone marrow biopsy is definitive for leukemia and myeloma, and LDH is a marker of tumor burden.'),
  ('heme', 37, 'A client''s CBC differential shows abnormal cell types, and leukemia is suspected. Which test will provide the definitive diagnosis?', '[{"id": "a", "text": "Lymph node biopsy"}, {"id": "b", "text": "CT/PET scan"}, {"id": "c", "text": "Bone marrow biopsy"}, {"id": "d", "text": "Skeletal survey"}]'::jsonb, '["c"]', 'A bone marrow biopsy is definitive for leukemia and shows marrow infiltration by abnormal cells. A lymph node biopsy is definitive for lymphoma, and a skeletal survey shows myeloma bone lesions.'),
  ('heme', 38, 'A client has just been diagnosed with lymphoma. Which test does the nurse anticipate will be used to stage the disease?', '[{"id": "a", "text": "Skeletal survey"}, {"id": "b", "text": "Urine electrophoresis"}, {"id": "c", "text": "Philadelphia chromosome test"}, {"id": "d", "text": "CT/PET scan"}]'::jsonb, '["d"]', 'CT/PET scanning is used for lymphoma staging because it identifies lymph node involvement and organ spread. The skeletal survey and electrophoresis are used for myeloma, and the Philadelphia chromosome test is used for CML.'),
  ('heme', 39, 'A client with lymphoma has an elevated LDH level. The nurse interprets this finding as:', '[{"id": "a", "text": "a marker of tumor burden and prognosis."}, {"id": "b", "text": "evidence of Bence-Jones proteins in urine."}, {"id": "c", "text": "a sign of the Philadelphia chromosome."}, {"id": "d", "text": "confirmation of Reed-Sternberg cells."}]'::jsonb, '["a"]', 'LDH is elevated in lymphoma and is a marker of tumor burden and prognosis. Reed-Sternberg cells are confirmed by lymph node biopsy, and Bence-Jones proteins are found by electrophoresis.'),
  ('heme', 40, 'A client newly diagnosed with multiple myeloma asks what kind of cancer it is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It is a cancer of the lymph nodes that causes painless swelling."}, {"id": "b", "text": "It is a cancer of plasma cells, which make antibodies."}, {"id": "c", "text": "It is a cancer of blood cells with the Philadelphia chromosome."}, {"id": "d", "text": "It is a cancer of white cells that occurs mostly in children."}]'::jsonb, '["b"]', 'Multiple myeloma is a cancer of antibody-producing plasma cells in the bone marrow. Painless node swelling describes lymphoma, the Philadelphia chromosome describes CML, and a childhood leukemia describes ALL.'),
  ('heme', 41, 'A client with multiple myeloma develops nausea, constipation, and new confusion. Which complication should the nurse suspect?', '[{"id": "a", "text": "Graft-versus-host disease"}, {"id": "b", "text": "Severe neutropenia"}, {"id": "c", "text": "Hypercalcemia"}, {"id": "d", "text": "Blast crisis"}]'::jsonb, '["c"]', 'In multiple myeloma, elevated calcium causes nausea, constipation, confusion, and kidney stones. Blast crisis is a progression of CML.'),
  ('heme', 42, 'Urine electrophoresis for a client with multiple myeloma shows Bence-Jones proteins. Which assessment is most important for the nurse to monitor?', '[{"id": "a", "text": "Peripheral smear for Auer rods"}, {"id": "b", "text": "Lymph nodes for painless swelling"}, {"id": "c", "text": "Philadelphia chromosome status"}, {"id": "d", "text": "BUN and creatinine levels"}]'::jsonb, '["d"]', 'Bence-Jones proteins damage the kidney tubules, causing renal failure with rising BUN and creatinine, so renal function is monitored. Auer rods relate to AML, and the Philadelphia chromosome relates to CML.'),
  ('heme', 43, 'A skeletal survey of a client with multiple myeloma shows punched-out lytic lesions. Which nursing intervention is the priority?', '[{"id": "a", "text": "Implement fall precautions to prevent pathologic fractures."}, {"id": "b", "text": "Encourage high-impact exercise to strengthen the bones."}, {"id": "c", "text": "Defer fall precautions until the pain is controlled."}, {"id": "d", "text": "Delay pain management until the lesions are treated."}]'::jsonb, '["a"]', 'Osteolytic lesions in myeloma cause pathologic fractures, so bone pain management, fall precautions, and fracture prevention are priorities. Deferring fall precautions or delaying pain management goes against these priorities.'),
  ('heme', 44, 'A client with multiple myeloma is prescribed zoledronic acid and asks why. The nurse explains that the medication is given to:', '[{"id": "a", "text": "inhibit the BCR-ABL protein."}, {"id": "b", "text": "prevent pathologic fractures."}, {"id": "c", "text": "treat graft-versus-host disease."}, {"id": "d", "text": "stimulate red blood cell production."}]'::jsonb, '["b"]', 'Zoledronic acid is a bisphosphonate given to prevent pathologic fractures in myeloma. BCR-ABL inhibition describes imatinib, and EPO is used to treat anemia.'),
  ('heme', 45, 'A client with multiple myeloma will begin bortezomib. Which statement by the nurse correctly describes the drug?', '[{"id": "a", "text": "It is an anti-CD20 monoclonal antibody."}, {"id": "b", "text": "It is a BCR-ABL inhibitor."}, {"id": "c", "text": "It is a proteasome inhibitor."}, {"id": "d", "text": "It is a bisphosphonate."}]'::jsonb, '["c"]', 'Bortezomib (Velcade) is a proteasome inhibitor that disrupts plasma cell survival. Rituximab is the anti-CD20 antibody, and imatinib is the BCR-ABL inhibitor.'),
  ('heme', 46, 'Which client has the highest risk profile for multiple myeloma?', '[{"id": "a", "text": "A 30-year-old woman"}, {"id": "b", "text": "A 35-year-old man"}, {"id": "c", "text": "A 10-year-old child with Down syndrome"}, {"id": "d", "text": "A 70-year-old African American man"}]'::jsonb, '["d"]', 'Myeloma risk factors include being African American (the highest-risk group), age over 65, and male sex. Myeloma is rare before age 40, and Down syndrome is a leukemia risk factor.'),
  ('heme', 47, 'Three weeks after an allogeneic stem cell transplant, a client develops a rash, signs of liver damage, and GI symptoms. Which complication should the nurse suspect?', '[{"id": "a", "text": "Graft-versus-host disease"}, {"id": "b", "text": "Blast crisis"}, {"id": "c", "text": "Hypercalcemia"}, {"id": "d", "text": "B symptoms of lymphoma"}]'::jsonb, '["a"]', 'Graft-versus-host disease is a complication of allogeneic (donor) stem cell transplant and presents with rash, liver damage, and GI involvement. Blast crisis is a progression of CML.'),
  ('heme', 48, 'The nurse teaches a client who is scheduled for an autologous stem cell transplant. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "The stem cells will be collected from my own body."}, {"id": "b", "text": "My own cells will give me a strong graft-versus-tumor effect."}, {"id": "c", "text": "Using my own cells means a lower risk of rejection."}, {"id": "d", "text": "My collected cells will be reinfused into me later."}]'::jsonb, '["b"]', 'An autologous transplant uses the client''s own cells, which carries a lower rejection risk but provides no graft-versus-tumor effect. Collecting and reinfusing the client''s own cells is accurate.'),
  ('heme', 49, 'The nurse explains the phases of leukemia treatment to a client. Which sequence of phases is correct?', '[{"id": "a", "text": "Maintenance, induction, consolidation"}, {"id": "b", "text": "Consolidation, induction, maintenance"}, {"id": "c", "text": "Induction, maintenance, consolidation"}, {"id": "d", "text": "Induction, consolidation, maintenance"}]'::jsonb, '["d"]', 'Induction is intensive chemotherapy to achieve remission, consolidation then prevents relapse during remission, and maintenance is long-term low-intensity chemotherapy. Consolidation cannot come first because it requires remission.'),
  ('heme', 50, 'A client with lymphoma is scheduled to start chemotherapy at 1000 and has a prescribed antiemetic. When should the nurse administer the antiemetic?', '[{"id": "a", "text": "After the client first vomits"}, {"id": "b", "text": "Before the chemotherapy starts"}, {"id": "c", "text": "Only if nausea lasts over 24 hours"}, {"id": "d", "text": "At the end of the chemotherapy infusion"}]'::jsonb, '["b"]', 'Antiemetics are given before chemotherapy as a key nursing intervention. Waiting until vomiting or prolonged nausea occurs delays prevention.'),
  ('gi_cancers', 1, 'A nurse reviews the history of a client admitted with progressive difficulty swallowing. Which history finding is the most significant risk factor for esophageal cancer?', '[{"id": "a", "text": "Chronic Helicobacter pylori gastric infection"}, {"id": "b", "text": "Long-standing GERD with Barrett''s esophagus"}, {"id": "c", "text": "Chronic hepatitis C with liver cirrhosis"}, {"id": "d", "text": "Long-standing chronic pancreatitis history"}]'::jsonb, '["b"]', 'GERD/Barrett''s esophagus is the #1 risk factor for esophageal cancer because chronic acid exposure causes metaplasia. H. pylori is the #1 modifiable risk for gastric cancer, not esophageal cancer.'),
  ('gi_cancers', 2, 'A client with suspected esophageal cancer describes their swallowing difficulty. Which description is consistent with the expected pattern?', '[{"id": "a", "text": "\"Solids stuck first, and now even liquids are hard to swallow.\""}, {"id": "b", "text": "\"Liquids were hard at first, and now solid foods are hard too.\""}, {"id": "c", "text": "\"Only liquids are hard to swallow; solid foods go down easily.\""}, {"id": "d", "text": "\"Swallowing was hard for a week and has now fully resolved.\""}]'::jsonb, '["a"]', 'Esophageal cancer causes progressive dysphagia that begins with solids and then progresses to liquids. A pattern starting with liquids reverses the expected progression.'),
  ('gi_cancers', 3, 'A client with esophageal cancer develops new hoarseness. The nurse recognizes that this finding most likely reflects which process?', '[{"id": "a", "text": "Bile salt deposits irritating the vocal cords"}, {"id": "b", "text": "Tumor involvement of the laryngeal nerve"}, {"id": "c", "text": "Iron-deficiency anemia from occult bleeding"}, {"id": "d", "text": "Distension of the liver capsule by tumor"}]'::jsonb, '["b"]', 'Hoarseness in esophageal cancer reflects laryngeal nerve involvement. Bile salt deposits cause pruritus in pancreatic cancer, and occult bleeding causes anemia, not hoarseness.'),
  ('gi_cancers', 4, 'A client is 2 days post-esophagectomy. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Tolerating sips of clear liquids"}, {"id": "b", "text": "New fever with chest pain"}, {"id": "c", "text": "Head of bed maintained at 40 degrees"}, {"id": "d", "text": "Requesting help to change position"}]'::jsonb, '["b"]', 'Fever and chest pain after esophagectomy are signs of an anastomotic leak and must be reported. Keeping the HOB at 30–45° and tolerating liquids are expected parts of post-op care.'),
  ('gi_cancers', 5, 'The nurse is supervising unlicensed assistive personnel (UAP) caring for a client after an esophagectomy. Which action by the UAP requires correction?', '[{"id": "a", "text": "Raising the head of the bed to 35 degrees"}, {"id": "b", "text": "Reporting the client''s new chest pain"}, {"id": "c", "text": "Offering liquids as ordered by the provider"}, {"id": "d", "text": "Lowering the head of the bed flat for comfort"}]'::jsonb, '["d"]', 'After esophagectomy the head of the bed should be elevated 30–45°, so lowering it flat requires correction. Reporting chest pain is appropriate because it may signal an anastomotic leak.'),
  ('gi_cancers', 6, 'The nurse is teaching a community group about lowering esophageal cancer risk. Which recommendation should the nurse include?', '[{"id": "a", "text": "Drink tea and coffee while very hot"}, {"id": "b", "text": "Gain weight above a healthy range"}, {"id": "c", "text": "Stop smoking and limit alcohol intake"}, {"id": "d", "text": "Choose smoked and cured meats daily"}]'::jsonb, '["c"]', 'Smoking and alcohol are risk factors for esophageal cancer, so cessation and limiting alcohol reduce risk. Hot liquids and obesity are also listed esophageal risk factors and should be avoided, not encouraged.'),
  ('gi_cancers', 7, 'A client with progressive dysphagia is scheduled for diagnostic testing. Which test will provide tissue to confirm esophageal cancer?', '[{"id": "a", "text": "Annual fecal occult blood test"}, {"id": "b", "text": "Serum CA 19-9 tumor marker"}, {"id": "c", "text": "Abdominal ultrasound imaging"}, {"id": "d", "text": "Upper endoscopy with biopsy"}]'::jsonb, '["d"]', 'Esophageal cancer is diagnosed by upper endoscopy with biopsy; a barium swallow may show stricture or irregularity. CA 19-9 is a pancreatic cancer marker, not an esophageal diagnostic test.'),
  ('gi_cancers', 8, 'A client with esophageal cancer reports pain every time they swallow. How should the nurse document this finding?', '[{"id": "a", "text": "Odynophagia"}, {"id": "b", "text": "Regurgitation"}, {"id": "c", "text": "Hematochezia"}, {"id": "d", "text": "Early satiety"}]'::jsonb, '["a"]', 'Odynophagia is painful swallowing. Regurgitation is a separate symptom of esophageal cancer, and early satiety is a symptom of gastric cancer.'),
  ('gi_cancers', 9, 'A client reports feeling full after only a few bites, epigastric discomfort, and unintended weight loss. The nurse recognizes these findings are most consistent with which cancer?', '[{"id": "a", "text": "Gastric cancer"}, {"id": "b", "text": "Colorectal cancer"}, {"id": "c", "text": "Liver cancer"}, {"id": "d", "text": "Pancreatic cancer"}]'::jsonb, '["a"]', 'Early satiety, epigastric pain, and unintended weight loss are symptoms of gastric cancer. Pancreatic cancer causes weight loss but is characterized by painless jaundice, clay-colored stools, and new-onset diabetes.'),
  ('gi_cancers', 10, 'A client with epigastric pain undergoes testing. Which finding represents the most significant modifiable risk factor for gastric cancer?', '[{"id": "a", "text": "Positive Helicobacter pylori test"}, {"id": "b", "text": "Blood type A"}, {"id": "c", "text": "Family history of gastric cancer"}, {"id": "d", "text": "Barrett''s esophagus on biopsy"}]'::jsonb, '["a"]', 'H. pylori infection is the #1 modifiable risk factor for gastric cancer. Blood type A and family history are gastric cancer risk factors that the client cannot change.'),
  ('gi_cancers', 11, 'The nurse teaches a client with a family history of gastric cancer about dietary risk. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will cut back on smoked meats and smoked fish.\""}, {"id": "b", "text": "\"I will limit pickled vegetables in my meals.\""}, {"id": "c", "text": "\"I can keep eating pickled and cured foods daily.\""}, {"id": "d", "text": "\"I will choose fewer cured foods like ham.\""}]'::jsonb, '["c"]', 'Smoked, pickled, and cured foods are risk factors for gastric cancer, so planning to eat them daily shows a need for more teaching. The other statements correctly reduce these foods.'),
  ('gi_cancers', 12, 'A client with gastric cancer has fatigue and pallor. The nurse anticipates which laboratory finding related to the disease?', '[{"id": "a", "text": "Polycythemia"}, {"id": "b", "text": "Iron-deficiency anemia"}, {"id": "c", "text": "Elevated AFP level"}, {"id": "d", "text": "Elevated CA 19-9 level"}]'::jsonb, '["b"]', 'Gastric cancer can cause occult (hidden) GI bleeding that leads to iron-deficiency anemia. AFP is a marker for liver cancer and CA 19-9 for pancreatic cancer.'),
  ('gi_cancers', 13, 'A client''s biopsy confirms gastric cancer, and a CT scan is ordered. The client asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The CT scan tests for H. pylori infection.\""}, {"id": "b", "text": "\"The CT scan helps determine the cancer''s stage.\""}, {"id": "c", "text": "\"The CT scan is needed to obtain a tissue sample.\""}, {"id": "d", "text": "\"The CT scan replaces the need for endoscopy.\""}]'::jsonb, '["b"]', 'In gastric cancer, CT scan is used for staging, while upper endoscopy with biopsy establishes the diagnosis. H. pylori is identified through separate H. pylori testing.'),
  ('gi_cancers', 14, 'A client with gastric cancer is prescribed trastuzumab (Herceptin). The nurse understands this therapy is indicated because the tumor has which characteristic?', '[{"id": "a", "text": "MSI-H/dMMR status"}, {"id": "b", "text": "HER2-positive status"}, {"id": "c", "text": "Elevated AFP level"}, {"id": "d", "text": "Elevated CEA level"}]'::jsonb, '["b"]', 'Trastuzumab is used in gastric cancer when the tumor is HER2-positive. MSI-H/dMMR status is the indication for nivolumab in colorectal cancer.'),
  ('gi_cancers', 15, 'A client who had a gastrectomy reports dizziness, sweating, nausea, and a racing heart 20 minutes after lunch. The nurse interprets these findings as which condition?', '[{"id": "a", "text": "Late dumping syndrome"}, {"id": "b", "text": "Anastomotic leak"}, {"id": "c", "text": "Bile leakage"}, {"id": "d", "text": "Early dumping syndrome"}]'::jsonb, '["d"]', 'Early dumping occurs 15–30 minutes after eating and causes dizziness, sweating, nausea, diarrhea, and tachycardia. Late dumping occurs 1–3 hours after eating and causes reactive hypoglycemia.'),
  ('gi_cancers', 16, 'Two hours after eating, a client who had a partial gastrectomy reports tremors and weakness. The nurse recognizes these symptoms are caused by which problem?', '[{"id": "a", "text": "Early fluid shifts into the bowel"}, {"id": "b", "text": "Reactive hypoglycemia"}, {"id": "c", "text": "Occult GI bleeding with anemia"}, {"id": "d", "text": "Leakage at the anastomosis"}]'::jsonb, '["b"]', 'Late dumping occurs 1–3 hours after eating and causes reactive hypoglycemia with tremors and weakness. Fluid shifts with tachycardia describe early dumping at 15–30 minutes.'),
  ('gi_cancers', 17, 'The nurse teaches a client after gastrectomy how to prevent dumping syndrome. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will eat three large meals each day.\""}, {"id": "b", "text": "\"I will eat about six small meals a day.\""}, {"id": "c", "text": "\"I will add more protein and fat to meals.\""}, {"id": "d", "text": "\"I will lie down for a while after I eat.\""}]'::jsonb, '["a"]', 'Dumping syndrome is managed with small frequent meals (about 6 per day), so three large meals is incorrect. Increasing protein and fat and lying down after eating are correct strategies.'),
  ('gi_cancers', 18, 'A client recovering from a gastrectomy is choosing a breakfast. Which choice best helps prevent dumping syndrome?', '[{"id": "a", "text": "Pancakes with maple syrup"}, {"id": "b", "text": "Sweetened cereal with juice"}, {"id": "c", "text": "Toast with jam and soda"}, {"id": "d", "text": "Scrambled eggs with cheese"}]'::jsonb, '["d"]', 'Clients at risk for dumping syndrome should avoid high-carbohydrate and sugary foods and increase protein and fat. Pancakes with syrup are high in carbohydrates and sugar.'),
  ('gi_cancers', 19, 'The nurse is supervising a UAP caring for a client after a gastrectomy. Which action by the UAP requires correction?', '[{"id": "a", "text": "Helping the client lie down after each meal"}, {"id": "b", "text": "Removing a sugary dessert from the meal tray"}, {"id": "c", "text": "Walking the client in the hall after each meal"}, {"id": "d", "text": "Reporting dizziness and sweating after meals"}]'::jsonb, '["c"]', 'Lying down after eating is part of dumping syndrome management, so ambulating immediately after a meal requires correction. Removing sugary desserts is appropriate because sugary foods should be avoided.'),
  ('gi_cancers', 20, 'A client after gastrectomy asks why dumping syndrome occurs. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Food moves too fast into the small intestine and shifts fluid.\""}, {"id": "b", "text": "\"Food stays in the stomach too long and causes fluid retention.\""}, {"id": "c", "text": "\"Bile is leaking from the surgical site into your abdomen.\""}, {"id": "d", "text": "\"Stomach acid backs up and damages your esophagus lining.\""}]'::jsonb, '["a"]', 'Dumping syndrome is caused by rapid emptying of hyperosmolar food into the small intestine, leading to fluid shifts and GI symptoms. Slow emptying is the reverse of the actual mechanism.'),
  ('gi_cancers', 21, 'A 58-year-old client attends a wellness visit. Which client report should the nurse recognize as a possible sign of colorectal cancer?', '[{"id": "a", "text": "\"My stools have become pale and clay-colored.\""}, {"id": "b", "text": "\"I feel full after eating only a few bites.\""}, {"id": "c", "text": "\"Solid food sticks when I try to swallow.\""}, {"id": "d", "text": "\"My stools have become thin like a pencil.\""}]'::jsonb, '["d"]', 'Pencil-thin stools result from a narrowed bowel lumen in colorectal cancer. Clay-colored stools point to obstructive jaundice in pancreatic cancer, and early satiety suggests gastric cancer.'),
  ('gi_cancers', 22, 'A client reports bright red blood with bowel movements. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Melena"}, {"id": "b", "text": "Hematochezia"}, {"id": "c", "text": "Odynophagia"}, {"id": "d", "text": "Regurgitation"}]'::jsonb, '["b"]', 'Hematochezia is bright red rectal bleeding, while melena is dark, tarry stool. Both can occur with colorectal cancer.'),
  ('gi_cancers', 23, 'The nurse reviews the histories of four clients at a clinic. Which client has the greatest risk for colorectal cancer?', '[{"id": "a", "text": "A 52-year-old with ulcerative colitis and a low-fiber diet"}, {"id": "b", "text": "A 30-year-old who eats a high-fiber diet and runs daily"}, {"id": "c", "text": "A 35-year-old with blood type A and no symptoms"}, {"id": "d", "text": "A 28-year-old with occasional heartburn after meals"}]'::jsonb, '["a"]', 'IBD such as ulcerative colitis, a low-fiber diet, and age over 45 are colorectal cancer risk factors. A high-fiber diet and regular activity are the opposite of the listed risks of low-fiber diet and inactivity.'),
  ('gi_cancers', 24, 'A 30-year-old client whose family has familial adenomatous polyposis (FAP) asks about colorectal screening. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"You should wait until age 45 like everyone else.\""}, {"id": "b", "text": "\"A yearly CEA blood test is the best screening for you.\""}, {"id": "c", "text": "\"You may need screening earlier or more often than usual.\""}, {"id": "d", "text": "\"Screening is not needed unless you develop symptoms.\""}]'::jsonb, '["c"]', 'FAP is a genetic syndrome that raises colorectal cancer risk, and high-risk clients need earlier or more frequent screening. CEA is not used for screening.'),
  ('gi_cancers', 25, 'A 45-year-old client at average risk asks about colorectal cancer screening with colonoscopy. Which schedule should the nurse teach?', '[{"id": "a", "text": "Begin at age 50 and repeat every 5 years"}, {"id": "b", "text": "Begin now and repeat every year"}, {"id": "c", "text": "Begin now and repeat every 10 years"}, {"id": "d", "text": "Begin at age 60 and repeat every 3 years"}]'::jsonb, '["c"]', 'Colonoscopy is the gold standard screening, done every 10 years starting at age 45. Annual testing applies to FOBT, not colonoscopy.'),
  ('gi_cancers', 26, 'A client''s annual fecal occult blood test (FOBT) is positive. Which follow-up does the nurse anticipate?', '[{"id": "a", "text": "Repeat FOBT in one year"}, {"id": "b", "text": "Serum CEA level"}, {"id": "c", "text": "Colonoscopy"}, {"id": "d", "text": "Upper endoscopy with biopsy"}]'::jsonb, '["c"]', 'A positive FOBT requires follow-up colonoscopy; waiting a year to repeat the FOBT delays evaluation. CEA is a tumor marker used to monitor treatment, not to screen.'),
  ('gi_cancers', 27, 'The nurse teaches a client about the carcinoembryonic antigen (CEA) test. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"CEA is checked to see how I respond to treatment.\""}, {"id": "b", "text": "\"CEA can help detect if my cancer comes back.\""}, {"id": "c", "text": "\"CEA is a tumor marker for colorectal cancer.\""}, {"id": "d", "text": "\"A CEA test can replace my screening colonoscopy.\""}]'::jsonb, '["d"]', 'CEA is a colorectal tumor marker used to monitor treatment response and detect recurrence; it is not used for screening. Colonoscopy remains the gold standard screening test.'),
  ('gi_cancers', 28, 'A client completed treatment for colorectal cancer 1 year ago. Follow-up CEA levels have risen steadily. The nurse recognizes this trend may indicate which outcome?', '[{"id": "a", "text": "Expected response to treatment"}, {"id": "b", "text": "Possible cancer recurrence"}, {"id": "c", "text": "New H. pylori infection"}, {"id": "d", "text": "Normal healing after colectomy"}]'::jsonb, '["b"]', 'CEA is used to monitor treatment response and detect recurrence, so a rising level after treatment may signal recurrence. A rising marker does not indicate an expected treatment response.'),
  ('gi_cancers', 29, 'A client is 1 day post-colectomy with a new colostomy. Which stoma finding should the nurse report to the provider?', '[{"id": "a", "text": "Moist, pink tissue at the stoma"}, {"id": "b", "text": "Necrotic tissue at the stoma edge"}, {"id": "c", "text": "Moist, red tissue across the stoma"}, {"id": "d", "text": "Pink stoma with no necrotic areas"}]'::jsonb, '["b"]', 'Stoma assessment after colostomy checks that the stoma is moist and pink/red with no necrosis, so necrotic tissue must be reported. Moist pink or red tissue is the expected finding.'),
  ('gi_cancers', 30, 'A client newly diagnosed with colorectal cancer will start chemotherapy. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Gemcitabine chemotherapy"}, {"id": "b", "text": "5-fluorouracil (5-FU)"}, {"id": "c", "text": "Sorafenib therapy"}, {"id": "d", "text": "Trastuzumab therapy"}]'::jsonb, '["b"]', '5-fluorouracil (5-FU) is the chemotherapy listed for colorectal cancer. Gemcitabine is used for pancreatic cancer and sorafenib for liver cancer.'),
  ('gi_cancers', 31, 'Testing shows that a client''s colorectal tumor is MSI-H/dMMR. Which therapy does the nurse anticipate?', '[{"id": "a", "text": "Trastuzumab therapy"}, {"id": "b", "text": "Sorafenib therapy"}, {"id": "c", "text": "Gemcitabine chemotherapy"}, {"id": "d", "text": "Nivolumab immunotherapy"}]'::jsonb, '["d"]', 'Nivolumab immunotherapy is used for MSI-H/dMMR colorectal tumors. Trastuzumab is used for HER2-positive gastric cancer.'),
  ('gi_cancers', 32, 'The nurse teaches a client how to lower colorectal cancer risk. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will eat more processed meats and less fiber.\""}, {"id": "b", "text": "\"I''ll eat more fiber and less red or processed meat.\""}, {"id": "c", "text": "\"I will cut back on exercise to save my energy.\""}, {"id": "d", "text": "\"I will switch to a high-fat, low-fiber diet.\""}]'::jsonb, '["b"]', 'Low-fiber, high-fat diets, red/processed meat, and physical inactivity are colorectal cancer risk factors. Increasing fiber and limiting red and processed meat reduces these risks.'),
  ('gi_cancers', 33, 'A 50-year-old client reports alternating constipation and diarrhea for several weeks, abdominal cramping, and unexplained weight loss. The nurse recognizes these findings are most consistent with which cancer?', '[{"id": "a", "text": "Colorectal cancer"}, {"id": "b", "text": "Esophageal cancer"}, {"id": "c", "text": "Gastric cancer"}, {"id": "d", "text": "Liver cancer"}]'::jsonb, '["a"]', 'A change in bowel habits with alternating constipation and diarrhea, cramping, and unexplained weight loss are colorectal cancer symptoms. Gastric cancer presents with early satiety and epigastric pain.'),
  ('gi_cancers', 34, 'A nurse reviews the history of a client with a liver mass. Which finding is the most important risk factor for hepatocellular carcinoma (HCC)?', '[{"id": "a", "text": "Chronic hepatitis B infection"}, {"id": "b", "text": "Positive H. pylori infection"}, {"id": "c", "text": "Barrett''s esophagus"}, {"id": "d", "text": "BRCA2 gene mutation"}]'::jsonb, '["a"]', 'Chronic hepatitis B or C is the most important risk factor for HCC. H. pylori is the #1 modifiable risk for gastric cancer, and BRCA mutations are linked to pancreatic cancer.'),
  ('gi_cancers', 35, 'A client with cirrhosis is being evaluated for hepatocellular carcinoma. Which assessment finding should the nurse expect?', '[{"id": "a", "text": "Yellowing of the skin and sclera"}, {"id": "b", "text": "Thin, pencil-shaped stool pattern"}, {"id": "c", "text": "Hoarse, weak voice when speaking"}, {"id": "d", "text": "Feeling full after a few bites"}]'::jsonb, '["a"]', 'Jaundice (yellowing of the skin and sclera) is a symptom of HCC, along with RUQ pain, ascites, and hepatomegaly. Pencil-thin stools are a colorectal cancer symptom.'),
  ('gi_cancers', 36, 'A client with hepatocellular carcinoma reports right upper quadrant pain and asks what causes it. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Bile salts are depositing in the skin.\""}, {"id": "b", "text": "\"The tumor stretches the liver''s outer capsule.\""}, {"id": "c", "text": "\"Acid is damaging the lining of the esophagus.\""}, {"id": "d", "text": "\"Food is emptying too fast into the intestine.\""}]'::jsonb, '["b"]', 'RUQ pain in HCC results from distension of the liver capsule. Bile salt deposits cause pruritus in pancreatic cancer, not RUQ pain.'),
  ('gi_cancers', 37, 'A client with cirrhosis has an elevated alpha-fetoprotein (AFP) level. The nurse recognizes this marker is associated with which cancer?', '[{"id": "a", "text": "Colorectal carcinoma"}, {"id": "b", "text": "Pancreatic carcinoma"}, {"id": "c", "text": "Gastric carcinoma"}, {"id": "d", "text": "Hepatocellular carcinoma"}]'::jsonb, '["d"]', 'AFP is elevated in hepatocellular carcinoma and is also used in testicular cancer. CEA is the colorectal marker and CA 19-9 is the pancreatic marker.'),
  ('gi_cancers', 38, 'A client with chronic hepatitis C asks how often liver cancer screening is needed. Which plan should the nurse teach?', '[{"id": "a", "text": "Abdominal ultrasound and AFP every 6 months"}, {"id": "b", "text": "Colonoscopy and CEA level every 10 years"}, {"id": "c", "text": "CT scan and CA 19-9 level every 5 years"}, {"id": "d", "text": "Upper endoscopy with biopsy every year"}]'::jsonb, '["a"]', 'Clients with cirrhosis or chronic hepatitis B/C should have an abdominal ultrasound plus AFP every 6 months. Colonoscopy every 10 years is colorectal screening.'),
  ('gi_cancers', 39, 'A nursing student who has never received the hepatitis B vaccine asks how to lower liver cancer risk. Which action should the nurse recommend?', '[{"id": "a", "text": "Have a yearly fecal occult blood test"}, {"id": "b", "text": "Begin colonoscopy screening now"}, {"id": "c", "text": "Get tested for H. pylori infection"}, {"id": "d", "text": "Receive the hepatitis B vaccine series"}]'::jsonb, '["d"]', 'The hepatitis B vaccine prevents HepB infection, which reduces liver cancer risk. FOBT and colonoscopy are colorectal screening, and H. pylori relates to gastric cancer.'),
  ('gi_cancers', 40, 'A client with chronic hepatitis C asks how to reduce their risk of liver cancer. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I can drink alcohol as long as I take my antivirals.\""}, {"id": "b", "text": "\"I will skip antiviral therapy because I feel well.\""}, {"id": "c", "text": "\"Only my hepatitis B status affects my liver risk.\""}, {"id": "d", "text": "\"I will take antiviral therapy and avoid alcohol.\""}]'::jsonb, '["d"]', 'Liver cancer prevention includes treating hepatitis C with antivirals and avoiding alcohol. Continuing to drink is unsafe because alcohol use disorder is a liver cancer risk factor.'),
  ('gi_cancers', 41, 'A client with advanced hepatocellular carcinoma is prescribed sorafenib and asks how the drug works. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It targets HER2-positive tumor cells only.\""}, {"id": "b", "text": "\"It is an antiviral drug for hepatitis C.\""}, {"id": "c", "text": "\"It is a targeted drug that inhibits VEGF.\""}, {"id": "d", "text": "\"It is a vaccine that prevents hepatitis B.\""}]'::jsonb, '["c"]', 'Sorafenib is a targeted therapy that acts as a VEGF inhibitor in HCC. Trastuzumab is the HER2-directed drug, used in gastric cancer.'),
  ('gi_cancers', 42, 'A surveillance abdominal ultrasound shows a new lesion in a client with cirrhosis. Which imaging study does the nurse anticipate next to confirm hepatocellular carcinoma?', '[{"id": "a", "text": "Barium swallow study"}, {"id": "b", "text": "Screening colonoscopy"}, {"id": "c", "text": "Repeat ultrasound in a year"}, {"id": "d", "text": "CT or MRI of the abdomen"}]'::jsonb, '["d"]', 'Abdominal ultrasound is used for HCC screening, and CT/MRI is used for confirmation. A barium swallow evaluates the esophagus.'),
  ('gi_cancers', 43, 'A 68-year-old client has painless jaundice, clay-colored stools, and newly diagnosed diabetes mellitus. The nurse recognizes these findings most strongly suggest which condition?', '[{"id": "a", "text": "Pancreatic cancer"}, {"id": "b", "text": "Gastric cancer"}, {"id": "c", "text": "Colorectal cancer"}, {"id": "d", "text": "Esophageal cancer"}]'::jsonb, '["a"]', 'Painless jaundice, clay-colored stools, and new-onset diabetes indicate pancreatic cancer until proven otherwise. Gastric cancer presents with early satiety and epigastric pain.'),
  ('gi_cancers', 44, 'A 70-year-old male client with chronic pancreatitis smokes one pack of cigarettes daily. Which pancreatic cancer risk factor is the most significant modifiable risk?', '[{"id": "a", "text": "Cigarette smoking"}, {"id": "b", "text": "Age over 65 years"}, {"id": "c", "text": "Male sex"}, {"id": "d", "text": "Chronic pancreatitis"}]'::jsonb, '["a"]', 'Smoking is the #1 modifiable risk factor for pancreatic cancer. Age over 65 and male sex are risk factors that the client cannot change.'),
  ('gi_cancers', 45, 'A client with pancreatic cancer reports severe itching. The nurse understands this symptom is caused by which process?', '[{"id": "a", "text": "Iron-deficiency anemia"}, {"id": "b", "text": "Pancreatic islet cell destruction"}, {"id": "c", "text": "Bile salt deposits in the skin"}, {"id": "d", "text": "Liver capsule distension"}]'::jsonb, '["c"]', 'Pruritus in pancreatic cancer results from bile salt deposits. Islet cell destruction causes new-onset diabetes, not itching.'),
  ('gi_cancers', 46, 'On postoperative day 4 after a Whipple procedure, a client whose jaundice had been improving now has worsening jaundice, fever, and severe abdominal pain. The nurse suspects which complication?', '[{"id": "a", "text": "Early dumping syndrome"}, {"id": "b", "text": "Reactive hypoglycemia"}, {"id": "c", "text": "Bile leakage"}, {"id": "d", "text": "Iron-deficiency anemia"}]'::jsonb, '["c"]', 'After a Whipple procedure, severe abdominal pain, fever, and jaundice worsening after initial improvement signal bile leakage. Dumping syndrome is a post-gastrectomy complication with dizziness, sweating, and tachycardia after meals.'),
  ('gi_cancers', 47, 'A client is recovering from a Whipple procedure. Which assessment is a priority because of disrupted pancreatic endocrine function?', '[{"id": "a", "text": "Stoma color checks"}, {"id": "b", "text": "Fecal occult blood testing"}, {"id": "c", "text": "Serum AFP monitoring"}, {"id": "d", "text": "Blood glucose monitoring"}]'::jsonb, '["d"]', 'After a Whipple procedure, blood glucose must be monitored because endocrine function is disrupted. Stoma checks apply to colostomy care, not the Whipple procedure.'),
  ('gi_cancers', 48, 'A client after a Whipple procedure asks why the nurse closely monitors nutritional status. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Loss of exocrine function causes early dumping.\""}, {"id": "b", "text": "\"The surgery removed most of the liver tissue.\""}, {"id": "c", "text": "\"Loss of exocrine function can cause malabsorption.\""}, {"id": "d", "text": "\"Bile salts in the skin reduce your appetite.\""}]'::jsonb, '["c"]', 'Nutritional status is monitored after a Whipple procedure because loss of exocrine function causes malabsorption. The procedure removes the head of the pancreas, duodenum, and part of the common bile duct, not liver tissue.'),
  ('gi_cancers', 49, 'A client with suspected pancreatic cancer asks whether an elevated CA 19-9 level confirms the diagnosis. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, an elevated level confirms pancreatic cancer.\""}, {"id": "b", "text": "\"It is the gold standard test to diagnose the cancer.\""}, {"id": "c", "text": "\"It is not diagnostic alone; it is used for monitoring.\""}, {"id": "d", "text": "\"It is used mainly to screen healthy adults yearly.\""}]'::jsonb, '["c"]', 'CA 19-9 is a pancreatic tumor marker that is not diagnostic alone and is used for monitoring. CT abdomen, not CA 19-9, is the gold standard imaging for pancreatic cancer.'),
  ('gi_cancers', 50, 'A client scheduled for a Whipple procedure asks what will be removed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The entire stomach and the lower part of the esophagus.\""}, {"id": "b", "text": "\"The tail of the pancreas, spleen, and part of the colon.\""}, {"id": "c", "text": "\"The pancreatic head, duodenum, and part of the bile duct.\""}, {"id": "d", "text": "\"The right lobe of the liver and the gallbladder only.\""}]'::jsonb, '["c"]', 'The Whipple procedure (pancreaticoduodenectomy) removes the head of the pancreas, the duodenum, and part of the common bile duct. Removal of the stomach describes a gastrectomy.'),
  ('large_organ', 1, 'A nurse reviews the history of a client with a newly found liver mass. Which history finding is the most important risk factor for hepatocellular carcinoma (HCC)?', '[{"id": "a", "text": "Von Hippel-Lindau syndrome"}, {"id": "b", "text": "Residential radon exposure"}, {"id": "c", "text": "Chronic hepatitis C infection"}, {"id": "d", "text": "BRCA2 gene mutation"}]'::jsonb, '["c"]', 'Chronic hepatitis B or C is the most important risk factor for HCC. VHL syndrome is a genetic risk for renal cell carcinoma, and radon is a lung cancer risk.'),
  ('large_organ', 2, 'A client with cirrhosis asks how often liver cancer surveillance is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"An abdominal ultrasound every 6 months.\""}, {"id": "b", "text": "\"A low-dose chest CT once a year.\""}, {"id": "c", "text": "\"An abdominal ultrasound every 5 years.\""}, {"id": "d", "text": "\"An AFP level only if you develop pain.\""}]'::jsonb, '["a"]', 'Clients with cirrhosis or chronic hepatitis B need surveillance abdominal ultrasound every 6 months. Annual low-dose CT is lung cancer screening for high-risk smokers.'),
  ('large_organ', 3, 'A client with cirrhosis has an elevated alpha-fetoprotein (AFP) level and asks, "Does this mean I definitely have liver cancer?" Which response by the nurse is best?', '[{"id": "a", "text": "\"Yes, an elevated AFP level confirms liver cancer.\""}, {"id": "b", "text": "\"AFP is a marker for pancreatic cancer instead.\""}, {"id": "c", "text": "\"AFP is a key marker, but it is not diagnostic alone.\""}, {"id": "d", "text": "\"AFP is used only to monitor kidney cancer.\""}]'::jsonb, '["c"]', 'AFP is a key HCC tumor marker that is elevated in HCC but is not diagnostic alone. CA 19-9, not AFP, is the pancreatic cancer marker.'),
  ('large_organ', 4, 'A client with a liver lesion undergoes CT of the abdomen. Which imaging pattern does the nurse recognize as characteristic of HCC?', '[{"id": "a", "text": "Atelectasis with pleural effusion"}, {"id": "b", "text": "Mass with pancreatic duct dilation"}, {"id": "c", "text": "Recurrent infiltrate in one lobe"}, {"id": "d", "text": "Arterial enhancement with washout"}]'::jsonb, '["d"]', 'On CT/MRI, arterial enhancement plus a washout pattern characterizes HCC. Atelectasis and pleural effusion are chest x-ray findings that may occur with lung cancer.'),
  ('large_organ', 5, 'A client with cirrhosis is diagnosed with HCC. Which additional assessment findings should the nurse anticipate?', '[{"id": "a", "text": "Spider angiomas and caput medusae"}, {"id": "b", "text": "Hemoptysis and recurrent pneumonia"}, {"id": "c", "text": "Painless hematuria and a flank mass"}, {"id": "d", "text": "Polycythemia and new hypertension"}]'::jsonb, '["a"]', 'Spider angiomas and caput medusae are expected in HCC when the client is cirrhotic. Painless hematuria with a flank mass, polycythemia, and hypertension point to renal cell carcinoma.'),
  ('large_organ', 6, 'A client with HCC reports a constant ache in the right upper quadrant and asks why. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The tumor is stretching the capsule around the liver.\""}, {"id": "b", "text": "\"Bile salts are building up in your skin.\""}, {"id": "c", "text": "\"The tumor is pressing on a nerve to your voice box.\""}, {"id": "d", "text": "\"Your kidney is producing too much renin.\""}]'::jsonb, '["a"]', 'RUQ pain in HCC is caused by liver capsule distension. Bile salt deposits in the skin cause pruritus in pancreatic cancer, not RUQ pain.'),
  ('large_organ', 7, 'The nurse teaches a client with non-alcoholic fatty liver disease (NAFLD) about liver cancer prevention. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will work toward a healthy body weight over time.\""}, {"id": "b", "text": "\"I will avoid drinking alcohol completely from now on.\""}, {"id": "c", "text": "\"I don''t drink, so my weight doesn''t affect my risk.\""}, {"id": "d", "text": "\"I will get the hepatitis B vaccine series soon.\""}]'::jsonb, '["c"]', 'NAFLD/NASH is an HCC risk factor, and prevention includes maintaining a healthy weight, so weight matters even without alcohol use. Avoiding alcohol and HepB vaccination are correct prevention measures.'),
  ('large_organ', 8, 'A farm worker reports years of exposure to moldy stored grain and peanuts. The nurse recognizes this exposure increases risk for which cancer?', '[{"id": "a", "text": "Renal cell carcinoma"}, {"id": "b", "text": "Small cell lung cancer"}, {"id": "c", "text": "Pancreatic cancer"}, {"id": "d", "text": "Hepatocellular carcinoma"}]'::jsonb, '["d"]', 'Aflatoxin exposure from mold on grains and peanuts is a risk factor for HCC. Radon and asbestos, not aflatoxin, are the environmental exposures listed for lung cancer.'),
  ('large_organ', 9, 'A client has a single, localized hepatocellular carcinoma. Which treatment does the nurse anticipate for this localized disease?', '[{"id": "a", "text": "Whipple procedure"}, {"id": "b", "text": "Nephrectomy"}, {"id": "c", "text": "Liver resection"}, {"id": "d", "text": "Lobectomy"}]'::jsonb, '["c"]', 'Liver resection is the treatment listed for localized HCC; other options include transplant, sorafenib, and TACE. The Whipple procedure is used for pancreatic cancer.'),
  ('large_organ', 10, 'During a smoking-cessation class, a participant asks how strongly smoking is linked to lung cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Smoking causes about 85% of lung cancers.\""}, {"id": "b", "text": "\"Smoking causes about 15% of lung cancers.\""}, {"id": "c", "text": "\"Radon causes more lung cancer than smoking.\""}, {"id": "d", "text": "\"Smoking matters only with asbestos exposure.\""}]'::jsonb, '["a"]', 'Smoking is the #1 cause of lung cancer, responsible for approximately 85% of cases. Radon and asbestos are additional risk factors but are not the leading cause.'),
  ('large_organ', 11, 'A retired shipyard worker with years of asbestos exposure smokes a pack of cigarettes daily. Which teaching point is most important for the nurse to emphasize?', '[{"id": "a", "text": "Smoking adds no extra risk after asbestos exposure"}, {"id": "b", "text": "Asbestos exposure is a risk only for liver cancer"}, {"id": "c", "text": "Radon testing matters more than quitting smoking"}, {"id": "d", "text": "Asbestos plus smoking creates a synergistic risk"}]'::jsonb, '["d"]', 'Asbestos exposure combined with smoking produces a synergistic lung cancer risk, so smoking cessation is essential. Smoking is the #1 cause of lung cancer, so it clearly adds risk.'),
  ('large_organ', 12, 'A client who has never smoked is diagnosed with lung cancer and asks what in the home could have contributed. Which exposure should the nurse identify?', '[{"id": "a", "text": "Aflatoxin on stored peanuts"}, {"id": "b", "text": "A relative with hepatitis C"}, {"id": "c", "text": "Use of home dialysis"}, {"id": "d", "text": "Residential radon gas"}]'::jsonb, '["d"]', 'Radon gas from residential exposure is a lung cancer risk factor. Aflatoxin and hepatitis C are liver cancer risks, and dialysis is a renal cell carcinoma risk.'),
  ('large_organ', 13, 'A 64-year-old client who smokes is seen for a third episode of pneumonia this year, each in the right lower lobe. Which conclusion by the nurse is most appropriate?', '[{"id": "a", "text": "The pattern warrants evaluation for lung cancer"}, {"id": "b", "text": "The pattern is expected in all adult smokers"}, {"id": "c", "text": "The pattern suggests renal cell carcinoma"}, {"id": "d", "text": "The pattern indicates hepatocellular carcinoma"}]'::jsonb, '["a"]', 'Recurrent pneumonia in the same lobe is a classic lung cancer symptom, especially in a smoker. It is not a presenting feature of renal or liver cancer.'),
  ('large_organ', 14, 'A 59-year-old client with a long smoking history reports a chronic cough, coughing up blood, and unexplained weight loss. Which condition should the nurse suspect?', '[{"id": "a", "text": "Renal cell carcinoma"}, {"id": "b", "text": "Lung cancer"}, {"id": "c", "text": "Hepatocellular carcinoma"}, {"id": "d", "text": "Pancreatic cancer"}]'::jsonb, '["b"]', 'Chronic cough plus hemoptysis plus weight loss points to lung cancer, especially in a smoker. Hematuria, flank pain, and a palpable mass point to renal cell carcinoma.'),
  ('large_organ', 15, 'A client with a known lung tumor develops new hoarseness. The nurse recognizes this finding most likely results from which cause?', '[{"id": "a", "text": "Bile salt deposits in the vocal cords"}, {"id": "b", "text": "Liver capsule distension by tumor"}, {"id": "c", "text": "Renin overproduction by the tumor"}, {"id": "d", "text": "Recurrent laryngeal nerve compression"}]'::jsonb, '["d"]', 'Hoarseness in lung cancer results from recurrent laryngeal nerve compression. Renin overproduction causes hypertension in renal cell carcinoma.'),
  ('large_organ', 16, 'The nurse reviews four clients for low-dose CT lung cancer screening eligibility. Which client meets the criteria?', '[{"id": "a", "text": "A 45-year-old with 25 pack-years who smokes now"}, {"id": "b", "text": "A 70-year-old with 10 pack-years who smokes now"}, {"id": "c", "text": "A 66-year-old with 40 pack-years who quit 20 years ago"}, {"id": "d", "text": "A 58-year-old with 30 pack-years who quit 5 years ago"}]'::jsonb, '["d"]', 'Low-dose CT screening is for adults aged 50–80 with at least a 20 pack-year history who currently smoke or quit within 15 years. The 66-year-old quit more than 15 years ago and does not qualify.'),
  ('large_organ', 17, 'A 62-year-old client with a 40 pack-year history who still smokes has a normal low-dose CT scan. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will repeat this CT scan once a year.\""}, {"id": "b", "text": "\"I qualify because of my smoking history.\""}, {"id": "c", "text": "\"Quitting smoking is still important for me.\""}, {"id": "d", "text": "\"It was normal, so I won''t need another scan.\""}]'::jsonb, '["d"]', 'Low-dose CT screening is done annually for eligible smokers, so a normal scan does not end screening. The client qualifies based on age 50–80 and at least 20 pack-years.'),
  ('large_organ', 18, 'A client''s chest CT shows a suspicious lung lesion. Which test does the nurse anticipate to provide gold standard confirmation of lung cancer?', '[{"id": "a", "text": "Sputum cytology testing"}, {"id": "b", "text": "Bronchoscopy with biopsy"}, {"id": "c", "text": "Chest x-ray imaging"}, {"id": "d", "text": "Repeat low-dose chest CT"}]'::jsonb, '["b"]', 'Bronchoscopy with biopsy provides tissue diagnosis and is the gold standard confirmation. Sputum cytology is non-invasive but less sensitive.'),
  ('large_organ', 19, 'A client newly diagnosed with lung cancer is scheduled for a PET/CT scan and asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It replaces the need for a tissue biopsy sample.\""}, {"id": "b", "text": "\"It is the yearly screening test for all smokers.\""}, {"id": "c", "text": "\"It measures the blood level of a tumor marker.\""}, {"id": "d", "text": "\"It checks whether cancer has spread to distant sites.\""}]'::jsonb, '["d"]', 'PET/CT is used to detect distant metastasis and for staging. Annual screening for high-risk smokers uses low-dose CT, and tissue diagnosis requires bronchoscopy with biopsy.'),
  ('large_organ', 20, 'A client with suspected lung cancer asks why sputum cytology alone cannot rule out cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is invasive and carries a high risk.\""}, {"id": "b", "text": "\"It is the gold standard for diagnosis.\""}, {"id": "c", "text": "\"It is non-invasive but less sensitive.\""}, {"id": "d", "text": "\"It is mainly used to detect metastasis.\""}]'::jsonb, '["c"]', 'Sputum cytology is non-invasive but less sensitive, so it cannot reliably rule out cancer. Bronchoscopy with biopsy is the gold standard, and PET/CT detects metastasis.'),
  ('large_organ', 21, 'A client with lung cancer is starting pembrolizumab. The nurse identifies this medication as which type of agent?', '[{"id": "a", "text": "VEGF receptor inhibitor"}, {"id": "b", "text": "Pancreatic enzyme replacement"}, {"id": "c", "text": "PD-1 inhibitor"}, {"id": "d", "text": "Hepatitis C antiviral"}]'::jsonb, '["c"]', 'Pembrolizumab is a PD-1 inhibitor used in lung cancer. VEGF inhibitors such as sunitinib and sorafenib are used for renal cell carcinoma and HCC.'),
  ('large_organ', 22, 'A client is diagnosed with surgically resectable non-small cell lung cancer (NSCLC). Which procedure does the nurse anticipate?', '[{"id": "a", "text": "Lobectomy"}, {"id": "b", "text": "Nephrectomy"}, {"id": "c", "text": "Whipple procedure"}, {"id": "d", "text": "Liver resection"}]'::jsonb, '["a"]', 'Surgery for NSCLC is lobectomy. Nephrectomy is for renal cell carcinoma, and the Whipple procedure is for pancreatic cancer.'),
  ('large_organ', 23, 'The nurse receives report on a client who had a lobectomy 6 hours ago. Which finding requires the nurse''s first action?', '[{"id": "a", "text": "Slight decrease in hemoglobin from baseline"}, {"id": "b", "text": "Incisional pain rated 5 on a 0–10 scale"}, {"id": "c", "text": "Request for smoking-cessation resources"}, {"id": "d", "text": "Labored breathing with increasing distress"}]'::jsonb, '["d"]', 'Post-surgical respiratory distress is priority 1 after any thoracic or abdominal surgery — airway first. Bleeding, monitored through drain output, vital signs, and Hgb/Hct trends, is priority 2.'),
  ('large_organ', 24, 'A 62-year-old male client reports blood in his urine and a dull ache in his side, and the nurse palpates a flank mass. Which condition should the nurse suspect?', '[{"id": "a", "text": "Hepatocellular carcinoma"}, {"id": "b", "text": "Renal cell carcinoma"}, {"id": "c", "text": "Pancreatic cancer"}, {"id": "d", "text": "Lung cancer"}]'::jsonb, '["b"]', 'Hematuria, flank pain, and a palpable mass form the classic triad of renal cell carcinoma. Jaundice, RUQ pain, and ascites suggest HCC or pancreatic cancer instead.'),
  ('large_organ', 25, 'A 58-year-old client who smokes mentions passing pink urine twice this week without any pain. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"Without pain, blood in the urine is not a concern.\""}, {"id": "b", "text": "\"Painless blood in the urine needs prompt evaluation.\""}, {"id": "c", "text": "\"This is expected and should resolve on its own.\""}, {"id": "d", "text": "\"Only blood with flank pain needs a workup.\""}]'::jsonb, '["b"]', 'Hematuria is painless in early RCC and should not be dismissed. Waiting for flank pain could miss early disease.'),
  ('large_organ', 26, 'A client with renal cell carcinoma has a complete blood count drawn. Which finding should the nurse anticipate as a result of the tumor?', '[{"id": "a", "text": "Anemia from reduced erythropoietin output"}, {"id": "b", "text": "Polycythemia from increased erythropoietin"}, {"id": "c", "text": "Polycythemia from bile duct obstruction"}, {"id": "d", "text": "Anemia from stretching of the liver capsule"}]'::jsonb, '["b"]', 'RCC can cause polycythemia because the tumor overproduces EPO (erythropoietin). Anemia from decreased EPO reverses the direction of the change.'),
  ('large_organ', 27, 'A client with renal cell carcinoma has newly elevated blood pressure. The nurse understands this is most likely related to which mechanism?', '[{"id": "a", "text": "Erythropoietin underproduction"}, {"id": "b", "text": "Bile duct obstruction"}, {"id": "c", "text": "Renin overproduction"}, {"id": "d", "text": "Liver capsule distension"}]'::jsonb, '["c"]', 'Hypertension in RCC results from renin overproduction. EPO is overproduced, not underproduced, in RCC and causes polycythemia.'),
  ('large_organ', 28, 'A client with Von Hippel-Lindau (VHL) syndrome asks which cancer the condition increases risk for. Which response by the nurse is accurate?', '[{"id": "a", "text": "Hepatocellular carcinoma"}, {"id": "b", "text": "Renal cell carcinoma"}, {"id": "c", "text": "Small cell lung cancer"}, {"id": "d", "text": "Pancreatic cancer"}]'::jsonb, '["b"]', 'VHL syndrome is a genetic risk factor for renal cell carcinoma. BRCA1/2 and PALB2 mutations are the genetic risks listed for pancreatic cancer.'),
  ('large_organ', 29, 'A 60-year-old male client is concerned about kidney cancer. Which risk factor for renal cell carcinoma should the nurse identify as the #1 modifiable risk?', '[{"id": "a", "text": "Male sex"}, {"id": "b", "text": "Cigarette smoking"}, {"id": "c", "text": "Age of 60 years"}, {"id": "d", "text": "Von Hippel-Lindau syndrome"}]'::jsonb, '["b"]', 'Smoking is the #1 modifiable risk factor for RCC. Male sex, age 50–70, and VHL syndrome are risk factors that cannot be changed.'),
  ('large_organ', 30, 'The nurse reviews clients at a renal clinic. Which client has a recognized risk factor for renal cell carcinoma?', '[{"id": "a", "text": "A client with chronic hepatitis B infection"}, {"id": "b", "text": "A client with residential radon exposure"}, {"id": "c", "text": "A client exposed to moldy stored peanuts"}, {"id": "d", "text": "A client on long-term dialysis for CKD"}]'::jsonb, '["d"]', 'Chronic kidney disease and dialysis are risk factors for RCC. Hepatitis B and aflatoxin are HCC risks, and radon is a lung cancer risk.'),
  ('large_organ', 31, 'A client with a renal mass seen on CT asks whether a biopsy will be required. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A biopsy usually isn''t needed if imaging is classic.\""}, {"id": "b", "text": "\"A biopsy is always required before any treatment.\""}, {"id": "c", "text": "\"A sputum sample will be needed instead.\""}, {"id": "d", "text": "\"A bronchoscopy will confirm the diagnosis.\""}]'::jsonb, '["a"]', 'Abdominal CT/MRI is the best imaging for a renal mass, and no biopsy is usually needed if imaging is classic. Bronchoscopy with biopsy is used for lung cancer.'),
  ('large_organ', 32, 'A client with renal cell carcinoma is scheduled for a nephrectomy. Which laboratory values should the nurse ensure are obtained as a baseline?', '[{"id": "a", "text": "BUN and creatinine"}, {"id": "b", "text": "AFP and CA 19-9"}, {"id": "c", "text": "Serum AFP level"}, {"id": "d", "text": "Serum CA 19-9 level"}]'::jsonb, '["a"]', 'BUN and creatinine are renal function tests obtained as a baseline before nephrectomy. AFP is the HCC marker and CA 19-9 is the pancreatic marker.'),
  ('large_organ', 33, 'A client has a small, localized renal tumor. Which surgical approach does the nurse anticipate?', '[{"id": "a", "text": "Whipple procedure"}, {"id": "b", "text": "Lobectomy"}, {"id": "c", "text": "Liver resection"}, {"id": "d", "text": "Partial nephrectomy"}]'::jsonb, '["d"]', 'Nephrectomy is definitive for localized RCC, and partial nephrectomy is used when the tumor is small. Lobectomy is surgery for non-small cell lung cancer.'),
  ('large_organ', 34, 'A client with metastatic renal cell carcinoma is prescribed sunitinib. Which client statement indicates understanding of the medication?', '[{"id": "a", "text": "\"It is a PD-1 inhibitor that boosts my immunity.\""}, {"id": "b", "text": "\"It is a tumor marker used to track my cancer.\""}, {"id": "c", "text": "\"It is a targeted drug that blocks VEGF receptors.\""}, {"id": "d", "text": "\"It is a pancreatic enzyme that aids digestion.\""}]'::jsonb, '["c"]', 'Sunitinib is a VEGF receptor inhibitor used as targeted therapy for metastatic RCC. Nivolumab, not sunitinib, is the anti-PD-1 immunotherapy option for advanced disease.'),
  ('large_organ', 35, 'A client is 4 hours post-nephrectomy with a patent airway and unlabored breathing. Which assessment is the nurse''s next priority?', '[{"id": "a", "text": "Blood glucose and pancreatic enzyme replacement"}, {"id": "b", "text": "Drain output, vital signs, and Hgb/Hct trends"}, {"id": "c", "text": "Sputum cytology and chest x-ray findings"}, {"id": "d", "text": "Serum AFP level and abdominal ultrasound"}]'::jsonb, '["b"]', 'After airway (priority 1), post-surgical bleeding is priority 2 and is monitored through drain output, vital signs, and Hgb/Hct trends. Glucose and enzyme needs are post-Whipple concerns.'),
  ('large_organ', 36, 'A 70-year-old client presents with painless jaundice, clay-colored stools, and newly diagnosed diabetes mellitus. Which condition should the nurse suspect?', '[{"id": "a", "text": "Pancreatic head cancer"}, {"id": "b", "text": "Renal cell carcinoma"}, {"id": "c", "text": "Non-small cell lung cancer"}, {"id": "d", "text": "Small cell lung cancer"}]'::jsonb, '["a"]', 'Painless jaundice, clay stools, and new-onset diabetes point to cancer of the pancreatic head. Renal cell carcinoma presents with hematuria, flank pain, and a palpable mass.'),
  ('large_organ', 37, 'A client with suspected pancreatic cancer describes their pain. Which description is most consistent with the expected presentation?', '[{"id": "a", "text": "\"I have a dull ache in my side and pink urine.\""}, {"id": "b", "text": "\"My chest hurts and I keep coughing up blood.\""}, {"id": "c", "text": "\"My belly pain goes straight through to my back.\""}, {"id": "d", "text": "\"My pain happens only when I swallow food.\""}]'::jsonb, '["c"]', 'Pancreatic cancer causes abdominal pain radiating to the back. A dull side ache with hematuria suggests RCC, and chest pain with hemoptysis suggests lung cancer.'),
  ('large_organ', 38, 'The nurse is assessing a client whose pancreatic tumor is obstructing the bile duct. Which elimination findings should the nurse expect?', '[{"id": "a", "text": "Pale urine and dark brown stools"}, {"id": "b", "text": "Dark urine and clay-colored stools"}, {"id": "c", "text": "Bloody urine and normal stools"}, {"id": "d", "text": "Clear urine and bright red stools"}]'::jsonb, '["b"]', 'Pancreatic cancer causes dark urine and clay-colored (acholic) stools. Bloody urine (hematuria) is a sign of renal cell carcinoma.'),
  ('large_organ', 39, 'A client with pancreatic cancer is scratching their arms and reports intense itching. Which process explains this symptom?', '[{"id": "a", "text": "Bile salts depositing in the skin"}, {"id": "b", "text": "Renin released by the tumor"}, {"id": "c", "text": "Erythropoietin released by the tumor"}, {"id": "d", "text": "Liver capsule being stretched"}]'::jsonb, '["a"]', 'Pruritus in pancreatic cancer results from bile salt deposits in the skin. Renin overproduction causes hypertension in RCC.'),
  ('large_organ', 40, 'A client who tested positive for a PALB2 gene mutation asks which cancer this increases risk for. Which response by the nurse is accurate?', '[{"id": "a", "text": "Pancreatic cancer"}, {"id": "b", "text": "Renal cell carcinoma"}, {"id": "c", "text": "Hepatocellular carcinoma"}, {"id": "d", "text": "Lung cancer"}]'::jsonb, '["a"]', 'BRCA1/2 and PALB2 mutations are risk factors for pancreatic cancer. VHL syndrome is the genetic risk listed for renal cell carcinoma.'),
  ('large_organ', 41, 'The nurse teaches a client with pancreatic cancer about the CA 19-9 tumor marker. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"CA 19-9 can be elevated in pancreatic cancer.\""}, {"id": "b", "text": "\"My family should get yearly CA 19-9 tests to screen.\""}, {"id": "c", "text": "\"CA 19-9 helps track how my cancer is responding.\""}, {"id": "d", "text": "\"CA 19-9 levels will be checked during my treatment.\""}]'::jsonb, '["b"]', 'CA 19-9 is elevated in pancreatic cancer and is used for monitoring, not screening. The other statements correctly describe its monitoring role.'),
  ('large_organ', 42, 'A client with suspected pancreatic cancer is scheduled for imaging. Which study does the nurse anticipate as the gold standard to show the mass and vascular involvement?', '[{"id": "a", "text": "Low-dose CT of the chest"}, {"id": "b", "text": "Abdominal ultrasound scan"}, {"id": "c", "text": "CT abdomen with contrast"}, {"id": "d", "text": "Sputum cytology sample"}]'::jsonb, '["c"]', 'CT abdomen with contrast is the gold standard imaging for pancreatic cancer, showing the mass, vascular involvement, and stage. Low-dose chest CT is used for lung cancer screening.'),
  ('large_organ', 43, 'A client with unresectable pancreatic cancer has jaundice from biliary obstruction. The nurse anticipates which procedure to provide palliation?', '[{"id": "a", "text": "Curative Whipple procedure"}, {"id": "b", "text": "ERCP with biliary stenting"}, {"id": "c", "text": "Partial nephrectomy"}, {"id": "d", "text": "Liver transplantation"}]'::jsonb, '["b"]', 'ERCP is used for biliary stenting for palliation. The Whipple procedure has curative intent and is used only if the tumor is resectable.'),
  ('large_organ', 44, 'A client with resectable pancreatic cancer asks what a Whipple procedure removes. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The pancreatic tail, the spleen, and a section of the colon.\""}, {"id": "b", "text": "\"The whole pancreas, the stomach, and the right lobe of the liver.\""}, {"id": "c", "text": "\"The pancreatic head, duodenum, gallbladder, and part of the bile duct.\""}, {"id": "d", "text": "\"The pancreatic head and one kidney with its adrenal gland.\""}]'::jsonb, '["c"]', 'The Whipple procedure (pancreaticoduodenectomy) removes the head of the pancreas, duodenum, gallbladder, and part of the common bile duct. It is done with curative intent if the tumor is resectable.'),
  ('large_organ', 45, 'On postoperative day 3 after a Whipple procedure, a client develops a fever, severe abdominal pain, and increasing jaundice. Which complication should the nurse suspect?', '[{"id": "a", "text": "Expected postoperative pain"}, {"id": "b", "text": "Bile or anastomotic leak"}, {"id": "c", "text": "Pancreatic enzyme deficiency"}, {"id": "d", "text": "New-onset diabetes mellitus"}]'::jsonb, '["b"]', 'Fever, severe abdominal pain, and worsening jaundice after a Whipple procedure indicate a bile/anastomotic leak, the first listed priority assessment. These findings are not expected postoperative pain.'),
  ('large_organ', 46, 'A client who had a Whipple procedure has no prior history of diabetes. Which assessment should the nurse include in the plan of care?', '[{"id": "a", "text": "Annual low-dose chest CT"}, {"id": "b", "text": "Serum AFP every 6 months"}, {"id": "c", "text": "Regular blood glucose monitoring"}, {"id": "d", "text": "Daily urinalysis for hematuria"}]'::jsonb, '["c"]', 'After a Whipple procedure, pancreatic endocrine disruption can cause diabetes to develop, so blood glucose is monitored. AFP every 6 months relates to HCC surveillance in cirrhotic clients.'),
  ('large_organ', 47, 'A client who had a Whipple procedure is found to have malabsorption. Which therapy does the nurse anticipate?', '[{"id": "a", "text": "Pancreatic enzyme replacement"}, {"id": "b", "text": "Sunitinib targeted therapy"}, {"id": "c", "text": "Pembrolizumab immunotherapy"}, {"id": "d", "text": "Biliary stent placement by ERCP"}]'::jsonb, '["a"]', 'Loss of exocrine pancreatic function after a Whipple procedure causes malabsorption, which is treated with enzyme replacement. Sunitinib is a VEGF inhibitor for metastatic RCC.'),
  ('large_organ', 48, 'The nurse is supervising a UAP caring for a client after a Whipple procedure. Which action by the UAP requires correction?', '[{"id": "a", "text": "Emptying the drain without noting the amount"}, {"id": "b", "text": "Reporting the client''s fever to the nurse"}, {"id": "c", "text": "Recording drain color on the flow sheet"}, {"id": "d", "text": "Reporting new severe abdominal pain"}]'::jsonb, '["a"]', 'Drain output must be monitored for color, consistency, and volume, so emptying the drain without measuring requires correction. Reporting fever or severe pain is appropriate because they can signal a bile leak.'),
  ('large_organ', 49, 'The family of a client newly diagnosed with pancreatic cancer asks why the prognosis is so poor. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Most cases are found early through screening.\""}, {"id": "b", "text": "\"Most cases are diagnosed at an advanced stage.\""}, {"id": "c", "text": "\"Most cases are caused by hepatitis infection.\""}, {"id": "d", "text": "\"Most tumors cannot be seen on a CT scan.\""}]'::jsonb, '["b"]', 'Pancreatic cancer has a 5-year survival under 12% overall because most cases are diagnosed at an advanced stage. CA 19-9 is not used for screening, and CT with contrast is the gold standard imaging.'),
  ('large_organ', 50, 'A client with advanced pancreatic cancer is assessed for cachexia. Which finding should the nurse recognize as consistent with cachexia?', '[{"id": "a", "text": "Polycythemia"}, {"id": "b", "text": "Hemoptysis"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "Muscle wasting"}]'::jsonb, '["d"]', 'Cachexia is muscle wasting from advanced disease and is monitored during nutritional assessment after a Whipple procedure. Polycythemia and hematuria are findings of renal cell carcinoma.'),
  ('sclc', 1, 'A client with small cell lung cancer (SCLC) has a serum sodium of 122 mEq/L. Which action should the nurse take first?', '[{"id": "a", "text": "Encourage the client to drink extra free water"}, {"id": "b", "text": "Document the result and recheck it tomorrow"}, {"id": "c", "text": "Notify the provider of the sodium level immediately"}, {"id": "d", "text": "Increase the IV maintenance fluid rate"}]'::jsonb, '["c"]', 'A sodium below 125 mEq/L in a client with SCLC must be reported immediately because severe hyponatremia can cause confusion or seizures. Extra free water or fluid would worsen the dilutional hyponatremia of SIADH.'),
  ('sclc', 2, 'A client with SCLC becomes newly confused and lethargic, and morning laboratory results show a low serum sodium. The nurse suspects which paraneoplastic syndrome?', '[{"id": "a", "text": "Syndrome of inappropriate antidiuretic hormone"}, {"id": "b", "text": "Ectopic adrenocorticotropic hormone syndrome"}, {"id": "c", "text": "Lambert-Eaton myasthenic syndrome"}, {"id": "d", "text": "Myasthenia gravis"}]'::jsonb, '["a"]', 'Tumor-secreted ADH causes water retention and dilutional hyponatremia, producing confusion, headache, seizures, and lethargy. Ectopic ACTH (Cushing''s) syndrome is marked by hyperglycemia and hypokalemia rather than low sodium.'),
  ('sclc', 3, 'The spouse of a client with SCLC and SIADH asks why the client''s sodium level is low. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The tumor makes cortisol, so the kidneys lose sodium in the urine."}, {"id": "b", "text": "The tumor makes ADH, so the body retains water that dilutes sodium."}, {"id": "c", "text": "Antibodies from the tumor block sodium at the muscle junction."}, {"id": "d", "text": "Cancer that spreads to the liver stops the body from keeping sodium."}]'::jsonb, '["b"]', 'In SIADH the tumor secretes excess ADH, causing water retention and a dilutional hyponatremia. Excess cortisol from ectopic ACTH is linked to hyperglycemia and hypokalemia, not low sodium.'),
  ('sclc', 4, 'Which intervention should the nurse include in the plan of care for a client with SCLC who has developed SIADH?', '[{"id": "a", "text": "Offer free water every hour while awake"}, {"id": "b", "text": "Encourage fluids of at least 3 liters daily"}, {"id": "c", "text": "Encourage drinking whenever the client is thirsty"}, {"id": "d", "text": "Restrict the client''s fluid intake as prescribed"}]'::jsonb, '["d"]', 'SIADH is treated with fluid restriction while sodium is monitored. Liberal fluids or free water would add to water retention and further dilute sodium.'),
  ('sclc', 5, 'A UAP is caring for a client with SCLC who has SIADH and is on fluid restriction. Which action by the UAP requires correction by the nurse?', '[{"id": "a", "text": "Recording all oral intake on the intake record"}, {"id": "b", "text": "Raising the head of the bed for meals"}, {"id": "c", "text": "Filling the client''s bedside pitcher with free water"}, {"id": "d", "text": "Reporting the client''s new confusion to the nurse"}]'::jsonb, '["c"]', 'Free water must not be given to a client with SIADH because it worsens hyponatremia. Recording intake, elevating the head of the bed, and reporting confusion are appropriate actions.'),
  ('sclc', 6, 'A client with SCLC and SIADH has a seizure. The nurse recognizes that this finding most likely indicates which problem?', '[{"id": "a", "text": "Severe hyperglycemia"}, {"id": "b", "text": "Severe hypokalemia"}, {"id": "c", "text": "Severe neutropenia"}, {"id": "d", "text": "Severe hyponatremia"}]'::jsonb, '["d"]', 'In a client with SIADH, confusion or seizures may indicate severe hyponatremia. Hyperglycemia and hypokalemia are associated with ectopic Cushing''s syndrome.'),
  ('sclc', 7, 'A client with SCLC develops a rounded face, a fatty hump between the shoulders, and hypertension. Which laboratory values should the nurse monitor most closely?', '[{"id": "a", "text": "Serum sodium and fluid balance"}, {"id": "b", "text": "Liver enzymes and bilirubin"}, {"id": "c", "text": "White cell count and ANC"}, {"id": "d", "text": "Blood glucose and potassium"}]'::jsonb, '["d"]', 'Moon face, buffalo hump, and hypertension suggest ectopic ACTH (Cushing''s) syndrome, which requires monitoring of glucose and potassium. Sodium and fluid balance are the focus for SIADH.'),
  ('sclc', 8, 'Which assessment finding in a client with SCLC should the nurse recognize as suggesting ectopic ACTH production?', '[{"id": "a", "text": "Weakness that improves with exercise"}, {"id": "b", "text": "Jaundice and right upper quadrant pain"}, {"id": "c", "text": "Moon face and buffalo hump"}, {"id": "d", "text": "Confusion with a low serum sodium"}]'::jsonb, '["c"]', 'Ectopic ACTH causes Cushing''s syndrome with moon face, buffalo hump, and central obesity. Weakness that improves with exercise points to Lambert-Eaton syndrome instead.'),
  ('sclc', 9, 'The nurse reviews laboratory results for a client with SCLC and ectopic Cushing''s syndrome. Which pair of findings does the nurse expect?', '[{"id": "a", "text": "Elevated glucose and low potassium"}, {"id": "b", "text": "Low glucose and high potassium"}, {"id": "c", "text": "Elevated glucose and high potassium"}, {"id": "d", "text": "Low glucose and low potassium"}]'::jsonb, '["a"]', 'Excess cortisol from ectopic ACTH places the client at risk for hyperglycemia and hypokalemia. High potassium and low glucose reverse these expected changes.'),
  ('sclc', 10, 'A nursing student asks how SCLC causes Cushing''s syndrome. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Tumor spread to the adrenals destroys cortisol cells."}, {"id": "b", "text": "The tumor secretes ADH, which causes water retention."}, {"id": "c", "text": "Antibodies from the tumor attack calcium channels."}, {"id": "d", "text": "The tumor secretes ACTH, which causes excess cortisol."}]'::jsonb, '["d"]', 'In ectopic Cushing''s syndrome the tumor secretes excess ACTH, leading to adrenal cortisol overproduction. Tumor-secreted ADH causes SIADH, a different paraneoplastic syndrome.'),
  ('sclc', 11, 'A nursing student asks what an ''ectopic hormone'' is in a client with SCLC. Which response by the nurse is correct?', '[{"id": "a", "text": "A hormone made in larger amounts by the normal gland"}, {"id": "b", "text": "A hormone that is given as part of chemotherapy"}, {"id": "c", "text": "A hormone made by the tumor rather than the normal gland"}, {"id": "d", "text": "A hormone released only after the tumor is removed"}]'::jsonb, '["c"]', 'SCLC produces ectopic hormones, meaning hormones made by the tumor itself rather than the normal gland, causing paraneoplastic syndromes. They are not produced by the normal gland or given as treatment.'),
  ('sclc', 12, 'A client with SCLC reports weakness in the hips and shoulders that gets better after repeated movement. The nurse recognizes this finding as consistent with which condition?', '[{"id": "a", "text": "Myasthenia gravis"}, {"id": "b", "text": "Lambert-Eaton syndrome"}, {"id": "c", "text": "Inappropriate ADH secretion"}, {"id": "d", "text": "Ectopic Cushing''s syndrome"}]'::jsonb, '["b"]', 'Lambert-Eaton syndrome causes proximal muscle weakness that improves with repeated movement. In myasthenia gravis, weakness worsens with repeated activity.'),
  ('sclc', 13, 'Which statement by a nursing student comparing Lambert-Eaton syndrome (LEMS) and myasthenia gravis (MG) indicates a need for further teaching?', '[{"id": "a", "text": "\"In LEMS, muscle weakness worsens with repeated activity.\""}, {"id": "b", "text": "\"In MG, muscle weakness worsens with repeated activity.\""}, {"id": "c", "text": "\"In LEMS, muscle weakness improves with repeated activity.\""}, {"id": "d", "text": "\"LEMS can occur as a paraneoplastic syndrome of SCLC.\""}]'::jsonb, '["a"]', 'LEMS weakness improves with activity, while MG weakness worsens with activity, so the statement that LEMS weakness worsens is incorrect. LEMS is listed as one of the SCLC paraneoplastic syndromes.'),
  ('sclc', 14, 'Which mechanism should the nurse identify as the cause of Lambert-Eaton syndrome in a client with SCLC?', '[{"id": "a", "text": "Tumor secretion of antidiuretic hormone"}, {"id": "b", "text": "Antibodies against voltage-gated calcium channels"}, {"id": "c", "text": "Tumor secretion of adrenocorticotropic hormone"}, {"id": "d", "text": "Spread of the tumor to the adrenal glands"}]'::jsonb, '["b"]', 'LEMS is an autoimmune neuromuscular disorder caused by antibodies against voltage-gated calcium channels at the neuromuscular junction. ADH secretion causes SIADH and ACTH secretion causes Cushing''s syndrome.'),
  ('sclc', 15, 'In addition to proximal muscle weakness, which finding should the nurse expect in a client with SCLC who has Lambert-Eaton syndrome?', '[{"id": "a", "text": "Buffalo hump"}, {"id": "b", "text": "Low serum sodium"}, {"id": "c", "text": "Jaundice"}, {"id": "d", "text": "Dry mouth"}]'::jsonb, '["d"]', 'Lambert-Eaton syndrome includes dry mouth and autonomic dysfunction along with proximal weakness. Buffalo hump reflects ectopic Cushing''s and low sodium reflects SIADH.'),
  ('sclc', 16, 'A client with SCLC and Lambert-Eaton syndrome asks whether the muscle weakness will ever get better. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The weakness is permanent once it has started.\""}, {"id": "b", "text": "\"Restricting your fluids will reverse the weakness.\""}, {"id": "c", "text": "\"Treating the lung cancer may improve the weakness.\""}, {"id": "d", "text": "\"Only radiation to the brain can reverse the weakness.\""}]'::jsonb, '["c"]', 'Because LEMS is a paraneoplastic syndrome, treating the SCLC may improve it. Fluid restriction is the treatment for SIADH, not LEMS.'),
  ('sclc', 17, 'The nurse is teaching a community group about small cell lung cancer. Which risk factor should the nurse identify as the leading cause?', '[{"id": "a", "text": "Radon gas exposure"}, {"id": "b", "text": "Asbestos exposure"}, {"id": "c", "text": "Family history of lung cancer"}, {"id": "d", "text": "Cigarette smoking"}]'::jsonb, '["d"]', 'Smoking is the number one cause of SCLC, linked to 95% of cases. Radon, asbestos, and family history are additional risk factors but are not the leading cause.'),
  ('sclc', 18, 'The nurse is screening nonsmoking clients for lung cancer risk. Which client history places the client at increased risk for SCLC?', '[{"id": "a", "text": "Many years of work with asbestos"}, {"id": "b", "text": "Frequent sunburns during childhood"}, {"id": "c", "text": "Two cups of coffee each day"}, {"id": "d", "text": "A history of seasonal allergies"}]'::jsonb, '["a"]', 'Asbestos exposure is a listed risk factor for SCLC, along with radon, family history, and secondhand smoke. Childhood sunburns, coffee intake, and allergies are not among the SCLC risk factors.'),
  ('sclc', 19, 'A nonsmoking client is learning about lung cancer risk. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Having my home tested for radon gas is a good idea.\""}, {"id": "b", "text": "\"My father''s lung cancer may increase my own risk.\""}, {"id": "c", "text": "\"Smoking is the number one cause of this lung cancer.\""}, {"id": "d", "text": "\"Since I never smoked, secondhand smoke cannot raise my risk.\""}]'::jsonb, '["d"]', 'Secondhand smoke is a risk factor for SCLC even in people who have never smoked. Radon exposure and a family history of lung cancer are also listed risk factors, and smoking is the number one cause.'),
  ('sclc', 20, 'Which finding in a client with a long smoking history should the nurse recognize as a possible sign of SCLC?', '[{"id": "a", "text": "Weight gain with an increased appetite"}, {"id": "b", "text": "A persistent cough that is new or has changed"}, {"id": "c", "text": "Weakness that worsens with repeated activity"}, {"id": "d", "text": "Improved tolerance for physical exercise"}]'::jsonb, '["b"]', 'A persistent cough that is new or changed in a smoker is a clinical symptom of SCLC. Weight loss, not weight gain, is the expected systemic effect, and weakness that worsens with activity describes myasthenia gravis.'),
  ('sclc', 21, 'A client with SCLC reports coughing up bright red sputum. The nurse should document this finding as which symptom?', '[{"id": "a", "text": "Stridor"}, {"id": "b", "text": "Hemoptysis"}, {"id": "c", "text": "Dyspnea"}, {"id": "d", "text": "Wheezing"}]'::jsonb, '["b"]', 'Coughing up blood is hemoptysis, a clinical symptom of SCLC. Stridor and wheezing result from airway obstruction, and dyspnea is shortness of breath.'),
  ('sclc', 22, 'A client with SCLC develops stridor. The nurse recognizes that this finding is most likely caused by which problem?', '[{"id": "a", "text": "Obstruction of the airway"}, {"id": "b", "text": "Excess secretion of ADH"}, {"id": "c", "text": "Excess secretion of ACTH"}, {"id": "d", "text": "Spread of tumor to the liver"}]'::jsonb, '["a"]', 'Wheezing or stridor in SCLC results from airway obstruction. Excess ADH and ACTH cause paraneoplastic syndromes, and liver spread causes jaundice and RUQ pain.'),
  ('sclc', 23, 'A client with SCLC develops a new headache and family members report personality changes. The nurse suspects metastasis to which site?', '[{"id": "a", "text": "Brain"}, {"id": "b", "text": "Liver"}, {"id": "c", "text": "Bones"}, {"id": "d", "text": "Adrenal glands"}]'::jsonb, '["a"]', 'Brain metastasis from SCLC causes neurological symptoms, personality changes, and headache. Liver metastasis causes jaundice and RUQ pain, and bone metastasis causes bone pain and fractures.'),
  ('sclc', 24, 'A client with SCLC develops jaundice and right upper quadrant pain. Which laboratory result would support the suspected site of metastasis?', '[{"id": "a", "text": "Low serum sodium level"}, {"id": "b", "text": "Low serum potassium level"}, {"id": "c", "text": "Elevated liver function tests"}, {"id": "d", "text": "Elevated blood glucose level"}]'::jsonb, '["c"]', 'Liver metastasis presents with jaundice, RUQ pain, and elevated LFTs. Low sodium suggests SIADH, and high glucose with low potassium suggests ectopic Cushing''s syndrome.'),
  ('sclc', 25, 'A client with SCLC has metastasis to the bones. Which risk should the nurse prioritize when planning care?', '[{"id": "a", "text": "Personality changes"}, {"id": "b", "text": "Pathologic fractures"}, {"id": "c", "text": "Jaundice"}, {"id": "d", "text": "Hyperglycemia"}]'::jsonb, '["b"]', 'Bone metastasis causes bone pain and pathologic fractures. Personality changes reflect brain metastasis and jaundice reflects liver metastasis.'),
  ('sclc', 26, 'A client newly diagnosed with SCLC asks why so many tests are being done on other organs. The nurse''s response is based on which characteristic of SCLC?', '[{"id": "a", "text": "It spreads early, so most clients have metastases at diagnosis."}, {"id": "b", "text": "It grows slowly, so it rarely spreads beyond the lung."}, {"id": "c", "text": "It spreads only to lymph nodes next to the tumor."}, {"id": "d", "text": "It spreads to other organs only after surgery."}]'::jsonb, '["a"]', 'SCLC is highly aggressive with rapid growth and early metastasis, and most clients already have metastatic disease at diagnosis. It does not grow slowly or stay limited to nearby nodes.'),
  ('sclc', 27, 'Which description should the nurse recognize as limited-stage SCLC?', '[{"id": "a", "text": "Cancer confined to one lung and nearby lymph nodes"}, {"id": "b", "text": "Cancer that has spread to the opposite lung"}, {"id": "c", "text": "Cancer that has spread to the brain and liver"}, {"id": "d", "text": "Cancer that has spread to the bones and adrenals"}]'::jsonb, '["a"]', 'Limited-stage SCLC is confined to one lung plus nearby regional lymph nodes and can fit in a single radiation field. Spread to the opposite lung or distant organs defines extensive stage.'),
  ('sclc', 28, 'The nurse is reviewing SCLC staging with a new graduate. Which statement about extensive-stage SCLC is accurate?', '[{"id": "a", "text": "It can be covered by a single radiation field."}, {"id": "b", "text": "It has a better prognosis than limited stage."}, {"id": "c", "text": "It is confined to one lung and nearby nodes."}, {"id": "d", "text": "It is the most common stage found at diagnosis."}]'::jsonb, '["d"]', 'About 70% of clients have extensive-stage SCLC at diagnosis. A single radiation field and confinement to one lung describe limited stage, which has the better prognosis.'),
  ('sclc', 29, 'A client with limited-stage SCLC asks how the outlook compares with extensive-stage disease. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Limited stage has a better prognosis than extensive stage.\""}, {"id": "b", "text": "\"Extensive stage has a better prognosis than limited stage.\""}, {"id": "c", "text": "\"Both stages have exactly the same expected prognosis.\""}, {"id": "d", "text": "\"Limited stage is the most common stage at diagnosis.\""}]'::jsonb, '["a"]', 'Limited-stage SCLC has a better prognosis than extensive stage, which carries a poorer prognosis. Extensive stage, not limited stage, is the most common at diagnosis.'),
  ('sclc', 30, 'The nurse is preparing a client with limited-stage SCLC for treatment. Which treatment plan does the nurse anticipate?', '[{"id": "a", "text": "Surgical lobectomy as the main treatment"}, {"id": "b", "text": "Immunotherapy alone without chemotherapy"}, {"id": "c", "text": "Cisplatin and etoposide with concurrent chest radiation"}, {"id": "d", "text": "Chest radiation alone without chemotherapy"}]'::jsonb, '["c"]', 'Limited-stage SCLC is treated with cisplatin plus etoposide, concurrent chest radiation, and PCI. Surgery is rarely used because most clients present with metastatic disease.'),
  ('sclc', 31, 'A client with extensive-stage SCLC will receive atezolizumab along with chemotherapy and asks why it was added. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is added to chemotherapy to improve overall survival.\""}, {"id": "b", "text": "\"It replaces chemotherapy for extensive-stage disease.\""}, {"id": "c", "text": "\"It is given to prevent the cancer from reaching the brain.\""}, {"id": "d", "text": "\"It is given to correct the low sodium caused by the tumor.\""}]'::jsonb, '["a"]', 'Atezolizumab or durvalumab is added to chemotherapy for extensive-stage SCLC and improves overall survival. Prevention of brain metastases is the purpose of PCI, not immunotherapy.'),
  ('sclc', 32, 'A client with SCLC also has chronic renal disease. When reviewing the chemotherapy plan, the nurse anticipates which change to the standard regimen?', '[{"id": "a", "text": "Cisplatin given instead of carboplatin"}, {"id": "b", "text": "Carboplatin given instead of cisplatin"}, {"id": "c", "text": "Atezolizumab given instead of etoposide"}, {"id": "d", "text": "Etoposide given without any platinum drug"}]'::jsonb, '["b"]', 'Carboplatin is used instead of cisplatin in clients with renal disease because it is less nephrotoxic. Substituting cisplatin would expose the kidneys to the more nephrotoxic drug.'),
  ('sclc', 33, 'A client with newly diagnosed SCLC and normal renal function is starting first-line chemotherapy. Which combination does the nurse anticipate?', '[{"id": "a", "text": "Etoposide and ondansetron"}, {"id": "b", "text": "Atezolizumab and durvalumab"}, {"id": "c", "text": "Cisplatin and etoposide"}, {"id": "d", "text": "Carboplatin and ondansetron"}]'::jsonb, '["c"]', 'Cisplatin plus etoposide is the most common first-line SCLC combination; carboplatin is substituted only in renal disease. Ondansetron is an antiemetic, and atezolizumab and durvalumab are immunotherapies added in extensive stage.'),
  ('sclc', 34, 'A client with SCLC who responded to initial chemotherapy is scheduled for prophylactic cranial irradiation (PCI) and says, "But I don''t have a brain tumor." Which response by the nurse is best?', '[{"id": "a", "text": "\"PCI is given to shrink a tumor already found in the brain.\""}, {"id": "b", "text": "\"PCI is given to prevent cancer from spreading to the brain.\""}, {"id": "c", "text": "\"PCI is given to correct the low sodium from the tumor.\""}, {"id": "d", "text": "\"PCI is given to replace any further chemotherapy.\""}]'::jsonb, '["b"]', 'PCI is given to prevent brain metastases because SCLC spreads to the brain very early. It is preventive rather than treatment for a known brain tumor.'),
  ('sclc', 35, 'The nurse is teaching a client with SCLC about prophylactic cranial irradiation. Which side effects should the nurse include?', '[{"id": "a", "text": "Moon face and central weight gain"}, {"id": "b", "text": "Memory impairment and cognitive changes"}, {"id": "c", "text": "Dry mouth and proximal weakness"}, {"id": "d", "text": "Yellowing of the skin and eyes"}]'::jsonb, '["b"]', 'Side effects of PCI include fatigue, memory impairment, and cognitive changes. Moon face reflects ectopic Cushing''s, and dry mouth with proximal weakness reflects Lambert-Eaton syndrome.'),
  ('sclc', 36, 'The nurse is reviewing the plans of care for four clients with SCLC. Which client is an appropriate candidate for prophylactic cranial irradiation?', '[{"id": "a", "text": "A client who has not yet been started on chemotherapy"}, {"id": "b", "text": "A client whose disease progressed during chemotherapy"}, {"id": "c", "text": "A client who has declined all forms of chemotherapy"}, {"id": "d", "text": "A client whose tumor responded to initial chemotherapy"}]'::jsonb, '["d"]', 'PCI is given to clients who respond to initial chemotherapy. Clients who have not started, have declined, or have not responded to chemotherapy do not meet this criterion.'),
  ('sclc', 37, 'A client with SCLC asks what prophylactic cranial irradiation involves. Which description by the nurse is accurate?', '[{"id": "a", "text": "High-dose radiation aimed at a single brain lesion"}, {"id": "b", "text": "Surgical removal of tumor that has spread to the brain"}, {"id": "c", "text": "Low-dose radiation delivered to the entire brain"}, {"id": "d", "text": "Chemotherapy delivered directly into the spinal fluid"}]'::jsonb, '["c"]', 'PCI is low-dose radiation to the entire brain to prevent metastases. It is not targeted at an existing lesion and is not a surgical procedure.'),
  ('sclc', 38, 'A client with SCLC asks why surgery is not being offered as treatment. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Surgery is avoided only because of a smoking history.\""}, {"id": "b", "text": "\"Surgery is reserved for clients with extensive-stage disease.\""}, {"id": "c", "text": "\"Most people already have widespread disease when diagnosed.\""}, {"id": "d", "text": "\"Surgery would cause the tumor to release more ADH.\""}]'::jsonb, '["c"]', 'Surgery is rarely used for SCLC because most clients present with extensive metastatic disease. The rare exception is a very early limited-stage solitary nodule, not extensive disease.'),
  ('sclc', 39, 'A client with a suspicious central lung mass on chest X-ray is suspected of having SCLC. Which test does the nurse anticipate will confirm the diagnosis?', '[{"id": "a", "text": "Repeat chest X-ray"}, {"id": "b", "text": "Sputum cytology"}, {"id": "c", "text": "Bronchoscopy with biopsy"}, {"id": "d", "text": "Serum sodium level"}]'::jsonb, '["c"]', 'Bronchoscopy with biopsy is the gold standard tissue diagnosis that confirms SCLC histology. Chest X-ray is an initial test, and sputum cytology has lower sensitivity.'),
  ('sclc', 40, 'A client with suspected SCLC asks why a bronchoscopy is needed when the sputum test was negative. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Sputum testing is the gold standard for this diagnosis.\""}, {"id": "b", "text": "\"Sputum testing is only used to stage the brain.\""}, {"id": "c", "text": "\"Sputum testing is used to measure your sodium level.\""}, {"id": "d", "text": "\"Sputum testing is noninvasive but has lower sensitivity.\""}]'::jsonb, '["d"]', 'Sputum cytology is noninvasive but has lower sensitivity, so a negative result does not rule out SCLC. Bronchoscopy with biopsy, not sputum cytology, is the gold standard.'),
  ('sclc', 41, 'A client has a confirmed diagnosis of SCLC. Which tests does the nurse anticipate to evaluate the client for brain and distant metastases?', '[{"id": "a", "text": "Sputum cytology and chest X-ray"}, {"id": "b", "text": "Bronchoscopy and biopsy"}, {"id": "c", "text": "MRI of the brain and PET scan"}, {"id": "d", "text": "Serum sodium and glucose levels"}]'::jsonb, '["c"]', 'MRI of the brain and PET scan are used for staging to evaluate for brain and distant metastases. Serum sodium and glucose monitor for paraneoplastic syndromes rather than metastases.'),
  ('sclc', 42, 'Which set of serum laboratory tests should the nurse expect to be ordered to monitor a client with SCLC for paraneoplastic syndromes?', '[{"id": "a", "text": "Calcium, magnesium, and phosphorus"}, {"id": "b", "text": "Sodium, cortisol, and glucose"}, {"id": "c", "text": "Albumin, ammonia, and bilirubin"}, {"id": "d", "text": "Amylase, lipase, and triglycerides"}]'::jsonb, '["b"]', 'Serum sodium, cortisol, and glucose are monitored to detect SIADH and ectopic Cushing''s syndrome. The other panels are not used for this purpose in SCLC.'),
  ('sclc', 43, 'A client with SCLC is short of breath. In which position should the nurse place the client?', '[{"id": "a", "text": "Supine with the legs elevated"}, {"id": "b", "text": "Trendelenburg with the head down"}, {"id": "c", "text": "Flat on the side with one pillow"}, {"id": "d", "text": "High-Fowler''s at 60 to 90 degrees"}]'::jsonb, '["d"]', 'High-Fowler''s position (60-90 degrees) is the recommended position to maximize lung expansion in a client with SCLC. Supine, head-down, and flat positions are not the recommended positions.'),
  ('sclc', 44, 'The nurse is teaching a client with SCLC how to manage episodes of dyspnea at home. Which instruction should the nurse include?', '[{"id": "a", "text": "Use pursed-lip breathing when short of breath"}, {"id": "b", "text": "Lie flat in bed when short of breath"}, {"id": "c", "text": "Hold your breath when short of breath"}, {"id": "d", "text": "Drink extra water when short of breath"}]'::jsonb, '["a"]', 'Nursing priorities for breathing in SCLC include teaching pursed-lip breathing and positioning upright. Lying flat or holding the breath does not reflect the upright High-Fowler''s positioning recommended to maximize lung expansion.'),
  ('sclc', 45, 'A client with SCLC is scheduled to receive cisplatin and etoposide. When should the nurse administer the prescribed ondansetron?', '[{"id": "a", "text": "Only after the client begins to vomit"}, {"id": "b", "text": "Before the chemotherapy infusion begins"}, {"id": "c", "text": "At the end of the chemotherapy infusion"}, {"id": "d", "text": "On the morning after the chemotherapy"}]'::jsonb, '["b"]', 'The antiemetic ondansetron is administered before chemotherapy. Waiting until vomiting starts or until after the infusion is not the stated practice.'),
  ('sclc', 46, 'A client receiving chemotherapy for SCLC asks when the risk of infection will be greatest. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"About 7 to 14 days after the chemotherapy\""}, {"id": "b", "text": "\"Within the first 24 hours after chemotherapy\""}, {"id": "c", "text": "\"About 4 to 6 weeks after the chemotherapy\""}, {"id": "d", "text": "\"Only while the chemotherapy is infusing\""}]'::jsonb, '["a"]', 'The neutropenia nadir occurs 7-14 days after chemotherapy, when the CBC must be monitored closely. Infection risk is not greatest during the infusion or in the first 24 hours.'),
  ('sclc', 47, 'The nurse reviews the absolute neutrophil counts (ANC) of four clients receiving chemotherapy for SCLC. Which client requires neutropenic precautions?', '[{"id": "a", "text": "The client with an ANC of 1,500/mm³"}, {"id": "b", "text": "The client with an ANC of 400/mm³"}, {"id": "c", "text": "The client with an ANC of 2,200/mm³"}, {"id": "d", "text": "The client with an ANC of 3,000/mm³"}]'::jsonb, '["b"]', 'Neutropenic precautions are implemented when the ANC is below 500. The other counts are above this threshold.'),
  ('sclc', 48, 'A client receiving chemotherapy for SCLC develops painful sores in the mouth. Which nursing intervention is appropriate?', '[{"id": "a", "text": "Withhold all oral hygiene"}, {"id": "b", "text": "Provide frequent oral care"}, {"id": "c", "text": "Withhold the ondansetron"}, {"id": "d", "text": "Restrict all oral fluids"}]'::jsonb, '["b"]', 'Oral care is a chemotherapy nursing priority for mucositis. Withholding oral hygiene or the antiemetic does not address mucositis.'),
  ('sclc', 49, 'The nurse is caring for four clients with SCLC. Which client finding should the nurse report to the provider first?', '[{"id": "a", "text": "A client after PCI who reports mild fatigue"}, {"id": "b", "text": "A client with LEMS whose hip strength improves with use"}, {"id": "c", "text": "A client whose nausea is controlled by ondansetron"}, {"id": "d", "text": "A client with SIADH who has a new seizure"}]'::jsonb, '["d"]', 'Seizures in SIADH may indicate severe hyponatremia and must be reported. Fatigue after PCI is an expected side effect, and improving strength with repeated use is typical of LEMS.'),
  ('sclc', 50, 'A client with SCLC and SIADH has been on fluid restriction for 3 days. Which finding indicates that the treatment is effective?', '[{"id": "a", "text": "Serum sodium rising and confusion resolving"}, {"id": "b", "text": "Serum sodium falling and a new headache"}, {"id": "c", "text": "Increasing lethargy and a low sodium level"}, {"id": "d", "text": "A new seizure and a falling sodium level"}]'::jsonb, '["a"]', 'SIADH causes dilutional hyponatremia with confusion, headache, seizures, and lethargy, and it is treated with fluid restriction while sodium is monitored. A rising sodium with resolving confusion shows improvement, while falling sodium and new symptoms show worsening.'),
  ('female', 1, 'A 24-year-old client at a women''s health clinic asks the nurse what most commonly causes cervical cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "Long-term use of oral contraceptive pills"}, {"id": "b", "text": "Infection with HPV, especially types 16 and 18"}, {"id": "c", "text": "Unopposed estrogen without progesterone"}, {"id": "d", "text": "Inherited BRCA1 or BRCA2 gene mutations"}]'::jsonb, '["b"]', 'HPV, especially types 16 and 18, is the number one cause of cervical cancer. Long-term oral contraceptive use is a cervical cancer risk factor but not the primary cause; unopposed estrogen is the top endometrial risk, and BRCA mutations carry the highest ovarian risk.'),
  ('female', 2, 'A 38-year-old client tells the clinic nurse she has noticed light bleeding after intercourse for the past month. The nurse recognizes this as a classic sign of which cancer?', '[{"id": "a", "text": "Cervical cancer"}, {"id": "b", "text": "Ovarian cancer"}, {"id": "c", "text": "Breast cancer"}, {"id": "d", "text": "Vulvar cancer"}]'::jsonb, '["a"]', 'Postcoital bleeding is the classic clue for cervical cancer. Ovarian cancer presents with vague symptoms such as bloating and early satiety, and vulvar cancer presents with persistent itching, pain, or a lump.'),
  ('female', 3, 'A 25-year-old client with no abnormal history asks how often she should have cervical cancer screening. Which recommendation should the nurse give?', '[{"id": "a", "text": "Pap smear plus HPV co-test every 5 years"}, {"id": "b", "text": "Pap smear alone every year"}, {"id": "c", "text": "Pap smear alone every 3 years"}, {"id": "d", "text": "No screening until age 30"}]'::jsonb, '["c"]', 'Clients aged 21 to 29 are screened with a Pap smear alone every 3 years. Co-testing every 5 years is the preferred option for ages 30 to 65, not for a 25-year-old.'),
  ('female', 4, 'A 40-year-old client with consistently normal results asks about her cervical cancer screening. Which screening plan does the nurse identify as the preferred approach for her age group?', '[{"id": "a", "text": "Pap smear alone every year"}, {"id": "b", "text": "HPV test alone every 10 years"}, {"id": "c", "text": "Pelvic exam with CA-125 every year"}, {"id": "d", "text": "Pap smear with HPV co-test every 5 years"}]'::jsonb, '["d"]', 'For ages 30 to 65, a Pap smear with HPV co-test every 5 years is preferred, with Pap alone every 3 years as the alternative. CA-125 is not a screening test; it is used to monitor ovarian cancer treatment response.'),
  ('female', 5, 'An 18-year-old sexually active client requests a Pap smear at her first gynecologic visit. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"You should have a Pap smear today and then every year.\""}, {"id": "b", "text": "\"Cervical cancer screening is not recommended before age 21.\""}, {"id": "c", "text": "\"You should have a Pap smear with an HPV co-test today.\""}, {"id": "d", "text": "\"Screening begins at your first sexual activity, so it is due now.\""}]'::jsonb, '["b"]', 'No cervical cancer screening is recommended for clients younger than 21. Pap smears begin at 21 (alone every 3 years), and HPV co-testing is used from age 30.'),
  ('female', 6, 'A 67-year-old client has had adequate prior normal Pap results and has no high-risk factors. She asks whether she still needs cervical cancer screening. Which response is accurate?', '[{"id": "a", "text": "\"You may stop cervical cancer screening.\""}, {"id": "b", "text": "\"You should switch to a yearly Pap smear.\""}, {"id": "c", "text": "\"You need co-testing every 5 years for life.\""}, {"id": "d", "text": "\"You need a Pap smear every 3 years for life.\""}]'::jsonb, '["a"]', 'After age 65, screening stops if the client has adequate prior normal results and no high-risk factors. Continuing co-testing or Pap smears lifelong is not recommended for this client.'),
  ('female', 7, 'A client is being discharged after a total hysterectomy in which the cervix was removed. She has no history of high-grade dysplasia. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will avoid sexual intercourse for 6 weeks.\""}, {"id": "b", "text": "\"I will report a foul-smelling vaginal discharge.\""}, {"id": "c", "text": "\"I will still need a Pap smear every 3 years.\""}, {"id": "d", "text": "\"I will not lift anything heavier than 10 pounds.\""}]'::jsonb, '["c"]', 'Screening stops after hysterectomy when the cervix was removed and there is no history of high-grade dysplasia, so continuing Pap smears reflects a misunderstanding. Avoiding intercourse for 6 weeks, no heavy lifting over 10 lbs, and reporting foul discharge are correct post-hysterectomy teaching.'),
  ('female', 8, 'A client with pre-invasive abnormal cervical cells is scheduled for a loop electrosurgical excision procedure (LEEP). Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It removes the uterus, cervix, and upper vagina.\""}, {"id": "b", "text": "\"It implants radioactive material into the cervix.\""}, {"id": "c", "text": "\"It removes both ovaries and the fallopian tubes.\""}, {"id": "d", "text": "\"It removes the abnormal cells from the cervix.\""}]'::jsonb, '["d"]', 'LEEP is an early/pre-invasive treatment that removes abnormal cells from the cervix. Removing the uterus, cervix, and upper vagina describes a radical hysterectomy, which is used for advanced invasive disease.'),
  ('female', 9, 'A client with invasive cervical cancer is scheduled for a radical hysterectomy. She asks which structures will be removed. Which response is accurate?', '[{"id": "a", "text": "Uterus, cervix, upper vagina, and pelvic lymph nodes"}, {"id": "b", "text": "A cone-shaped section of cervical tissue only"}, {"id": "c", "text": "The abnormal surface cells of the cervix only"}, {"id": "d", "text": "Both ovaries and both fallopian tubes only"}]'::jsonb, '["a"]', 'A radical hysterectomy removes the uterus, cervix, upper vagina, and pelvic lymph nodes. Removing a cone of cervical tissue describes conization, a pre-invasive treatment.'),
  ('female', 10, 'A client with invasive cervical cancer will receive concurrent chemoradiation. The nurse anticipates that the chemotherapy will be based on which agent?', '[{"id": "a", "text": "Tamoxifen"}, {"id": "b", "text": "Trastuzumab"}, {"id": "c", "text": "Cisplatin"}, {"id": "d", "text": "Anastrozole"}]'::jsonb, '["c"]', 'Concurrent chemoradiation for advanced/invasive cervical cancer is cisplatin-based. Tamoxifen, trastuzumab, and anastrozole are breast cancer therapies.'),
  ('female', 11, 'The nurse teaches a parent about the HPV vaccine for her 12-year-old daughter. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"The vaccine protects against HPV types 16 and 18.\""}, {"id": "b", "text": "\"Once she is vaccinated, she will not need Pap smears.\""}, {"id": "c", "text": "\"The vaccine is recommended for boys as well as girls.\""}, {"id": "d", "text": "\"Vaccination plus screening gives the best prevention.\""}]'::jsonb, '["b"]', 'Vaccination and screening together provide the best prevention, so the vaccine does not replace Pap smears. The vaccine is recommended for girls and boys and protects against HPV 16 and 18, among others.'),
  ('female', 12, 'The nurse reviews the histories of four clients. Which client''s history is most associated with an increased risk of cervical cancer?', '[{"id": "a", "text": "A 55-year-old with obesity who has never been pregnant"}, {"id": "b", "text": "A 45-year-old with a BRCA1 mutation and endometriosis"}, {"id": "c", "text": "A 70-year-old with lichen sclerosis of the vulva"}, {"id": "d", "text": "A 30-year-old with HIV who smokes cigarettes"}]'::jsonb, '["d"]', 'Smoking and immunosuppression from HIV are cervical cancer risk factors. Obesity and nulliparity point to endometrial cancer, BRCA and endometriosis to ovarian cancer, and lichen sclerosis to vulvar cancer.'),
  ('female', 13, 'A client asks the nurse why unopposed estrogen is considered the number one risk factor for endometrial cancer. Which explanation is accurate?', '[{"id": "a", "text": "Estrogen stimulates the uterus with no progesterone to counteract it"}, {"id": "b", "text": "Progesterone excess thickens the lining without estrogen balance"}, {"id": "c", "text": "Low estrogen levels after early menopause damage the lining"}, {"id": "d", "text": "Estrogen allows HPV to infect the lining of the uterus"}]'::jsonb, '["a"]', 'Unopposed estrogen means there is no progesterone to counteract estrogen, making it the number one endometrial cancer risk. Late menopause, not early menopause, is the listed risk factor.'),
  ('female', 14, 'A client with a BMI in the obese range asks why her weight increases her risk of endometrial cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Fat tissue converts estrogen into progesterone.\""}, {"id": "b", "text": "\"Fat tissue converts androgens into estrogen.\""}, {"id": "c", "text": "\"Fat tissue blocks estrogen receptors in the uterus.\""}, {"id": "d", "text": "\"Fat tissue lowers estrogen production in the body.\""}]'::jsonb, '["b"]', 'In obesity, adipose tissue converts androgens to estrogen, adding to estrogen exposure of the endometrium. Conversion of estrogen to progesterone reverses the actual process.'),
  ('female', 15, 'A client beginning tamoxifen therapy for breast cancer asks how the drug affects her uterus. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It blocks estrogen in the uterus and protects the lining.\""}, {"id": "b", "text": "\"It acts only on the breast and has no effect on the uterus.\""}, {"id": "c", "text": "\"It stimulates the endometrium and raises endometrial cancer risk.\""}, {"id": "d", "text": "\"It replaces progesterone and thins the lining of the uterus.\""}]'::jsonb, '["c"]', 'Tamoxifen is an endometrial cancer risk factor because it stimulates the endometrium while blocking estrogen in the breast. It does not protect the uterine lining.'),
  ('female', 16, 'A 64-year-old client who has been postmenopausal for 12 years mentions during a routine visit that she has had light vaginal spotting for 2 weeks. What is the nurse''s best action?', '[{"id": "a", "text": "Explain that occasional spotting is normal after menopause"}, {"id": "b", "text": "Advise her to keep a log of the spotting for 6 months"}, {"id": "c", "text": "Recommend discussing it at her next routine Pap smear"}, {"id": "d", "text": "Report the bleeding promptly so it can be evaluated"}]'::jsonb, '["d"]', 'Any postmenopausal bleeding is not normal and must be reported immediately and evaluated for endometrial cancer. Waiting or reassuring the client delays evaluation of the number one endometrial cancer symptom.'),
  ('female', 17, 'A postmenopausal client with vaginal bleeding is being evaluated for endometrial cancer. Which test does the nurse anticipate as the gold standard for diagnosis?', '[{"id": "a", "text": "Pap smear"}, {"id": "b", "text": "CA-125 level"}, {"id": "c", "text": "Mammogram"}, {"id": "d", "text": "Endometrial biopsy"}]'::jsonb, '["d"]', 'Endometrial biopsy is the gold standard for diagnosing endometrial cancer. CA-125 is an ovarian cancer marker, and the Pap smear screens for cervical cancer.'),
  ('female', 18, 'A transvaginal ultrasound on a 60-year-old postmenopausal client shows an endometrial thickness of 6 mm. How should the nurse interpret this finding?', '[{"id": "a", "text": "Normal thickness for a postmenopausal woman"}, {"id": "b", "text": "Suspicious thickness that needs further evaluation"}, {"id": "c", "text": "Thin lining that rules out endometrial cancer"}, {"id": "d", "text": "Finding that confirms a diagnosis of ovarian cancer"}]'::jsonb, '["b"]', 'In a postmenopausal woman, an endometrial thickness greater than 4 mm on transvaginal ultrasound is suspicious, so 6 mm needs further evaluation. Ultrasound assesses thickness but does not confirm a diagnosis; biopsy is the gold standard.'),
  ('female', 19, 'A client with endometrial cancer is a good surgical candidate. Which surgical treatment does the nurse anticipate as the standard approach?', '[{"id": "a", "text": "Loop electrosurgical excision of the cervix"}, {"id": "b", "text": "Cold knife conization of the cervix"}, {"id": "c", "text": "TAH-BSO with pelvic lymph node dissection"}, {"id": "d", "text": "Vulvectomy with sentinel node biopsy"}]'::jsonb, '["c"]', 'Total abdominal hysterectomy with bilateral salpingo-oophorectomy (TAH-BSO) plus pelvic lymph node dissection is the surgical standard for endometrial cancer. LEEP and conization treat pre-invasive cervical disease.'),
  ('female', 20, 'An older client with endometrial cancer is not able to undergo surgery. Which therapy does the nurse anticipate will be prescribed?', '[{"id": "a", "text": "Progestins"}, {"id": "b", "text": "Estrogen replacement"}, {"id": "c", "text": "Tamoxifen"}, {"id": "d", "text": "Trastuzumab"}]'::jsonb, '["a"]', 'Progestins are the treatment for endometrial cancer clients who cannot have surgery. Tamoxifen stimulates the endometrium and is itself an endometrial cancer risk factor.'),
  ('female', 21, 'Which client history should the nurse identify as placing the client at greatest risk for endometrial cancer?', '[{"id": "a", "text": "Three full-term pregnancies and normal weight"}, {"id": "b", "text": "Polycystic ovary syndrome and diabetes mellitus"}, {"id": "c", "text": "Menopause at age 42 and normal blood glucose"}, {"id": "d", "text": "Prior cervical cancer and in-utero DES exposure"}]'::jsonb, '["b"]', 'PCOS and diabetes mellitus are both endometrial cancer risk factors. Nulliparity and late menopause raise risk, so multiple pregnancies and early menopause do not; prior cervical cancer and DES exposure are vaginal cancer risks.'),
  ('female', 22, 'The nurse is reviewing risk factors with several clients. Which finding places a client at the highest risk for ovarian cancer?', '[{"id": "a", "text": "Long-term oral contraceptive use"}, {"id": "b", "text": "History of three pregnancies"}, {"id": "c", "text": "A BRCA1 gene mutation"}, {"id": "d", "text": "Breastfeeding two children"}]'::jsonb, '["c"]', 'BRCA1 and BRCA2 mutations carry the highest risk for ovarian cancer. Oral contraceptives, pregnancy, and breastfeeding are protective factors.'),
  ('female', 23, 'After teaching about ovarian cancer risk, which statement by the client indicates correct understanding?', '[{"id": "a", "text": "\"Long-term hormone replacement lowers my risk.\""}, {"id": "b", "text": "\"Never having been pregnant lowers my risk.\""}, {"id": "c", "text": "\"Having endometriosis lowers my risk.\""}, {"id": "d", "text": "\"Taking oral contraceptives may lower my risk.\""}]'::jsonb, '["d"]', 'Oral contraceptives, pregnancy, and breastfeeding are protective against ovarian cancer. Long-term hormone replacement, nulliparity, and endometriosis are risk factors.'),
  ('female', 24, 'A 60-year-old client reports several weeks of persistent abdominal bloating, feeling full after a few bites, and urinary frequency. The nurse recognizes these findings as possible signs of which condition?', '[{"id": "a", "text": "Ovarian cancer"}, {"id": "b", "text": "Cervical cancer"}, {"id": "c", "text": "Vulvar cancer"}, {"id": "d", "text": "Breast cancer"}]'::jsonb, '["a"]', 'Persistent bloating, early satiety, and urinary urgency or frequency are vague ovarian cancer symptoms. Cervical cancer classically causes postcoital bleeding and watery discharge.'),
  ('female', 25, 'A nursing student asks why ovarian cancer is called the "silent killer." Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It never produces symptoms at any stage"}, {"id": "b", "text": "It is found only by an annual Pap smear"}, {"id": "c", "text": "Its vague symptoms delay diagnosis to late stages"}, {"id": "d", "text": "It spreads only after menopause has occurred"}]'::jsonb, '["c"]', 'Ovarian cancer has vague, late-presenting symptoms, so it is usually diagnosed at stage III or IV. It does produce symptoms such as bloating and early satiety, but they are easily overlooked.'),
  ('female', 26, 'A client receiving chemotherapy for ovarian cancer has CA-125 levels drawn. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My CA-125 level helps show how well treatment is working.\""}, {"id": "b", "text": "\"CA-125 is a good test to screen all women for ovarian cancer.\""}, {"id": "c", "text": "\"My CA-125 could also go up with conditions like endometriosis.\""}, {"id": "d", "text": "\"There is no effective early screening test for ovarian cancer.\""}]'::jsonb, '["b"]', 'CA-125 is used to monitor treatment response, not for screening, because it is not specific. There is no effective early screening test for ovarian cancer.'),
  ('female', 27, 'A client with a history of endometriosis has an elevated CA-125 level. Which interpretation by the nurse is most accurate?', '[{"id": "a", "text": "The result confirms a diagnosis of ovarian cancer"}, {"id": "b", "text": "The result rules out pelvic inflammatory disease"}, {"id": "c", "text": "The result shows the endometriosis has resolved"}, {"id": "d", "text": "The result is not specific and needs evaluation"}]'::jsonb, '["d"]', 'CA-125 is elevated in ovarian cancer but is not specific; it also rises with endometriosis, PID, and pregnancy. Definitive ovarian cancer diagnosis requires surgical biopsy or tissue from debulking.'),
  ('female', 28, 'Pelvic ultrasound shows an ovarian mass in a 62-year-old client. She asks how the diagnosis of ovarian cancer will be confirmed. Which response is accurate?', '[{"id": "a", "text": "\"By surgical biopsy or tissue taken during debulking.\""}, {"id": "b", "text": "\"By an elevated CA-125 level alone.\""}, {"id": "c", "text": "\"By the ultrasound findings alone.\""}, {"id": "d", "text": "\"By a Pap smear with HPV testing.\""}]'::jsonb, '["a"]', 'Definitive diagnosis of ovarian cancer comes from surgical biopsy or tissue obtained during debulking. Ultrasound is initial imaging, and CA-125 is not specific.'),
  ('female', 29, 'A client who had TAH-BSO and surgical debulking for ovarian cancer is starting adjuvant chemotherapy. Which regimen does the nurse anticipate?', '[{"id": "a", "text": "Tamoxifen with an aromatase inhibitor"}, {"id": "b", "text": "Paclitaxel with cisplatin or carboplatin"}, {"id": "c", "text": "Trastuzumab with anastrozole"}, {"id": "d", "text": "Progestins with estrogen replacement"}]'::jsonb, '["b"]', 'Paclitaxel (Taxol) with cisplatin or carboplatin is the standard adjuvant chemotherapy for ovarian cancer. Tamoxifen, aromatase inhibitors, and trastuzumab are breast cancer therapies.'),
  ('female', 30, 'A 42-year-old client with a BRCA2 mutation asks whether any testing is available to watch for ovarian cancer. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A yearly Pap smear will detect ovarian cancer early.\""}, {"id": "b", "text": "\"A mammogram screens the ovaries at the same time.\""}, {"id": "c", "text": "\"CA-125 and ultrasound may be used because you are high risk.\""}, {"id": "d", "text": "\"A yearly CA-125 is recommended for all women your age.\""}]'::jsonb, '["c"]', 'There is no routine population screening for ovarian cancer; CA-125 plus ultrasound is used for high-risk clients only, such as those with BRCA mutations. A Pap smear screens for cervical cancer, not ovarian cancer.'),
  ('female', 31, 'A client tells the nurse that her mother took diethylstilbestrol (DES) while pregnant with her. The nurse recognizes that this exposure increases the client''s risk for which cancer?', '[{"id": "a", "text": "Ovarian cancer"}, {"id": "b", "text": "Breast cancer"}, {"id": "c", "text": "Endometrial cancer"}, {"id": "d", "text": "Vaginal cancer"}]'::jsonb, '["d"]', 'DES exposure in utero is a vaginal cancer risk factor, along with HPV and prior cervical cancer. BRCA mutations are the highest ovarian cancer risk, and unopposed estrogen is the top endometrial risk.'),
  ('female', 32, 'A 72-year-old client with lichen sclerosis reports persistent vulvar itching and burning, and the nurse notes a small ulcerated lesion. Which action does the nurse anticipate?', '[{"id": "a", "text": "Biopsy of the vulvar lesion"}, {"id": "b", "text": "Reassurance that itching is normal with age"}, {"id": "c", "text": "A CA-125 blood level"}, {"id": "d", "text": "A routine Pap smear in 3 years"}]'::jsonb, '["a"]', 'Persistent vulvar itching, burning, and an ulcer in a client with lichen sclerosis and older age suggest vulvar cancer, and any suspicious vulvar lesion must be biopsied. Delaying or reassuring the client is unsafe.'),
  ('female', 33, 'A 56-year-old client reports finding a breast lump. Which description is most consistent with the typical presentation of breast cancer?', '[{"id": "a", "text": "A painful lump with fever near the nipple"}, {"id": "b", "text": "A painless lump in the upper outer quadrant"}, {"id": "c", "text": "A painful lump in the lower inner quadrant"}, {"id": "d", "text": "A painless lump that is felt only during menses"}]'::jsonb, '["b"]', 'A painless lump is the most common presentation of breast cancer, typically in the upper outer quadrant. A painful lump does not fit the classic presentation.'),
  ('female', 34, 'During a breast assessment, the nurse notes thickened, pitted skin resembling an orange peel over part of the client''s breast. The nurse recognizes this finding may indicate which condition?', '[{"id": "a", "text": "A benign fluid-filled cyst"}, {"id": "b", "text": "An expected effect of tamoxifen"}, {"id": "c", "text": "Inflammatory breast cancer or lymphatic blockage"}, {"id": "d", "text": "Normal skin changes from aging"}]'::jsonb, '["c"]', 'Peau d''orange (orange-peel skin) indicates inflammatory breast cancer or skin edema from lymph blockage. It is not a normal or expected finding.'),
  ('female', 35, 'The nurse is assessing a non-lactating client with suspected breast cancer. Which additional findings would the nurse expect?', '[{"id": "a", "text": "Postcoital bleeding and watery discharge"}, {"id": "b", "text": "Persistent vulvar itching and burning"}, {"id": "c", "text": "Early satiety and urinary frequency"}, {"id": "d", "text": "Nipple retraction and skin dimpling"}]'::jsonb, '["d"]', 'Nipple retraction or discharge in a non-lactating client, skin dimpling, asymmetry, and axillary lymphadenopathy are breast cancer signs. Postcoital bleeding suggests cervical cancer, and early satiety suggests ovarian cancer.'),
  ('female', 36, 'For which client does the nurse anticipate that breast MRI will be ordered?', '[{"id": "a", "text": "A client with a BRCA2 mutation and dense breasts"}, {"id": "b", "text": "A client needing a definitive tissue diagnosis"}, {"id": "c", "text": "A client needing to know if a mass is a cyst"}, {"id": "d", "text": "An average-risk client with no breast symptoms"}]'::jsonb, '["a"]', 'MRI is used for high-risk (BRCA-positive) clients and those with dense breasts. Core needle biopsy gives the definitive diagnosis, and ultrasound differentiates cyst from solid mass.'),
  ('female', 37, 'A client''s mammogram and ultrasound show a solid breast mass. She asks which test will tell her for certain whether it is cancer. Which response is accurate?', '[{"id": "a", "text": "\"A repeat mammogram in 6 months\""}, {"id": "b", "text": "\"A breast MRI\""}, {"id": "c", "text": "\"A core needle biopsy\""}, {"id": "d", "text": "\"A CA-125 blood test\""}]'::jsonb, '["c"]', 'Core needle biopsy provides the definitive diagnosis of breast cancer. MRI is an imaging tool for high-risk clients and dense breasts, not a definitive diagnosis.'),
  ('female', 38, 'The nurse reviews the histories of four clients. Which client has the most risk factors for breast cancer?', '[{"id": "a", "text": "A 30-year-old with three children who does not drink alcohol"}, {"id": "b", "text": "A 58-year-old who drinks alcohol and whose sister had breast cancer"}, {"id": "c", "text": "A 25-year-old with late menarche and a normal body weight"}, {"id": "d", "text": "A 40-year-old with HPV infection who smokes cigarettes"}]'::jsonb, '["b"]', 'Age over 50, alcohol use, and a first-degree relative with breast cancer are all breast cancer risk factors. HPV and smoking are cervical cancer risks, and late menarche is the reverse of the early-menarche risk.'),
  ('female', 39, 'A client with early breast cancer asks about breast-conserving surgery. Which statement by the nurse about lumpectomy is accurate?', '[{"id": "a", "text": "\"It removes the entire breast along with the axillary nodes.\""}, {"id": "b", "text": "\"It removes breast tissue only and needs no further treatment.\""}, {"id": "c", "text": "\"It is used only for clients with HER2-positive tumors.\""}, {"id": "d", "text": "\"It removes the tumor with a margin and is followed by radiation.\""}]'::jsonb, '["d"]', 'Lumpectomy is breast-conserving surgery that removes the tumor with a margin and axillary nodes and is followed by radiation. Removing the entire breast describes mastectomy.'),
  ('female', 40, 'A client scheduled for a modified radical mastectomy asks what will be removed. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The breast and the axillary lymph nodes\""}, {"id": "b", "text": "\"The breast tissue only\""}, {"id": "c", "text": "\"The tumor with a small margin only\""}, {"id": "d", "text": "\"The axillary lymph nodes only\""}]'::jsonb, '["a"]', 'A modified radical mastectomy removes the breast plus the axillary lymph nodes. A simple mastectomy removes the breast only, and removing just the tumor with a margin is a lumpectomy.'),
  ('female', 41, 'A premenopausal client with ER-positive breast cancer is prescribed tamoxifen. Which statement by the client indicates understanding of the medication?', '[{"id": "a", "text": "\"It raises my estrogen levels; I take it for 6 months.\""}, {"id": "b", "text": "\"It targets HER2 protein; I take it until surgery.\""}, {"id": "c", "text": "\"It blocks estrogen receptors; I may take it 5 to 10 years.\""}, {"id": "d", "text": "\"It stops estrogen production; I take it for 1 month.\""}]'::jsonb, '["c"]', 'Tamoxifen blocks estrogen receptors in ER/PR-positive cancers in premenopausal women and is taken for 5 to 10 years. HER2-targeted therapy is trastuzumab.'),
  ('female', 42, 'A 66-year-old postmenopausal client has ER/PR-positive breast cancer. Which medication does the nurse anticipate will be prescribed?', '[{"id": "a", "text": "Paclitaxel"}, {"id": "b", "text": "Anastrozole"}, {"id": "c", "text": "Progestin"}, {"id": "d", "text": "Cisplatin"}]'::jsonb, '["b"]', 'Aromatase inhibitors such as anastrozole and letrozole are used for postmenopausal ER/PR-positive breast cancer. Paclitaxel with cisplatin is the standard ovarian cancer regimen.'),
  ('female', 43, 'Hormone receptor testing on a client''s breast tumor shows it is HER2-positive. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Letrozole"}, {"id": "b", "text": "Anastrozole"}, {"id": "c", "text": "Cisplatin"}, {"id": "d", "text": "Trastuzumab"}]'::jsonb, '["d"]', 'Trastuzumab (Herceptin) is targeted antibody therapy for HER2-positive breast cancer. Letrozole and anastrozole are aromatase inhibitors for postmenopausal ER/PR-positive disease.'),
  ('female', 44, 'A client had a left modified radical mastectomy. Which action by the unlicensed assistive personnel (UAP) requires correction by the nurse?', '[{"id": "a", "text": "Measuring the client''s blood pressure on the left arm"}, {"id": "b", "text": "Elevating the client''s left arm on a pillow at rest"}, {"id": "c", "text": "Measuring the client''s blood pressure on the right arm"}, {"id": "d", "text": "Removing a tight bracelet from the client''s left wrist"}]'::jsonb, '["a"]', 'No blood pressure measurements should be taken on the affected (left) arm, to prevent lymphedema. Elevating the arm at rest and avoiding tight jewelry on that arm are correct precautions.'),
  ('female', 45, 'The nurse needs to draw blood from a client who had a right mastectomy with axillary node removal 3 years ago. The right arm shows no swelling. Which action is appropriate?', '[{"id": "a", "text": "Use the right arm because 3 years have passed"}, {"id": "b", "text": "Use the left arm because the restriction is lifelong"}, {"id": "c", "text": "Use the right arm because there is no swelling"}, {"id": "d", "text": "Use the right arm with a smaller-gauge needle"}]'::jsonb, '["b"]', 'Affected arm precautions are lifelong, so venipuncture and IV access are avoided on the affected arm regardless of time since surgery or absence of swelling.'),
  ('female', 46, 'The nurse teaches a client about lymphedema prevention after a right mastectomy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will elevate my right arm when I am resting.\""}, {"id": "b", "text": "\"I will protect my right arm from cuts and infection.\""}, {"id": "c", "text": "\"I will keep wearing my snug watch on my right wrist.\""}, {"id": "d", "text": "\"I will do the pendulum arm exercises as directed.\""}]'::jsonb, '["c"]', 'Tight clothing and jewelry should be avoided on the affected arm. Elevating the arm at rest, protecting it from cuts and infection, and doing pendulum exercises as directed are correct.'),
  ('female', 47, 'A client is 1 day post-op after an abdominal hysterectomy. Which nursing intervention best reduces the client''s risk of deep vein thrombosis?', '[{"id": "a", "text": "Keeping the client on strict bed rest for 48 hours"}, {"id": "b", "text": "Removing the compression devices while she is in bed"}, {"id": "c", "text": "Delaying ambulation until the urinary catheter is out"}, {"id": "d", "text": "Applying SCDs and promoting early ambulation"}]'::jsonb, '["d"]', 'Immobility plus pelvic surgery creates DVT risk, so SCDs and early ambulation are used. Bed rest, removing SCDs in bed, or delaying ambulation increases immobility and DVT risk.'),
  ('female', 48, 'A client is 4 days post-op after a hysterectomy. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "Foul-smelling vaginal discharge"}, {"id": "b", "text": "Sadness about the loss of fertility"}, {"id": "c", "text": "Asking when intercourse may resume"}, {"id": "d", "text": "Walking in the hallway three times daily"}]'::jsonb, '["a"]', 'Foul vaginal discharge, excessive bleeding, fever, and difficulty urinating should be reported after hysterectomy. Sadness about lost fertility calls for grief and emotional support, and ambulating is expected.'),
  ('female', 49, 'The nurse provides discharge teaching to a client after a hysterectomy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will not lift anything heavier than 10 pounds.\""}, {"id": "b", "text": "\"I can resume sexual intercourse in 2 weeks.\""}, {"id": "c", "text": "\"I will report a fever or trouble urinating.\""}, {"id": "d", "text": "\"I will walk often to help prevent blood clots.\""}]'::jsonb, '["b"]', 'Sexual intercourse is avoided for 6 weeks after hysterectomy, until the pelvic floor has healed. Avoiding lifting over 10 lbs, reporting fever or difficulty urinating, and walking to prevent DVT are correct.'),
  ('female', 50, 'A 44-year-old premenopausal client is scheduled for a TAH-BSO. She asks how the surgery will affect her hormonally. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Menopause will not occur because you are under 50.\""}, {"id": "b", "text": "\"Menopause occurs only if you also receive radiation.\""}, {"id": "c", "text": "\"Removing both ovaries will bring on menopause.\""}, {"id": "d", "text": "\"Your fertility will return once your incision heals.\""}]'::jsonb, '["c"]', 'Removing both ovaries (BSO) causes menopause, and hysterectomy results in loss of fertility, so the client needs grief and emotional support. Fertility does not return after hysterectomy.'),
  ('male', 1, 'A 68-year-old client with prostate cancer asks why he has trouble starting his urine stream. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"The prostate surrounds the urethra, so enlargement affects urination.\""}, {"id": "b", "text": "\"The cancer has spread to the kidneys and reduced urine production.\""}, {"id": "c", "text": "\"Low testosterone levels weaken the muscles of the bladder.\""}, {"id": "d", "text": "\"The prostate sits above the bladder and presses down on it.\""}]'::jsonb, '["a"]', 'The walnut-sized prostate encircles the urethra, so enlargement causes urinary symptoms such as hesitancy. The other explanations do not reflect where the prostate sits or why urinary symptoms occur.'),
  ('male', 2, 'The nurse is teaching a community group about prostate cancer. Which risk factor should the nurse identify as the most important?', '[{"id": "a", "text": "A high-fat diet"}, {"id": "b", "text": "Age over 50"}, {"id": "c", "text": "Cadmium exposure at work"}, {"id": "d", "text": "Cryptorchidism"}]'::jsonb, '["b"]', 'Age over 50 is the most important prostate cancer risk factor. A high-fat diet and cadmium exposure are also risks but are not the most important, and cryptorchidism is the number one testicular cancer risk.'),
  ('male', 3, 'A 43-year-old African American client whose father had prostate cancer asks when he should start thinking about prostate cancer screening. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Screening is not considered until you turn 65.\""}, {"id": "b", "text": "\"Screening is not considered until you turn 50.\""}, {"id": "c", "text": "\"Your risk is high, so a screening decision is due now.\""}, {"id": "d", "text": "\"Screening is needed only if you develop symptoms.\""}]'::jsonb, '["c"]', 'High-risk men, including African American men and those with a family history, make the screening decision at age 40 to 45. Age 50 is the screening decision point for average-risk men.'),
  ('male', 4, 'A 50-year-old client with no family history and no other prostate cancer risk factors asks whether he should consider prostate cancer screening. Which response by the nurse is appropriate?', '[{"id": "a", "text": "\"You should have waited until age 65 to decide.\""}, {"id": "b", "text": "\"You should have decided by age 40 at the latest.\""}, {"id": "c", "text": "\"Screening is needed only once symptoms appear.\""}, {"id": "d", "text": "\"At your risk level, age 50 is the time to decide.\""}]'::jsonb, '["d"]', 'For average-risk men, the prostate screening decision is made at age 50 using PSA and DRE. Waiting for symptoms is unsafe because early prostate cancer is often asymptomatic.'),
  ('male', 5, 'The nurse is assessing a 72-year-old client with suspected prostate cancer. Which assessment findings would the nurse expect?', '[{"id": "a", "text": "Difficulty starting urination and nocturia"}, {"id": "b", "text": "A painless lump and scrotal heaviness"}, {"id": "c", "text": "A non-healing ulcer and foul discharge"}, {"id": "d", "text": "Enlarged breasts and groin aching"}]'::jsonb, '["a"]', 'Prostate cancer causes urinary hesitancy, dribbling, nocturia, and hematuria. A painless lump, scrotal heaviness, gynecomastia, and groin ache are testicular cancer findings, and a non-healing ulcer suggests penile cancer.'),
  ('male', 6, 'A client being treated for prostate cancer reports new, persistent low back and hip pain. The nurse recognizes this finding may indicate which complication?', '[{"id": "a", "text": "Urinary retention"}, {"id": "b", "text": "Bone metastases"}, {"id": "c", "text": "Erectile dysfunction"}, {"id": "d", "text": "Lymphatic spread to the scrotum"}]'::jsonb, '["b"]', 'Low back or bone pain in prostate cancer results from bone metastases to the spine, hips, and pelvis. Urinary retention and erectile dysfunction do not explain new back and hip pain.'),
  ('male', 7, 'The nurse provides teaching about prostate cancer to a 55-year-old client. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"A digital rectal exam checks for a hard, irregular prostate.\""}, {"id": "b", "text": "\"Blood in my urine is a symptom I should report.\""}, {"id": "c", "text": "\"I have no urinary symptoms, so I cannot have prostate cancer.\""}, {"id": "d", "text": "\"The PSA test can also be high with BPH or prostatitis.\""}]'::jsonb, '["c"]', 'Early prostate cancer is often asymptomatic, so the absence of urinary symptoms does not rule it out. The other statements about DRE findings, hematuria, and PSA are accurate.'),
  ('male', 8, 'A 64-year-old client recently treated for prostatitis has an elevated PSA level. How should the nurse interpret this result?', '[{"id": "a", "text": "It confirms prostate cancer and staging should begin"}, {"id": "b", "text": "It rules out prostate cancer because prostatitis is present"}, {"id": "c", "text": "It confirms bone metastases from prostate cancer"}, {"id": "d", "text": "It is not specific, since prostatitis can also raise PSA"}]'::jsonb, '["d"]', 'PSA is elevated in prostate cancer, BPH, and prostatitis, so an elevated value is not specific. Diagnosis is confirmed only by prostate biopsy.'),
  ('male', 9, 'During a digital rectal exam, which prostate finding should the nurse recognize as most suggestive of prostate cancer?', '[{"id": "a", "text": "A hard, nodular, irregular gland"}, {"id": "b", "text": "A soft, smooth, symmetric gland"}, {"id": "c", "text": "A small, smooth, tender gland"}, {"id": "d", "text": "A boggy, smooth, uniform gland"}]'::jsonb, '["a"]', 'DRE is used to feel for a hard, nodular, irregular prostate, which suggests cancer. Smooth or soft glands do not match this description.'),
  ('male', 10, 'A client''s prostate biopsy report includes a Gleason score. The client asks what this score means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It measures the PSA level in your blood.\""}, {"id": "b", "text": "\"It grades how aggressive the cancer is.\""}, {"id": "c", "text": "\"It shows whether the cancer is in your bones.\""}, {"id": "d", "text": "\"It measures how much urine your bladder holds.\""}]'::jsonb, '["b"]', 'Prostate biopsy confirms the diagnosis, and the Gleason score grades the cancer''s aggressiveness. A bone scan, not the Gleason score, is used when bone metastases are suspected.'),
  ('male', 11, 'A client with an elevated PSA and an irregular prostate on DRE is scheduled for a needle biopsy. Which procedure does the nurse anticipate will be used to guide the biopsy?', '[{"id": "a", "text": "Scrotal ultrasound"}, {"id": "b", "text": "Bone scan"}, {"id": "c", "text": "Transrectal ultrasound"}, {"id": "d", "text": "Chest x-ray"}]'::jsonb, '["c"]', 'Transrectal ultrasound (TRUS) guides the prostate needle biopsy. Scrotal ultrasound is the initial test for a testicular mass, and a bone scan is used when bone metastases are suspected.'),
  ('male', 12, 'A client with confirmed prostate cancer reports new pain in his spine and pelvis. Which diagnostic test does the nurse anticipate?', '[{"id": "a", "text": "Repeat digital rectal exam"}, {"id": "b", "text": "Scrotal ultrasound"}, {"id": "c", "text": "Serum AFP level"}, {"id": "d", "text": "Bone scan"}]'::jsonb, '["d"]', 'A bone scan is done when bone metastases are suspected, and prostate cancer spreads to the spine, hips, and pelvis. AFP is a testicular cancer marker.'),
  ('male', 13, 'An 84-year-old client has low-risk, slow-growing prostate cancer and has chosen active surveillance. Which statement by the nurse best describes this plan?', '[{"id": "a", "text": "\"Your PSA and rectal exams will be monitored over time.\""}, {"id": "b", "text": "\"Radioactive seeds will be placed into your prostate.\""}, {"id": "c", "text": "\"Your entire prostate will be removed robotically.\""}, {"id": "d", "text": "\"You will receive monthly injections to lower testosterone.\""}]'::jsonb, '["a"]', 'Active surveillance is watchful waiting for low-risk, slow-growing cancer in elderly clients, with monitoring of PSA and DRE. Seed implants describe brachytherapy, and removing the prostate is radical prostatectomy.'),
  ('male', 14, 'A client with localized prostate cancer asks what brachytherapy involves. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A beam of radiation is aimed at the prostate from outside.\""}, {"id": "b", "text": "\"Radioactive seeds are implanted directly into the prostate.\""}, {"id": "c", "text": "\"The entire prostate gland is removed through small incisions.\""}, {"id": "d", "text": "\"A medication is injected to reduce your testosterone level.\""}]'::jsonb, '["b"]', 'Brachytherapy implants radioactive seeds directly into the prostate gland. External beam radiation delivers targeted radiation from outside the body.'),
  ('male', 15, 'A client with metastatic prostate cancer is prescribed leuprolide (Lupron). Which explanation of the drug''s action should the nurse provide?', '[{"id": "a", "text": "\"It increases testosterone to slow the tumor.\""}, {"id": "b", "text": "\"It destroys cancer cells in the bones directly.\""}, {"id": "c", "text": "\"It reduces testosterone as a GnRH agonist.\""}, {"id": "d", "text": "\"It improves erectile function after surgery.\""}]'::jsonb, '["c"]', 'Leuprolide is a GnRH agonist used in androgen deprivation therapy to reduce testosterone in metastatic disease. Increasing testosterone is the opposite of its action, and sildenafil is the drug that may be prescribed for erectile dysfunction.'),
  ('male', 16, 'A client''s metastatic prostate cancer continues to progress despite androgen deprivation therapy (castrate-resistant). Which medication does the nurse anticipate?', '[{"id": "a", "text": "Sildenafil"}, {"id": "b", "text": "Bleomycin"}, {"id": "c", "text": "Etoposide"}, {"id": "d", "text": "Docetaxel"}]'::jsonb, '["d"]', 'Docetaxel is the chemotherapy used for castrate-resistant metastatic prostate cancer. Bleomycin and etoposide are part of the BEP regimen for testicular NSGCT, and sildenafil is for erectile dysfunction.'),
  ('male', 17, 'A client returned from a radical prostatectomy 6 hours ago and has an indwelling urinary catheter. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "Clots blocking catheter drainage"}, {"id": "b", "text": "Light pink, blood-tinged urine"}, {"id": "c", "text": "A patent catheter draining well"}, {"id": "d", "text": "Mild concern about future erections"}]'::jsonb, '["a"]', 'After prostate surgery, the nurse monitors catheter output, color, and patency and reports clots or blockage. A small amount of blood-tinged urine is normal post-op.'),
  ('male', 18, 'The nurse is caring for a client on the first day after a radical prostatectomy. Which urine finding is expected?', '[{"id": "a", "text": "Bright red urine with clots"}, {"id": "b", "text": "Small amount of blood-tinged urine"}, {"id": "c", "text": "No urine output for 4 hours"}, {"id": "d", "text": "Bright red urine with a fever"}]'::jsonb, '["b"]', 'A small amount of blood-tinged urine is normal after prostate surgery. Bright red blood in the urine, fever, clots, and absent output should be reported.'),
  ('male', 19, 'A client who had a radical prostatectomy asks when he should begin Kegel exercises and why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Wait 6 months after surgery; they improve erections.\""}, {"id": "b", "text": "\"Start before surgery only; they prevent catheter clots.\""}, {"id": "c", "text": "\"Start once the catheter is removed; they improve continence.\""}, {"id": "d", "text": "\"Start only if leakage persists a year; they shrink the prostate.\""}]'::jsonb, '["c"]', 'Kegel exercises strengthen the pelvic floor and should begin as soon as the catheter is removed to improve urinary continence. Delaying them is not supported.'),
  ('male', 20, 'The urinary catheter of a client who had a prostatectomy is removed this morning. Which instruction should the nurse give the client?', '[{"id": "a", "text": "\"Limit fluids so you will not need to void today.\""}, {"id": "b", "text": "\"Any amount of bright red urine is expected now.\""}, {"id": "c", "text": "\"Wait 24 hours before trying to void on your own.\""}, {"id": "d", "text": "\"Try to void, and tell me if you are unable to.\""}]'::jsonb, '["d"]', 'There is a risk of urinary retention after catheter removal, so the client is taught to void and report inability to void. Bright red blood in the urine should be reported, not considered expected.'),
  ('male', 21, 'A client preparing for a nerve-sparing radical prostatectomy asks whether the surgery will affect his ability to have erections. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"ED is common even with nerve-sparing, and sildenafil may help.\""}, {"id": "b", "text": "\"Nerve-sparing surgery fully prevents ED in every client.\""}, {"id": "c", "text": "\"ED occurs only if radioactive seeds are also implanted.\""}, {"id": "d", "text": "\"ED cannot be treated after any type of prostate surgery.\""}]'::jsonb, '["a"]', 'Nerve-sparing surgery helps, but erectile dysfunction is still common after prostatectomy, and sildenafil (Viagra) may be prescribed. Saying nerve-sparing fully prevents ED is inaccurate.'),
  ('male', 22, 'During a health history, which occupational exposure reported by a 58-year-old client should the nurse identify as a risk factor for prostate cancer?', '[{"id": "a", "text": "Asbestos"}, {"id": "b", "text": "Cadmium"}, {"id": "c", "text": "Benzene"}, {"id": "d", "text": "Silica dust"}]'::jsonb, '["b"]', 'Occupational exposure to cadmium is a listed prostate cancer risk factor. The other exposures are not identified as prostate cancer risks.'),
  ('male', 23, 'The nurse reviews the histories of four male clients. Which history is a risk factor for prostate cancer rather than for testicular or penile cancer?', '[{"id": "a", "text": "Cryptorchidism"}, {"id": "b", "text": "Phimosis"}, {"id": "c", "text": "High-fat diet"}, {"id": "d", "text": "Klinefelter syndrome"}]'::jsonb, '["c"]', 'A high-fat diet is a prostate cancer risk factor. Cryptorchidism and Klinefelter syndrome are testicular cancer risks, and phimosis is a penile cancer risk.'),
  ('male', 24, 'A school nurse is planning testicular self-exam teaching. Which group should the nurse recognize as having the peak incidence of testicular cancer?', '[{"id": "a", "text": "Boys younger than 10 years"}, {"id": "b", "text": "Men older than 50 years"}, {"id": "c", "text": "Men older than 65 years"}, {"id": "d", "text": "Young men aged 15 to 35"}]'::jsonb, '["d"]', 'Testicular cancer is the most common cancer in young men aged 15 to 35. Age over 50 is the most important risk factor for prostate cancer, not testicular cancer.'),
  ('male', 25, 'While taking the health history of a 19-year-old client, the nurse notes that he had an undescended testicle as an infant. The nurse recognizes this as which type of risk?', '[{"id": "a", "text": "The number one risk for testicular cancer"}, {"id": "b", "text": "The number one risk for prostate cancer"}, {"id": "c", "text": "The number one risk for penile cancer"}, {"id": "d", "text": "A risk only for erectile dysfunction"}]'::jsonb, '["a"]', 'Cryptorchidism (undescended testicle) is the number one risk factor for testicular cancer. Age over 50 is the most important prostate cancer risk.'),
  ('male', 26, 'A 22-year-old client tells the nurse he found a firm, painless lump on his right testicle last week. What is the nurse''s priority action?', '[{"id": "a", "text": "Advise him to recheck the lump in 3 months"}, {"id": "b", "text": "Arrange prompt evaluation with scrotal ultrasound"}, {"id": "c", "text": "Reassure him that painless lumps are benign"}, {"id": "d", "text": "Advise him to return only if pain develops"}]'::jsonb, '["b"]', 'A painless testicular mass in a young male is testicular cancer until proven otherwise and requires immediate evaluation with scrotal ultrasound. Waiting for pain is unsafe because pain is uncommon.'),
  ('male', 27, 'The nurse teaches a 25-year-old client about testicular cancer warning signs. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"A feeling of heaviness in my scrotum should be checked.\""}, {"id": "b", "text": "\"A change in the size of a testicle should be reported.\""}, {"id": "c", "text": "\"A lump that does not hurt is probably nothing to worry about.\""}, {"id": "d", "text": "\"A dull ache in my groin could be a warning sign.\""}]'::jsonb, '["c"]', 'Pain is uncommon in testicular cancer, and the absence of pain does not rule it out; a painless lump is the number one presenting symptom. Scrotal heaviness, groin ache, and size changes are correctly identified.'),
  ('male', 28, 'A 24-year-old client with a testicular mass also has newly enlarged breasts. The client asks how the two could be related. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Breast growth is caused by the scrotal ultrasound.\""}, {"id": "b", "text": "\"Breast growth means the cancer has spread to the chest.\""}, {"id": "c", "text": "\"Breast growth is unrelated to a testicular mass.\""}, {"id": "d", "text": "\"Some testicular tumors make hCG or estrogen.\""}]'::jsonb, '["d"]', 'Gynecomastia can occur because some testicular tumors produce hCG or estrogen. It does not by itself indicate spread to the chest.'),
  ('male', 29, 'A 28-year-old client is being evaluated for testicular cancer. In addition to a testicular lump, which findings would the nurse expect the client to report?', '[{"id": "a", "text": "Scrotal heaviness and a dull ache in the groin"}, {"id": "b", "text": "Urinary hesitancy and waking at night to urinate"}, {"id": "c", "text": "Foul discharge from under the foreskin and itching"}, {"id": "d", "text": "Low back pain and blood in the urine"}]'::jsonb, '["a"]', 'Testicular cancer can cause a feeling of heaviness in the scrotum and a dull ache in the lower abdomen or groin. Hesitancy, nocturia, hematuria, and back pain fit prostate cancer, and foul discharge fits penile cancer.'),
  ('male', 30, 'A client with a testicular tumor has an elevated alpha-fetoprotein (AFP) level. How should the nurse interpret this finding?', '[{"id": "a", "text": "It indicates a pure seminoma"}, {"id": "b", "text": "It indicates a non-seminomatous germ cell tumor"}, {"id": "c", "text": "It indicates the tumor is a benign cyst"}, {"id": "d", "text": "It indicates prostate cancer has spread"}]'::jsonb, '["b"]', 'AFP is elevated in non-seminomatous germ cell tumors (NSGCT) and is normal in pure seminoma. An elevated AFP therefore points away from a pure seminoma.'),
  ('male', 31, 'A client with testicular cancer has an elevated lactate dehydrogenase (LDH) level. Which statement best describes how this marker is used?', '[{"id": "a", "text": "It is specific and confirms the diagnosis"}, {"id": "b", "text": "It identifies the tumor as a pure seminoma"}, {"id": "c", "text": "It is non-specific and helps with staging"}, {"id": "d", "text": "It is used to screen healthy young men"}]'::jsonb, '["c"]', 'LDH is non-specific, elevated in advanced disease, and used for staging and prognosis. Definitive diagnosis comes from radical inguinal orchiectomy.'),
  ('male', 32, 'A 20-year-old client with a scrotal mass is scheduled for his first diagnostic test. The client asks what this test will show. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"A bone scan will show whether the mass has spread.\""}, {"id": "b", "text": "\"A biopsy through the scrotum will confirm cancer.\""}, {"id": "c", "text": "\"A PSA blood test will show whether it is cancer.\""}, {"id": "d", "text": "\"An ultrasound will show if the mass is solid or cystic.\""}]'::jsonb, '["d"]', 'Scrotal ultrasound is the initial test and differentiates a solid from a cystic mass. Scrotal biopsy is contraindicated because it risks lymphatic spread.'),
  ('male', 33, 'A client with a solid testicular mass on ultrasound has several new orders. Which order should the nurse question?', '[{"id": "a", "text": "Needle biopsy through the scrotum"}, {"id": "b", "text": "Serum AFP, beta-hCG, and LDH levels"}, {"id": "c", "text": "CT of the abdomen, pelvis, and chest"}, {"id": "d", "text": "Sperm banking consultation"}]'::jsonb, '["a"]', 'Scrotal biopsy is contraindicated because it risks lymphatic spread; diagnosis is made by trans-inguinal radical orchiectomy. Tumor markers, staging CT, and sperm banking are appropriate.'),
  ('male', 34, 'A client is newly diagnosed with testicular cancer, and the tumor type and stage are still being determined. Which treatment does the nurse anticipate first?', '[{"id": "a", "text": "BEP chemotherapy"}, {"id": "b", "text": "Radical inguinal orchiectomy"}, {"id": "c", "text": "Retroperitoneal lymph node dissection"}, {"id": "d", "text": "Radiation to the abdomen"}]'::jsonb, '["b"]', 'Radical inguinal orchiectomy is the first step in testicular cancer treatment regardless of type or stage. BEP, radiation, and RPLND depend on tumor type and lymph node involvement.'),
  ('male', 35, 'After orchiectomy, a client''s pathology shows an early-stage seminoma. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Docetaxel chemotherapy"}, {"id": "b", "text": "Leuprolide injections"}, {"id": "c", "text": "Radiation therapy"}, {"id": "d", "text": "Penectomy"}]'::jsonb, '["c"]', 'Early-stage seminoma is treated with radiation, while advanced seminoma receives cisplatin-based chemotherapy. Docetaxel and leuprolide are prostate cancer treatments.'),
  ('male', 36, 'A client with a non-seminomatous germ cell tumor (NSGCT) is starting the standard chemotherapy regimen. Which combination does the nurse anticipate?', '[{"id": "a", "text": "Leuprolide and docetaxel"}, {"id": "b", "text": "Docetaxel and sildenafil"}, {"id": "c", "text": "Leuprolide alone"}, {"id": "d", "text": "Bleomycin, etoposide, and cisplatin"}]'::jsonb, '["d"]', 'BEP chemotherapy (bleomycin, etoposide, cisplatin) is the standard regimen for NSGCT. Leuprolide and docetaxel are used for prostate cancer.'),
  ('male', 37, 'Staging CT after orchiectomy shows lymph node involvement in a client with testicular cancer. Which surgical procedure does the nurse anticipate?', '[{"id": "a", "text": "Retroperitoneal lymph node dissection"}, {"id": "b", "text": "Radical prostatectomy with seed implants"}, {"id": "c", "text": "Partial penectomy with node biopsy"}, {"id": "d", "text": "Scrotal biopsy of the remaining testicle"}]'::jsonb, '["a"]', 'Retroperitoneal lymph node dissection (RPLND) is performed for testicular cancer with lymph node involvement. Scrotal biopsy is contraindicated.'),
  ('male', 38, 'A 26-year-old client is scheduled for a radical inguinal orchiectomy followed by chemotherapy. He mentions he hopes to have children someday. Which nursing action is the priority before treatment?', '[{"id": "a", "text": "Teach him to begin Kegel exercises"}, {"id": "b", "text": "Discuss sperm banking before treatment"}, {"id": "c", "text": "Schedule a PSA and DRE after surgery"}, {"id": "d", "text": "Teach him to wait for pain before reporting"}]'::jsonb, '["b"]', 'Sperm banking should be offered and recommended before orchiectomy or chemotherapy, because both can reduce fertility. Kegel exercises are post-prostatectomy teaching.'),
  ('male', 39, 'The nurse teaches a 17-year-old client how to perform a testicular self-exam (TSE). Which instruction is accurate?', '[{"id": "a", "text": "\"Do the exam once a year before a cold shower.\""}, {"id": "b", "text": "\"Do the exam weekly while the scrotum is tight.\""}, {"id": "c", "text": "\"Do the exam monthly after a warm bath or shower.\""}, {"id": "d", "text": "\"Do the exam only when a testicle becomes painful.\""}]'::jsonb, '["c"]', 'TSE is done monthly and is best performed after a warm bath or shower, when the scrotum is relaxed. Waiting for pain is unsafe because pain is uncommon in testicular cancer.'),
  ('male', 40, 'The nurse evaluates a client''s understanding of testicular self-exam technique. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will gently roll each testicle between my thumb and fingers.\""}, {"id": "b", "text": "\"I will report any new lump or area of hardness.\""}, {"id": "c", "text": "\"I will do the exam after a warm shower each month.\""}, {"id": "d", "text": "\"I will report a lump but not a change in shape.\""}]'::jsonb, '["d"]', 'Any new lump, hardness, or change in size or shape should be reported after TSE. Gently rolling each testicle between the thumb and fingers after a warm shower is correct technique.'),
  ('male', 41, 'A client who had a radical inguinal orchiectomy for testicular cancer asks whether he still needs to do testicular self-exams. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, prior testicular cancer raises the risk in the other testicle.\""}, {"id": "b", "text": "\"No, removing one testicle eliminates the risk of testicular cancer.\""}, {"id": "c", "text": "\"No, self-exams are needed only by men older than 50.\""}, {"id": "d", "text": "\"Only if you develop pain in the remaining testicle.\""}]'::jsonb, '["a"]', 'Prior testicular cancer is a risk factor because of contralateral risk, so self-exams remain important. Waiting for pain is unsafe because pain is uncommon.'),
  ('male', 42, 'The nurse reviews the histories of four male clients. Which client has the most risk factors for penile cancer?', '[{"id": "a", "text": "A circumcised client with a high-fat diet"}, {"id": "b", "text": "An uncircumcised client with phimosis who smokes"}, {"id": "c", "text": "A client with cryptorchidism and Klinefelter syndrome"}, {"id": "d", "text": "A client with cadmium exposure and a BRCA2 mutation"}]'::jsonb, '["b"]', 'Being uncircumcised, having phimosis, and smoking are penile cancer risk factors. Cryptorchidism and Klinefelter syndrome are testicular risks, while a high-fat diet, cadmium, and BRCA are prostate risks.'),
  ('male', 43, 'A 66-year-old uncircumcised client reports a red sore on his penis that has not healed for several weeks and a foul-smelling discharge from under his foreskin. The nurse recognizes these findings as consistent with which condition?', '[{"id": "a", "text": "Prostate cancer"}, {"id": "b", "text": "Testicular cancer"}, {"id": "c", "text": "Penile cancer"}, {"id": "d", "text": "Urinary retention"}]'::jsonb, '["c"]', 'A red, ulcerated, non-healing penile lesion and foul-smelling discharge from under the foreskin are presenting signs of penile cancer. Testicular cancer typically presents as a painless testicular lump.'),
  ('male', 44, 'A client with a biopsy-confirmed penile lesion has swollen, palpable lymph nodes in both groins. The nurse recognizes this finding as most likely indicating which?', '[{"id": "a", "text": "An expected reaction to the biopsy"}, {"id": "b", "text": "Spread to the bones of the pelvis"}, {"id": "c", "text": "A normal finding needing no follow-up"}, {"id": "d", "text": "Lymph node involvement by the cancer"}]'::jsonb, '["d"]', 'Swollen, palpable inguinal lymph nodes in penile cancer indicate lymph node involvement, and enlarged nodes are palpated and biopsied. It is not a normal finding to ignore.'),
  ('male', 45, 'A client admits he waited 8 months to report a penile sore because he felt embarrassed. Which understanding should guide the nurse''s response?', '[{"id": "a", "text": "Embarrassment often delays penile cancer diagnosis"}, {"id": "b", "text": "Penile sores usually heal without any evaluation"}, {"id": "c", "text": "Penile cancer is mostly found early on routine exams"}, {"id": "d", "text": "Delay matters only if the sore becomes painful"}]'::jsonb, '["a"]', 'Penile cancer is often diagnosed late due to embarrassment and delay, so the nurse should encourage prompt evaluation. A non-healing penile lesion is a warning sign, not something expected to heal.'),
  ('male', 46, 'The nurse observes a UAP providing perineal care to an uncircumcised client. Which action by the UAP requires correction?', '[{"id": "a", "text": "Fully retracting the foreskin before cleaning"}, {"id": "b", "text": "Leaving the foreskin retracted after cleaning"}, {"id": "c", "text": "Cleaning under the foreskin with soap and water"}, {"id": "d", "text": "Performing penile hygiene as part of daily care"}]'::jsonb, '["b"]', 'Daily penile hygiene includes fully retracting the foreskin, cleaning with soap and water, and replacing the foreskin after cleaning. Leaving it retracted is incorrect.'),
  ('male', 47, 'The parent of a 12-year-old boy asks why the HPV vaccine (Gardasil) is recommended for boys. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It prevents undescended testicles.\""}, {"id": "b", "text": "\"It lowers the PSA level later in life.\""}, {"id": "c", "text": "\"It protects against HPV types linked to penile cancer.\""}, {"id": "d", "text": "\"It replaces the need for good penile hygiene.\""}]'::jsonb, '["c"]', 'The HPV vaccine protects against HPV 16 and 18, which cause penile cancer. Daily penile hygiene is still part of prevention.'),
  ('male', 48, 'Parents of a newborn boy ask whether circumcision is necessary to prevent penile cancer later in life. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, circumcision is required to prevent penile cancer.\""}, {"id": "b", "text": "\"No, circumcision has no effect on penile cancer risk.\""}, {"id": "c", "text": "\"Yes, uncircumcised males always develop penile cancer.\""}, {"id": "d", "text": "\"It lowers risk, but good hygiene is an alternative.\""}]'::jsonb, '["d"]', 'Circumcision reduces penile cancer risk but is not required if hygiene is maintained. Saying it has no effect is inaccurate because uncircumcised males have higher risk.'),
  ('male', 49, 'A client is diagnosed with invasive penile cancer. Which surgical procedure does the nurse anticipate?', '[{"id": "a", "text": "Partial or total penectomy"}, {"id": "b", "text": "Radical inguinal orchiectomy"}, {"id": "c", "text": "Radical prostatectomy"}, {"id": "d", "text": "Circumcision alone"}]'::jsonb, '["a"]', 'Partial or total penectomy is the treatment for invasive penile cancer. Radical inguinal orchiectomy treats testicular cancer, and radical prostatectomy treats prostate cancer.'),
  ('male', 50, 'A client''s penile biopsy shows early in-situ disease. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Total penectomy"}, {"id": "b", "text": "Laser therapy or topical chemotherapy"}, {"id": "c", "text": "Lymph node dissection with radiation"}, {"id": "d", "text": "Androgen deprivation therapy"}]'::jsonb, '["b"]', 'Laser therapy or topical chemotherapy is used for early in-situ penile disease. Penectomy is for invasive cancer, and radiation with lymph node dissection is for advanced disease.'),
  ('skin', 1, 'A 65-year-old client has a pearly lesion on the nose with a slightly depressed center and raised, rolled borders. The nurse recognizes these as characteristics of which condition?', '[{"id": "a", "text": "Squamous cell carcinoma"}, {"id": "b", "text": "Actinic keratosis"}, {"id": "c", "text": "Basal cell carcinoma"}, {"id": "d", "text": "Melanoma"}]'::jsonb, '["c"]', 'Basal cell carcinoma classically appears pearly or waxy with a slightly depressed center and raised, rolled borders. Squamous cell carcinoma is crusty, scaly, hard, and reddish-pink.'),
  ('skin', 2, 'A client who works outdoors has a crusty, scaly, hard, raised reddish-pink lesion on the lower lip. The nurse suspects which condition?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Actinic keratosis"}, {"id": "c", "text": "Squamous cell carcinoma"}, {"id": "d", "text": "Melanoma"}]'::jsonb, '["c"]', 'Squamous cell carcinoma appears as a crusty, scaly, hard raised reddish-pink lesion on sun-exposed areas including the lips. Basal cell carcinoma is pearly or waxy with rolled borders.'),
  ('skin', 3, 'A fair-skinned 72-year-old client has several rough, scaly, reddish-brown patches on the backs of both hands. The nurse recognizes these findings as most consistent with which condition?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Melanoma"}, {"id": "c", "text": "Actinic keratosis"}, {"id": "d", "text": "Marjolin''s ulcer"}]'::jsonb, '["c"]', 'Actinic keratosis appears as rough, scaly, reddish-brown patches on sun-damaged skin, most often in older adults with fair skin. Basal cell carcinoma is pearly with rolled borders, and melanoma is asymmetric and multicolored.'),
  ('skin', 4, 'During a skin assessment, which mole finding should the nurse report as a warning sign of melanoma?', '[{"id": "a", "text": "A mole with smooth, even edges"}, {"id": "b", "text": "A uniformly tan mole 4 mm across"}, {"id": "c", "text": "A symmetric mole unchanged for years"}, {"id": "d", "text": "A mole with ragged, notched edges"}]'::jsonb, '["d"]', 'Irregular, ragged, notched, or blurred borders are a melanoma warning sign; normal moles have smooth borders. A small, uniformly colored, symmetric, unchanging mole does not meet the ABCDE criteria.'),
  ('skin', 5, 'A client learning the ABCDE rule asks what the letter "A" means. Which response by the nurse is correct?', '[{"id": "a", "text": "\"The mole is larger than a pencil eraser.\""}, {"id": "b", "text": "\"The mole has changed in size or shape.\""}, {"id": "c", "text": "\"The mole has several colors within it.\""}, {"id": "d", "text": "\"One half of the mole does not match the other half.\""}]'::jsonb, '["d"]', 'A stands for asymmetry, meaning one half does not match the other. Size larger than a pencil eraser is D (diameter), and change over time is E (evolution).'),
  ('skin', 6, 'The nurse is assessing moles on a client''s back. Which color finding is most concerning for melanoma?', '[{"id": "a", "text": "A uniform tan color throughout one mole"}, {"id": "b", "text": "A uniform brown color throughout one mole"}, {"id": "c", "text": "An even light-brown color in one mole"}, {"id": "d", "text": "Black, red, and blue areas within one mole"}]'::jsonb, '["d"]', 'Multiple colors or color variation within one lesion, such as black, red, white, or blue, is a melanoma warning sign. Normal moles are a uniform tan or brown.'),
  ('skin', 7, 'The nurse measures four symmetric, uniformly colored moles with smooth borders that the client says have not changed. Which mole meets the diameter warning criterion of the ABCDE rule?', '[{"id": "a", "text": "A mole measuring 8 mm across"}, {"id": "b", "text": "A mole measuring 3 mm across"}, {"id": "c", "text": "A mole measuring 4 mm across"}, {"id": "d", "text": "A mole measuring 5 mm across"}]'::jsonb, '["a"]', 'The diameter criterion is a lesion larger than 6 mm, about the size of a pencil eraser. The other moles are smaller than 6 mm.'),
  ('skin', 8, 'A client reports that a long-standing mole has started to itch and bleed over the past month. Which ABCDE criterion does this finding represent?', '[{"id": "a", "text": "Evolution"}, {"id": "b", "text": "Asymmetry"}, {"id": "c", "text": "Border"}, {"id": "d", "text": "Diameter"}]'::jsonb, '["a"]', 'Evolution includes any change in size, shape, color, bleeding, crusting, or new symptoms such as itching or pain over time. Asymmetry, border, and diameter describe the lesion''s shape, edges, and size.'),
  ('skin', 9, 'The nurse has taught a client about the ABCDE rule. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I should report a mole bigger than a pencil eraser.\""}, {"id": "b", "text": "\"A normal mole usually has smooth borders.\""}, {"id": "c", "text": "\"A normal mole usually has several different colors.\""}, {"id": "d", "text": "\"I should report a mole that starts to itch.\""}]'::jsonb, '["c"]', 'Normal moles are a uniform tan or brown; multiple colors within one lesion is a melanoma warning sign. Size larger than a pencil eraser, smooth borders in normal moles, and new itching are all correct points.'),
  ('skin', 10, 'A client recently diagnosed with skin cancer asks which type of skin cancer is the most common. Which response by the nurse is correct?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Squamous cell carcinoma"}, {"id": "c", "text": "Melanoma"}, {"id": "d", "text": "Actinic keratosis"}]'::jsonb, '["a"]', 'Basal cell carcinoma is the most common type of skin cancer. Squamous cell carcinoma is the second most common, and actinic keratosis is precancerous rather than cancer.'),
  ('skin', 11, 'A client diagnosed with basal cell carcinoma on the cheek asks whether it will spread. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It spreads early to the lungs, brain, bones, and liver.\""}, {"id": "b", "text": "\"It is precancerous, so it is not actually a cancer yet.\""}, {"id": "c", "text": "\"It grows slowly and rarely spreads but can damage nearby tissue.\""}, {"id": "d", "text": "\"It rarely spreads, so it does not need any treatment.\""}]'::jsonb, '["c"]', 'Basal cell carcinoma grows slowly and rarely metastasizes but can cause local tissue destruction if untreated. Early spread to the lungs and brain describes melanoma.'),
  ('skin', 12, 'The nurse reviews biopsy results for four clients. Which diagnosis carries the greatest risk of early metastasis and death?', '[{"id": "a", "text": "Basal cell carcinoma"}, {"id": "b", "text": "Melanoma"}, {"id": "c", "text": "Squamous cell carcinoma"}, {"id": "d", "text": "Actinic keratosis"}]'::jsonb, '["b"]', 'Melanoma causes the most skin cancer deaths because of its tendency to metastasize early. Basal cell carcinoma rarely metastasizes, and squamous cell carcinoma has a moderate risk.'),
  ('skin', 13, 'A client with newly diagnosed actinic keratosis says, "So I have skin cancer." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is a melanoma that will need excision with wide margins.\""}, {"id": "b", "text": "\"It is precancerous and can become squamous cell carcinoma.\""}, {"id": "c", "text": "\"It is a harmless spot that will never need any treatment.\""}, {"id": "d", "text": "\"It is a basal cell carcinoma that rarely spreads to organs.\""}]'::jsonb, '["b"]', 'Actinic keratosis is not yet cancer; it is a precancerous lesion that can develop into squamous cell carcinoma if untreated. It must be treated and monitored, so it is not harmless.'),
  ('skin', 14, 'The nurse has taught a client about actinic keratosis. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"These patches could turn into squamous cell cancer.\""}, {"id": "b", "text": "\"Since it is not cancer yet, I can skip treating it.\""}, {"id": "c", "text": "\"These patches may itch, burn, or feel tender.\""}, {"id": "d", "text": "\"My provider may freeze them with liquid nitrogen.\""}]'::jsonb, '["b"]', 'Actinic keratosis must be treated and monitored because it can progress to squamous cell carcinoma. Itching or burning and cryotherapy with liquid nitrogen are accurate statements.'),
  ('skin', 15, 'A client is diagnosed with actinic keratosis on the scalp. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Wide excision with node biopsy"}, {"id": "b", "text": "Cryotherapy with liquid nitrogen"}, {"id": "c", "text": "Regional lymph node dissection"}, {"id": "d", "text": "Oral vemurafenib therapy"}]'::jsonb, '["b"]', 'Actinic keratosis is treated with cryotherapy, topical 5-FU, imiquimod, photodynamic therapy, or curettage. Wide excision with sentinel node biopsy and vemurafenib are used for melanoma.'),
  ('skin', 16, 'Which client report should the nurse expect when assessing a client with actinic keratosis?', '[{"id": "a", "text": "The lesion sometimes itches or burns"}, {"id": "b", "text": "The lesion has a pearly, waxy shine"}, {"id": "c", "text": "The lesion has many colors within it"}, {"id": "d", "text": "The lesion has a rolled, raised border"}]'::jsonb, '["a"]', 'Actinic keratosis may itch, burn, or feel tender. A pearly, waxy lesion with rolled borders describes basal cell carcinoma, and multiple colors suggest melanoma.'),
  ('skin', 17, 'Which assessment finding supports the nurse''s suspicion that a facial lesion is basal cell carcinoma?', '[{"id": "a", "text": "A rough, reddish-brown, scaly flat patch"}, {"id": "b", "text": "A hard, crusty, reddish-pink raised lesion"}, {"id": "c", "text": "A multicolored lesion with notched edges"}, {"id": "d", "text": "A translucent lesion with tiny dilated vessels"}]'::jsonb, '["d"]', 'Basal cell carcinoma is translucent with visible telangiectasias (dilated blood vessels). A hard, crusty, reddish-pink lesion describes squamous cell carcinoma.'),
  ('skin', 18, 'A client with basal cell carcinoma on the nose asks which procedure has the highest cure rate. Which response by the nurse is correct?', '[{"id": "a", "text": "Cryosurgery with liquid nitrogen"}, {"id": "b", "text": "Mohs micrographic surgery"}, {"id": "c", "text": "Electrodesiccation and curettage"}, {"id": "d", "text": "Topical 5-fluorouracil cream"}]'::jsonb, '["b"]', 'Mohs micrographic surgery has the highest cure rate and removes the cancer layer by layer. Cryosurgery, electrodesiccation and curettage, and topical agents are options for selected lesions.'),
  ('skin', 19, 'The nurse is preparing a client with basal cell carcinoma for treatment. Which treatment does the nurse anticipate as primary?', '[{"id": "a", "text": "Systemic chemotherapy infusions"}, {"id": "b", "text": "Radiation to the whole brain"}, {"id": "c", "text": "Surgical excision with clear margins"}, {"id": "d", "text": "Immunotherapy with pembrolizumab"}]'::jsonb, '["c"]', 'Surgical excision with clear margins is the primary treatment for basal cell carcinoma. Pembrolizumab immunotherapy is a melanoma treatment.'),
  ('skin', 20, 'A client whose basal cell carcinoma was excised says, "Now that it''s gone, I won''t need any more skin checks." Which response by the nurse is best?', '[{"id": "a", "text": "\"That''s right; this type of cancer never comes back.\""}, {"id": "b", "text": "\"Follow-up is needed only if it spreads to your lungs.\""}, {"id": "c", "text": "\"Skin checks are needed only after a melanoma diagnosis.\""}, {"id": "d", "text": "\"Regular follow-up matters because this cancer can recur.\""}]'::jsonb, '["d"]', 'Basal cell carcinoma is rarely fatal, but regular follow-up is important because of the risk of recurrence. It is not true that it never recurs.'),
  ('skin', 21, 'The nurse is reviewing four clients with squamous cell carcinoma. Which client has the greatest risk for metastasis?', '[{"id": "a", "text": "A client with a neglected lesion on the lip"}, {"id": "b", "text": "A client with a small forearm lesion removed early"}, {"id": "c", "text": "A client with a small hand lesion removed early"}, {"id": "d", "text": "A client with a small neck lesion removed early"}]'::jsonb, '["a"]', 'Squamous cell carcinoma can metastasize, especially if neglected or located on mucosal surfaces, ears, or lips. Small lesions removed early lack these risk features.'),
  ('skin', 22, 'A nursing student is comparing squamous cell carcinoma with basal cell carcinoma. Which statement by the student is accurate?', '[{"id": "a", "text": "\"Basal cell carcinoma grows faster and spreads early.\""}, {"id": "b", "text": "\"Squamous cell carcinoma is the most common skin cancer.\""}, {"id": "c", "text": "\"Squamous cell carcinoma is a precancerous skin lesion.\""}, {"id": "d", "text": "\"Squamous cell carcinoma grows faster and can metastasize.\""}]'::jsonb, '["d"]', 'Squamous cell carcinoma grows faster than basal cell carcinoma and has potential for metastasis. Basal cell carcinoma is the most common, and actinic keratosis is the precancerous lesion.'),
  ('skin', 23, 'The nurse is inspecting the oral cavity of a client at risk for skin cancer. Which skin cancer does the nurse recognize can arise on mucous membranes such as the mouth?', '[{"id": "a", "text": "Actinic keratosis"}, {"id": "b", "text": "Basal cell carcinoma"}, {"id": "c", "text": "Dysplastic nevus"}, {"id": "d", "text": "Squamous cell carcinoma"}]'::jsonb, '["d"]', 'Squamous cell carcinoma also arises on mucous membranes, including the oral cavity and genitals. Actinic keratosis occurs on sun-damaged skin, and basal cell carcinoma is most common on the face, ears, and nose.'),
  ('skin', 24, 'A client has squamous cell carcinoma on the ear. Which treatment does the nurse anticipate for this location?', '[{"id": "a", "text": "Topical imiquimod"}, {"id": "b", "text": "Watchful waiting"}, {"id": "c", "text": "Photodynamic therapy"}, {"id": "d", "text": "Mohs surgery"}]'::jsonb, '["d"]', 'Mohs surgery is used for squamous cell carcinoma in high-risk areas such as the face, ears, and lips. Topical imiquimod and photodynamic therapy are listed for actinic keratosis.'),
  ('skin', 25, 'A client asks when radiation therapy is used for squamous cell carcinoma. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"When surgery is not possible\""}, {"id": "b", "text": "\"As the standard first-line choice\""}, {"id": "c", "text": "\"Only for an actinic keratosis\""}, {"id": "d", "text": "\"Before every surgical excision\""}]'::jsonb, '["a"]', 'Radiation therapy is used for squamous cell carcinoma when surgery is not possible. Surgical excision is the standard first-line treatment.'),
  ('skin', 26, 'Squamous cell carcinoma has spread to a client''s regional lymph nodes. Which procedure does the nurse anticipate?', '[{"id": "a", "text": "Lymph node dissection"}, {"id": "b", "text": "Cryotherapy alone"}, {"id": "c", "text": "Topical 5-FU alone"}, {"id": "d", "text": "Curettage alone"}]'::jsonb, '["a"]', 'Lymph node dissection is performed for squamous cell carcinoma with regional spread. Cryotherapy, topical 5-FU, and curettage are local treatments listed for actinic keratosis and basal cell carcinoma, not for regional spread.'),
  ('skin', 27, 'A nursing student asks which cells give rise to melanoma. Which response by the nurse is correct?', '[{"id": "a", "text": "Basal cells in the stratum basale"}, {"id": "b", "text": "Squamous cells of the epidermis"}, {"id": "c", "text": "Fat cells of the hypodermis"}, {"id": "d", "text": "Melanocytes in the stratum basale"}]'::jsonb, '["d"]', 'Melanoma arises from mutated melanocytes in the stratum basale. Basal cells in the same layer give rise to basal cell carcinoma.'),
  ('skin', 28, 'A client with metastatic melanoma develops a new cough and dyspnea. The nurse recognizes possible spread to which site, the most common distant site of melanoma metastasis?', '[{"id": "a", "text": "Bones"}, {"id": "b", "text": "Lungs"}, {"id": "c", "text": "Brain"}, {"id": "d", "text": "Liver"}]'::jsonb, '["b"]', 'The lungs are the most common distant site of melanoma metastasis. Bones, brain, and liver are also metastatic sites but are not the most common.'),
  ('skin', 29, 'A client with melanoma is scheduled for a sentinel lymph node biopsy and asks its purpose. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It measures how deeply the tumor has invaded the skin.\""}, {"id": "b", "text": "\"It is the gold standard test to diagnose the melanoma.\""}, {"id": "c", "text": "\"It removes the main tumor with wide surgical margins.\""}, {"id": "d", "text": "\"It checks whether the cancer has spread to nearby nodes.\""}]'::jsonb, '["d"]', 'Sentinel lymph node biopsy assesses regional spread. Depth of invasion is measured as Breslow thickness, and skin biopsy is the gold standard for diagnosis.'),
  ('skin', 30, 'A client with melanoma asks what "Breslow thickness" on the pathology report means. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is the depth of invasion and helps predict outcome.\""}, {"id": "b", "text": "\"It is the width of the mole across the skin surface.\""}, {"id": "c", "text": "\"It is the number of colors found within the lesion.\""}, {"id": "d", "text": "\"It is the number of lymph nodes found with cancer.\""}]'::jsonb, '["a"]', 'Breslow thickness is the depth of invasion and is a key prognostic factor. Lesion width relates to the diameter criterion, and lymph node involvement is assessed by sentinel node biopsy.'),
  ('skin', 31, 'A client has a mole that meets several ABCDE criteria. Which diagnostic procedure does the nurse anticipate to confirm melanoma?', '[{"id": "a", "text": "Whole-body PET scan"}, {"id": "b", "text": "Sentinel node biopsy"}, {"id": "c", "text": "Excisional skin biopsy"}, {"id": "d", "text": "CT scan of the chest"}]'::jsonb, '["c"]', 'Skin biopsy is the gold standard for diagnosis, with excisional biopsy preferred for suspected melanoma. CT and PET are used for staging, and sentinel node biopsy assesses regional spread.'),
  ('skin', 32, 'A client is diagnosed with melanoma that has not spread. Which primary treatment does the nurse anticipate?', '[{"id": "a", "text": "Cryotherapy with liquid nitrogen"}, {"id": "b", "text": "Topical 5-fluorouracil cream"}, {"id": "c", "text": "Surgical excision with wide margins"}, {"id": "d", "text": "Electrodesiccation and curettage"}]'::jsonb, '["c"]', 'Surgical excision with wide margins is the primary treatment for melanoma. Cryotherapy, topical 5-FU, and electrodesiccation and curettage are listed for basal cell carcinoma or actinic keratosis.'),
  ('skin', 33, 'Testing shows that a client''s melanoma has a BRAF mutation. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Imiquimod cream"}, {"id": "b", "text": "Topical fluorouracil"}, {"id": "c", "text": "Vemurafenib"}, {"id": "d", "text": "Liquid nitrogen"}]'::jsonb, '["c"]', 'Targeted therapy with BRAF/MEK inhibitors such as vemurafenib is used for BRAF-mutant melanoma. Imiquimod, topical fluorouracil, and liquid nitrogen are treatments for superficial lesions and actinic keratosis.'),
  ('skin', 34, 'A client with melanoma is prescribed pembrolizumab. The nurse identifies this medication as which type of therapy?', '[{"id": "a", "text": "BRAF inhibitor therapy"}, {"id": "b", "text": "Immunotherapy"}, {"id": "c", "text": "Topical chemotherapy"}, {"id": "d", "text": "Cryotherapy"}]'::jsonb, '["b"]', 'Pembrolizumab, nivolumab, and ipilimumab are immunotherapy agents for melanoma. Vemurafenib, not pembrolizumab, is the BRAF/MEK inhibitor.'),
  ('skin', 35, 'The nurse is teaching a client about sun protection. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"I will garden from noon until 2 p.m. each day.\""}, {"id": "b", "text": "\"I will garden from 10 a.m. until noon each day.\""}, {"id": "c", "text": "\"I will garden before 10 a.m. or after 4 p.m.\""}, {"id": "d", "text": "\"I will garden from 1 p.m. until 3 p.m. each day.\""}]'::jsonb, '["c"]', 'Sun exposure should be avoided between 10 a.m. and 4 p.m., the peak UV radiation hours. The other times all fall within the peak UV window.'),
  ('skin', 36, 'A client asks when to apply sunscreen before a day at the beach. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Apply it 30 minutes before going outside.\""}, {"id": "b", "text": "\"Apply it after the first hour in the sun.\""}, {"id": "c", "text": "\"Apply it only once you notice redness.\""}, {"id": "d", "text": "\"Apply it just as you leave the beach.\""}]'::jsonb, '["a"]', 'Broad-spectrum sunscreen should be applied 30 minutes before going outside and reapplied every 2 hours. Waiting until after sun exposure or redness does not provide protection.'),
  ('skin', 37, 'The nurse has taught a client who works outdoors about sunscreen use. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"One application in the morning lasts all day.\""}, {"id": "b", "text": "\"I''ll reapply every 2 hours while I''m outdoors.\""}, {"id": "c", "text": "\"I''ll put it on 30 minutes before going outside.\""}, {"id": "d", "text": "\"I''ll use a broad-spectrum sunscreen product.\""}]'::jsonb, '["a"]', 'Sunscreen should be reapplied every 2 hours when outdoors, so one morning application is not enough. Applying 30 minutes before going out and using broad-spectrum sunscreen are correct.'),
  ('skin', 38, 'A client asks what sun protection factor (SPF) to look for when buying sunscreen. Which minimum SPF should the nurse recommend?', '[{"id": "a", "text": "SPF 4 or higher"}, {"id": "b", "text": "SPF 15 or higher"}, {"id": "c", "text": "SPF 8 or higher"}, {"id": "d", "text": "SPF 10 or higher"}]'::jsonb, '["b"]', 'Primary prevention includes broad-spectrum sunscreen with SPF of at least 15, with SPF 30 or higher preferred. The other values fall below the recommended minimum.'),
  ('skin', 39, 'A client says, "I use a tanning bed so I don''t burn in the real sun." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Tanning bed UV-A goes deeper and damages DNA.\""}, {"id": "b", "text": "\"Tanning beds are safe if used once a week.\""}, {"id": "c", "text": "\"Tanning beds give off only harmless light.\""}, {"id": "d", "text": "\"A base tan from a bed prevents skin cancer.\""}]'::jsonb, '["a"]', 'Tanning beds should be avoided because their UV-A penetrates deeper and causes DNA damage. Tanning beds emit UV-A and UV-B and are a skin cancer risk factor, not a protection.'),
  ('skin', 40, 'The nurse is teaching a client about protective clothing for outdoor work. Which choice should the nurse recommend?', '[{"id": "a", "text": "A wide-brimmed hat and long sleeves"}, {"id": "b", "text": "A tank top and shorts with no hat"}, {"id": "c", "text": "A short-sleeved shirt and no hat"}, {"id": "d", "text": "A sleeveless shirt and a visor"}]'::jsonb, '["a"]', 'Protective clothing includes a wide-brimmed hat, UV-blocking sunglasses, and long sleeves. The other choices leave sun-exposed skin uncovered.'),
  ('skin', 41, 'A parent asks why sun protection is so important for young children. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Children''s skin is protected from UV until puberty.\""}, {"id": "b", "text": "\"Childhood sunburns affect only the risk of wrinkles.\""}, {"id": "c", "text": "\"Even one severe childhood sunburn raises melanoma risk.\""}, {"id": "d", "text": "\"Only sunburns after age 18 affect melanoma risk.\""}]'::jsonb, '["c"]', 'Childhood sun protection is critical because even one severe childhood sunburn increases melanoma risk. Childhood sunburns are not limited to cosmetic effects.'),
  ('skin', 42, 'The nurse has taught a client how to perform a skin self-examination. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"Each year I''ll check only the skin on my face, arms, and hands.\""}, {"id": "b", "text": "\"Each month I''ll check my scalp, between my toes, and under my nails.\""}, {"id": "c", "text": "\"Each month I''ll check only the skin areas that get sun exposure.\""}, {"id": "d", "text": "\"Each year I''ll check any mole that has been bothering me lately.\""}]'::jsonb, '["b"]', 'Monthly self-examination should cover all skin surfaces, including the scalp, between the toes, and under the nails. Checking only sun-exposed areas or only once a year is incomplete.'),
  ('skin', 43, 'A client asks what is needed to perform a monthly skin self-examination at home. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A full-length mirror in a well-lit room\""}, {"id": "b", "text": "\"A small hand mirror in a dimly lit room\""}, {"id": "c", "text": "\"A magnifying glass in a darkened room\""}, {"id": "d", "text": "\"A handheld flashlight in a dark room\""}]'::jsonb, '["a"]', 'Clients should perform the monthly self-exam in a well-lit room using a full-length mirror. Dim or dark rooms do not allow adequate inspection.'),
  ('skin', 44, 'The nurse is giving discharge instructions after excision of a skin cancer. Which instruction should the nurse include?', '[{"id": "a", "text": "Let the wound dry out in direct sunlight"}, {"id": "b", "text": "Pick off any scab that forms on the site"}, {"id": "c", "text": "Leave the wound open with no bandage"}, {"id": "d", "text": "Keep the wound moist with petroleum jelly"}]'::jsonb, '["d"]', 'Petroleum jelly keeps the wound moist and promotes healing, followed by a non-stick bandage. The wound should be kept out of direct sun and should not be picked.'),
  ('skin', 45, 'Two days after cryotherapy of a skin lesion, which finding should the client be taught to report?', '[{"id": "a", "text": "A moist wound under the bandage"}, {"id": "b", "text": "A thin layer of petroleum jelly"}, {"id": "c", "text": "A non-stick bandage changed daily"}, {"id": "d", "text": "Increasing redness, pus, and fever"}]'::jsonb, '["d"]', 'Signs of infection to monitor include increased redness, warmth, swelling, purulent drainage, and fever. A moist wound under a non-stick bandage with petroleum jelly reflects correct wound care.'),
  ('skin', 46, 'The nurse observes a client caring for a healing excision site. Which action by the client requires correction?', '[{"id": "a", "text": "Changing the non-stick bandage on the site daily"}, {"id": "b", "text": "Sitting outside with the site uncovered in direct sun"}, {"id": "c", "text": "Applying a thin layer of petroleum jelly to the site"}, {"id": "d", "text": "Avoiding scratching or picking at the healing site"}]'::jsonb, '["b"]', 'The wound should be kept out of direct sun while healing. Daily non-stick bandage changes, petroleum jelly, and avoiding picking are correct actions.'),
  ('skin', 47, 'During a skin cancer screening, which client finding should the nurse identify as a risk factor for skin cancer?', '[{"id": "a", "text": "Daily use of SPF 30 sunscreen"}, {"id": "b", "text": "Red hair, blue eyes, and fair skin"}, {"id": "c", "text": "Avoiding sun from 10 a.m. to 4 p.m."}, {"id": "d", "text": "Monthly skin self-examinations"}]'::jsonb, '["b"]', 'Fair skin, light eyes, and red or blonde hair are personal risk factors for skin cancer. Daily sunscreen and avoiding peak sun hours are prevention measures.'),
  ('skin', 48, 'The nurse is caring for a client taking immunosuppressants after a kidney transplant. Which teaching about skin cancer is accurate?', '[{"id": "a", "text": "\"Your immunosuppression protects against skin cancer.\""}, {"id": "b", "text": "\"Your immunosuppression raises your skin cancer risk.\""}, {"id": "c", "text": "\"Only sun exposure affects your skin cancer risk.\""}, {"id": "d", "text": "\"Transplant recipients do not need skin checks.\""}]'::jsonb, '["b"]', 'Immunosuppression, such as after a transplant or with HIV, is a personal risk factor for skin cancer. Sun exposure is the number one risk, but it is not the only one.'),
  ('skin', 49, 'Which finding in a client''s history should the nurse recognize as a risk factor for skin cancer?', '[{"id": "a", "text": "Daily use of broad-spectrum sunscreen"}, {"id": "b", "text": "Living at sea level far from the equator"}, {"id": "c", "text": "A long-standing scar with chronic irritation"}, {"id": "d", "text": "Wearing a wide-brimmed hat outdoors"}]'::jsonb, '["c"]', 'Chronic skin irritation or scarring (Marjolin''s ulcer) is a skin cancer risk factor. Living closer to the equator or at higher altitude, not at sea level far from it, increases risk.'),
  ('skin', 50, 'A community group asks the nurse which factor contributes most to the development of skin cancer. Which response by the nurse is correct?', '[{"id": "a", "text": "Exposure to arsenic or coal tar at work"}, {"id": "b", "text": "Excessive exposure to UV radiation from the sun"}, {"id": "c", "text": "Exposure to ionizing radiation at work"}, {"id": "d", "text": "Having many atypical moles on the body"}]'::jsonb, '["b"]', 'Excessive sun exposure (UV radiation) is the number one risk factor for all skin cancers. Arsenic, coal tar, ionizing radiation, and atypical moles are additional risk factors but are not the leading one.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _cancer_seed_map m USING (source_key)
 CROSS JOIN _cancer_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _cancer_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Cancer seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
